-- Science Olympiad question-bank tables and source-of-truth seed data.
-- Generated from the committed TypeScript banks on 2026-09-13.
-- Runtime question loading intentionally remains TypeScript-only in Phase 1.

-- astronomy_questions: 48 rows

create table if not exists public.astronomy_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint astronomy_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint astronomy_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.astronomy_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('astro-q1', 'astronomy', 'sun-and-stars', 'What is the Sun?', '[{"id":"a","text":"A star"},{"id":"b","text":"A planet"},{"id":"c","text":"A moon"},{"id":"d","text":"A comet"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The Sun is a star: a giant ball of hot glowing gas. It looks huge because it is our closest star.', 'The Sun gives Earth heat and light, just like other twinkling lights in the night sky — only much closer.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q2', 'astronomy', 'sun-and-stars', 'Why do stars look like tiny points of light?', '[{"id":"a","text":"They are smaller than pebbles"},{"id":"b","text":"They are holes in the sky"},{"id":"c","text":"They are very far away"},{"id":"d","text":"They are sparks from the Sun"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Stars are enormous, but they are so far from Earth that they look like tiny points of light.', 'Think about a distant streetlight — it looks small even if it is actually large.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q3', 'astronomy', 'the-moon', 'What makes the Moon look bright in the night sky?', '[{"id":"a","text":"The Moon makes its own fire"},{"id":"b","text":"Sunlight reflecting off the Moon"},{"id":"c","text":"Earth''s shadow glowing"},{"id":"d","text":"Streetlights bouncing into space"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The Moon shines because sunlight hits its surface and bounces toward Earth. We call that reflected light.', 'The Moon does not make its own light the way the Sun does.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q4', 'astronomy', 'the-moon', 'About how long does the Moon take to travel once around Earth?', '[{"id":"a","text":"About one hour"},{"id":"b","text":"About one day"},{"id":"c","text":"About one month"},{"id":"d","text":"About one year"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Moon takes about one month to orbit Earth. That is why we see a cycle of Moon phases.', 'The Moon''s shape seems to change in a repeating pattern that lasts several weeks.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q5', 'astronomy', 'solar-system', 'Which planet do people live on?', '[{"id":"a","text":"Mars"},{"id":"b","text":"Venus"},{"id":"c","text":"Jupiter"},{"id":"d","text":"Earth"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Earth is our home planet. It is the only planet in our solar system known to have people living on it.', 'It is the planet with air to breathe, oceans, and a moon you can see at night.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q6', 'astronomy', 'solar-system', 'Which planet is famous for its big, bright rings?', '[{"id":"a","text":"Mercury"},{"id":"b","text":"Saturn"},{"id":"c","text":"Earth"},{"id":"d","text":"Mars"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Saturn is known for its bright rings, which are made of ice and rock pieces orbiting the planet.', 'Picture a pale gold planet wearing a wide halo.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q7', 'astronomy', 'solar-system', 'Why is Mercury so hot during its daytime?', '[{"id":"a","text":"It is the closest planet to the Sun"},{"id":"b","text":"It has the most volcanoes"},{"id":"c","text":"It is the biggest planet"},{"id":"d","text":"It has the most moons"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Mercury orbits closest to the Sun, so sunlight is much stronger there than on Earth.', 'Planets nearer the Sun receive more of the Sun''s energy.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q8', 'astronomy', 'day-night-seasons', 'Why do we have day and night on Earth?', '[{"id":"a","text":"The Sun turns off at night"},{"id":"b","text":"Earth rotates, or spins"},{"id":"c","text":"The Moon covers the Sun each evening"},{"id":"d","text":"Clouds hide the Sun until morning"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Earth spins once a day. The side facing the Sun has daytime; the side facing away has nighttime.', 'Think of a globe spinning in a flashlight beam — one side is lit, the other is dark.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q9', 'astronomy', 'day-night-seasons', 'Why does Earth have seasons?', '[{"id":"a","text":"Earth''s axis is tilted as it orbits the Sun"},{"id":"b","text":"The Moon blocks heat in winter"},{"id":"c","text":"The Sun changes color each month"},{"id":"d","text":"Clouds get thicker every fall"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Earth''s axis is tilted. As Earth orbits the Sun, different parts of the planet get more direct sunlight, which makes seasons.', 'Earth is not standing straight up and down as it travels around the Sun.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q10', 'astronomy', 'sun-and-stars', 'What does the Sun mainly give Earth that living things need?', '[{"id":"a","text":"A steady wind from space"},{"id":"b","text":"Light and heat"},{"id":"c","text":"A magnetic shield we can see"},{"id":"d","text":"Extra gravity for the oceans"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The Sun sends energy to Earth as light and heat. That energy warms the planet and lets plants make food.', 'Plants grow toward something the Sun sends, and a sunny sidewalk feels warm.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q11', 'astronomy', 'sun-and-stars', 'How is a star different from a planet?', '[{"id":"a","text":"A star is always smaller than a planet"},{"id":"b","text":"A star must have rings"},{"id":"c","text":"A star cannot have any gravity"},{"id":"d","text":"A star makes its own light"}]'::jsonb, 'd', 'multiple-choice', NULL, 'A star is a giant ball of hot gas that produces its own light. A planet shines only by reflecting light, usually from a star.', 'At night, stars twinkle with their own glow. Planets do not power themselves that way.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q12', 'astronomy', 'sun-and-stars', 'Why does the Sun look so much brighter than other stars in our sky?', '[{"id":"a","text":"It is much closer to Earth than those stars"},{"id":"b","text":"It is the only star that is made of firewood"},{"id":"c","text":"Other stars shine only during winter"},{"id":"d","text":"Earth''s atmosphere hides every star except the Sun"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Other stars can be as bright as the Sun, or even brighter, but they are vastly farther away. Distance makes the Sun dominate our daytime sky.', 'A nearby flashlight can outshine a huge stadium light that is many miles away.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q13', 'astronomy', 'sun-and-stars', 'What is a constellation?', '[{"id":"a","text":"A cloud of planets locked together by rings"},{"id":"b","text":"A family of moons that share one orbit"},{"id":"c","text":"A pattern of stars as they appear from Earth"},{"id":"d","text":"A group of stars that must all be the same distance away"}]'::jsonb, 'c', 'multiple-choice', NULL, 'A constellation is a pattern we imagine by connecting stars as they look from Earth. The stars in one picture are often at very different distances.', 'People named pictures in the night sky long before they could measure how far each star was.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q14', 'astronomy', 'sun-and-stars', 'Where does most of the Sun''s energy come from?', '[{"id":"a","text":"Burning coal in a crust around the Sun"},{"id":"b","text":"Hydrogen joining together in the Sun''s core"},{"id":"c","text":"Sunlight bouncing back from the Moon"},{"id":"d","text":"Meteors constantly hitting the Sun''s surface"}]'::jsonb, 'b', 'multiple-choice', NULL, 'In the Sun''s core, hydrogen nuclei join to make helium. That process, called fusion, releases the energy that eventually leaves the Sun as light and heat.', 'The Sun is not a campfire. Its center is so hot and squeezed that atoms can combine.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q15', 'astronomy', 'sun-and-stars', 'Why are stars hard to see in the daytime?', '[{"id":"a","text":"Stars stop shining whenever Earth faces the Sun"},{"id":"b","text":"The Moon covers the rest of the sky after sunrise"},{"id":"c","text":"Stars only exist on the night side of the galaxy"},{"id":"d","text":"Sunlight is so bright that it outshines them"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Stars shine day and night. In daytime the Sun''s light scatters through Earth''s air and overwhelms the fainter starlight, so we usually cannot see them.', 'The stars are still there. Something much closer is flooding the sky with light.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q16', 'astronomy', 'sun-and-stars', 'What does a light-year measure?', '[{"id":"a","text":"The distance light travels in one year"},{"id":"b","text":"How many hours a star shines each day"},{"id":"c","text":"The age of the Sun in Earth years"},{"id":"d","text":"How long a planet takes to spin once"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Light is fast, but space is huge. A light-year is the distance light can travel in one year. It is a unit of distance, not a unit of time.', 'The word has "year" in it, but astronomers use it when they talk about how far away something is.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q17', 'astronomy', 'sun-and-stars', 'How does the Sun''s size compare with Earth''s?', '[{"id":"a","text":"The Sun and Earth are about the same size"},{"id":"b","text":"Earth is much larger than the Sun"},{"id":"c","text":"The Sun is much larger than Earth"},{"id":"d","text":"The Sun is smaller, but hotter, than Earth"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Sun is a star, far larger than Earth. About one million Earths could fit inside the Sun''s volume.', 'Earth is only one of the objects going around the Sun. The object at the center has to be able to hold them with its gravity.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q18', 'astronomy', 'sun-and-stars', 'Two stars look equally bright from Earth. What could be true?', '[{"id":"a","text":"They must be the same size, temperature, and distance"},{"id":"b","text":"The nearer star could be giving off less light than the farther one"},{"id":"c","text":"Both stars must be closer than the Moon"},{"id":"d","text":"One star has to be a planet that only looks like a star"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Apparent brightness is not the same as how luminous a star truly is. A closer, less powerful star can look as bright as a more powerful star that is farther away.', 'Brightness in the sky depends on two things: how much light the star makes, and how far away it is.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q19', 'astronomy', 'sun-and-stars', 'If you could compare two stars that are the same size, which is hotter?', '[{"id":"a","text":"The redder-looking star"},{"id":"b","text":"The star that looks dimmest from Earth"},{"id":"c","text":"Color cannot tell you anything about temperature"},{"id":"d","text":"The bluer-looking star"}]'::jsonb, 'd', 'multiple-choice', NULL, 'A star''s color is a clue to its surface temperature. Bluer stars are hotter; redder stars are cooler. The Sun looks yellowish-white because its surface is in between.', 'Think of a stove burner: the hottest glow is not the deep red of a cooling coil.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q20', 'astronomy', 'the-moon', 'What is the Moon, compared with Earth?', '[{"id":"a","text":"Earth''s natural satellite"},{"id":"b","text":"A small star orbiting Earth"},{"id":"c","text":"A planet farther from the Sun than Mars"},{"id":"d","text":"A comet that got stuck in the sky"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The Moon is Earth''s natural satellite: a rocky world that orbits Earth. It is not a star and is not classified as a planet.', 'It stays with Earth and goes around us again and again.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q21', 'astronomy', 'the-moon', 'When we see a full moon, what is happening?', '[{"id":"a","text":"Earth is covering the Moon completely"},{"id":"b","text":"The Moon has moved inside Earth''s atmosphere"},{"id":"c","text":"The Moon''s sunlit side is facing Earth"},{"id":"d","text":"The Moon is making extra light of its own"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Sun always lights half of the Moon. At full moon, Earth is roughly between the Sun and Moon, so we see nearly all of that sunlit half.', 'The Moon is always half lit by the Sun. Full moon is about which half we can see.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q22', 'astronomy', 'the-moon', 'Why does the Moon seem to change shape over a month?', '[{"id":"a","text":"Earth''s shadow slowly nibbles the Moon each night"},{"id":"b","text":"We see different amounts of the Moon''s sunlit half"},{"id":"c","text":"The Moon melts and then freezes again"},{"id":"d","text":"Clouds on the Moon grow and shrink"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Moon phases happen because the Moon orbits Earth. We see more or less of the half that sunlight is hitting. The Moon itself is not changing size or being eaten by a shadow each night.', 'The Moon is a ball. From different places in its orbit, different slices of the bright half point toward us.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q23', 'astronomy', 'the-moon', 'What made most of the round pits on the Moon''s surface?', '[{"id":"a","text":"Volcanoes that still erupt every night"},{"id":"b","text":"Rivers that dried up long ago"},{"id":"c","text":"Wind carving the rock like Earth''s deserts"},{"id":"d","text":"Rocks from space striking the surface"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Most lunar craters are impact craters. Chunks of rock hit the Moon and blasted bowl-shaped holes. With almost no air or liquid water, those scars last a very long time.', 'The Moon has almost no air to burn those visitors up, and no weather to erase the marks quickly.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q24', 'astronomy', 'the-moon', 'What is the main reason Earth has ocean tides?', '[{"id":"a","text":"The Moon''s gravity pulls on Earth''s water"},{"id":"b","text":"The Sun turns off and on twice a day"},{"id":"c","text":"Earth''s spinning flings all water toward the equator"},{"id":"d","text":"Underwater volcanoes push the sea up and down"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The Moon''s gravity pulls more strongly on the side of Earth facing the Moon. That pull, together with Earth''s motion, makes the ocean bulge — the tides. The Sun also affects tides, but the Moon is the main driver.', 'High tide is not random. It follows a body that orbits Earth.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q25', 'astronomy', 'the-moon', 'Why do we always see the same face of the Moon from Earth?', '[{"id":"a","text":"The Moon does not rotate at all"},{"id":"b","text":"The Moon is glued to Earth''s sky"},{"id":"c","text":"The Moon rotates once in the same time it orbits Earth"},{"id":"d","text":"The far side of the Moon gives off no reflected light"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Moon rotates, but one spin takes the same time as one orbit. That match, called synchronous rotation, keeps the same hemisphere pointing toward Earth.', 'The Moon does spin. Its spin just matches its trip around Earth.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q26', 'astronomy', 'the-moon', 'Why does the Moon have almost no weather like Earth''s?', '[{"id":"a","text":"The Moon is too close to the Sun for clouds"},{"id":"b","text":"The Moon has almost no atmosphere"},{"id":"c","text":"The Moon''s oceans absorb all the wind"},{"id":"d","text":"Sunlight cannot reach the Moon"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Earth''s weather happens in a thick blanket of air. The Moon''s gravity is weaker and it holds almost no atmosphere, so it has no Earth-like wind, rain, or storms.', 'Weather needs air (and, on Earth, a lot of water). Check which of those the Moon is missing.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q27', 'astronomy', 'the-moon', 'During a total lunar eclipse, which object is in the middle?', '[{"id":"a","text":"The Sun"},{"id":"b","text":"The Moon"},{"id":"c","text":"Mars"},{"id":"d","text":"Earth"}]'::jsonb, 'd', 'multiple-choice', NULL, 'In a lunar eclipse, Earth is between the Sun and the Moon. Earth''s shadow falls on the Moon, so the full moon darkens — often turning reddish from sunlight bent through Earth''s air.', 'The Moon goes dim because something is blocking sunlight that would have hit it.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q28', 'astronomy', 'the-moon', 'During a total solar eclipse, which object is in the middle?', '[{"id":"a","text":"The Moon"},{"id":"b","text":"Earth"},{"id":"c","text":"The Sun"},{"id":"d","text":"Jupiter"}]'::jsonb, 'a', 'multiple-choice', NULL, 'In a solar eclipse, the Moon passes between the Sun and Earth and casts a shadow on Earth. The Moon is much smaller than the Sun, but it is much closer, so it can cover the Sun''s disk.', 'Daylight fades because something small, from our point of view, covers the Sun''s face.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q29', 'astronomy', 'the-moon', 'Why don''t we have a lunar eclipse every full moon?', '[{"id":"a","text":"The Sun is not always shining on the Moon"},{"id":"b","text":"Full moons only happen once every ten years"},{"id":"c","text":"The Moon''s orbit is tilted, so it often misses Earth''s shadow"},{"id":"d","text":"Earth''s shadow is too small to ever reach the Moon"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Moon''s orbit is tilted compared with Earth''s path around the Sun. Most months the Moon passes a little above or below Earth''s shadow, so there is no eclipse.', 'Full moon means the Moon is in the right direction, but it also has to line up in height, not just left-to-right.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q30', 'astronomy', 'solar-system', 'What do the planets in our solar system travel around?', '[{"id":"a","text":"The Moon"},{"id":"b","text":"The Sun"},{"id":"c","text":"The North Star"},{"id":"d","text":"The asteroid belt"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The planets orbit the Sun. The Sun''s gravity holds the solar system together.', 'Earth''s year is one complete trip around that central object.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q31', 'astronomy', 'solar-system', 'Which planet is the largest in our solar system?', '[{"id":"a","text":"Earth"},{"id":"b","text":"Mars"},{"id":"c","text":"Jupiter"},{"id":"d","text":"Mercury"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Jupiter is the largest planet. It is a gas giant, much more massive than Earth.', 'The biggest planet is a giant world far beyond Mars, not a rocky neighbor of Earth.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q32', 'astronomy', 'solar-system', 'How are the four inner planets different from the four outer planets?', '[{"id":"a","text":"The inner planets are mostly rocky; the outer planets are much larger and gassy or icy"},{"id":"b","text":"The inner planets all have rings; the outer planets have none"},{"id":"c","text":"The inner planets are stars; the outer planets are moons"},{"id":"d","text":"The inner planets take longer to orbit the Sun than the outer planets"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Mercury, Venus, Earth, and Mars are smaller, rocky worlds. Jupiter, Saturn, Uranus, and Neptune are giant planets made mostly of gas and ice, with thick atmospheres.', 'Think about what Mercury, Venus, Earth, and Mars are made of, then picture Jupiter and Saturn.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q33', 'astronomy', 'solar-system', 'What mainly keeps a planet moving in its path around the Sun?', '[{"id":"a","text":"A stream of air blowing from the Sun"},{"id":"b","text":"Magnetic tracks between the planets"},{"id":"c","text":"The planet''s moons pulling it forward"},{"id":"d","text":"The Sun''s gravity, together with the planet''s motion"}]'::jsonb, 'd', 'multiple-choice', NULL, 'A planet would fly off in a straight line if nothing pulled on it. The Sun''s gravity continually tugs the planet inward while the planet''s sideways motion keeps it from falling straight into the Sun, so the path is an orbit.', 'If you swing a ball on a string, two things matter: the pull toward the center, and the ball already moving.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q34', 'astronomy', 'solar-system', 'Where is the main asteroid belt in our solar system?', '[{"id":"a","text":"Between the Sun and Mercury"},{"id":"b","text":"Between Mars and Jupiter"},{"id":"c","text":"Just beyond the Moon''s orbit"},{"id":"d","text":"Inside Earth''s atmosphere"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Most asteroids in the main belt orbit the Sun between Mars and Jupiter. They are leftover rocky and metallic pieces from the solar system''s formation.', 'It sits between the last small rocky planet and the first giant planet.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q35', 'astronomy', 'solar-system', 'Venus is not the closest planet to the Sun, but it is the hottest. Why?', '[{"id":"a","text":"Venus has more volcanoes than any star"},{"id":"b","text":"Venus is the largest planet, so it holds more heat"},{"id":"c","text":"Venus has a thick atmosphere that traps heat"},{"id":"d","text":"Venus always faces the Sun on the same side"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Venus''s dense carbon dioxide atmosphere creates a strong greenhouse effect. Heat is trapped, so Venus''s surface is hotter than Mercury''s even though Mercury is closer to the Sun.', 'Distance from the Sun matters, but a planet''s air can act like a blanket.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q36', 'astronomy', 'solar-system', 'Why does Neptune take much longer than Earth to complete one trip around the Sun?', '[{"id":"a","text":"Neptune''s orbit is much larger, so the journey is longer"},{"id":"b","text":"Neptune is made of ice, which slows it down"},{"id":"c","text":"Neptune has to wait for all inner planets to finish first"},{"id":"d","text":"Neptune does not orbit the Sun"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Planets farther from the Sun travel on larger orbits and move more slowly. Neptune is much farther out than Earth, so one Neptune year lasts many Earth years.', 'A runner on the outside lane of a track has a longer loop to finish.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q37', 'astronomy', 'solar-system', 'What is the difference between a moon and a planet in our solar system?', '[{"id":"a","text":"Moons are always larger than planets"},{"id":"b","text":"Planets orbit moons, and moons orbit the Sun only"},{"id":"c","text":"Moons give off their own starlight; planets do not"},{"id":"d","text":"A planet orbits the Sun; a moon orbits a planet (or similar body)"}]'::jsonb, 'd', 'multiple-choice', NULL, 'In our solar system, planets orbit the Sun. Moons (natural satellites) orbit planets or some smaller bodies. Earth''s Moon orbits Earth while Earth orbits the Sun.', 'Ask what each object is going around.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q38', 'astronomy', 'solar-system', 'A comet grows a tail when it gets closer to the Sun. Which way does the tail generally point?', '[{"id":"a","text":"Toward the Sun, because heat pulls the tail inward"},{"id":"b","text":"Away from the Sun"},{"id":"c","text":"Always toward Earth, so we can see it"},{"id":"d","text":"Along the comet''s path, like the wake of a boat"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Sunlight and the solar wind push dust and gas away from the comet''s icy body. That is why a comet''s tail points generally away from the Sun, even if the comet is moving sideways or outward.', 'The tail is pushed by energy and particles coming from the Sun, not by the comet dragging air behind it.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q39', 'astronomy', 'day-night-seasons', 'About how long does Earth take to orbit the Sun once?', '[{"id":"a","text":"One day"},{"id":"b","text":"One month"},{"id":"c","text":"One year"},{"id":"d","text":"One hour"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Earth takes about 365 days — one year — to complete one orbit around the Sun.', 'Your birthday comes after Earth has finished that trip.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q40', 'astronomy', 'day-night-seasons', 'Why does the Sun appear to rise in the east?', '[{"id":"a","text":"Earth rotates from west to east"},{"id":"b","text":"The Sun orbits Earth once each morning"},{"id":"c","text":"The Moon pushes the Sun upward"},{"id":"d","text":"East is always the hottest direction in space"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Earth rotates toward the east. Because we ride a spinning planet, the Sun appears to climb in the east and set in the west.', 'The Sun is not racing around us each day. We are the ones turning.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q41', 'astronomy', 'day-night-seasons', 'What is the difference between Earth''s rotation and Earth''s revolution?', '[{"id":"a","text":"They are two names for the same spinning motion"},{"id":"b","text":"Rotation is Earth''s trip around the Sun; revolution is Earth spinning"},{"id":"c","text":"Rotation happens only at night; revolution happens only in summer"},{"id":"d","text":"Rotation is Earth spinning; revolution is Earth orbiting the Sun"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Rotation is Earth spinning on its axis, which causes day and night. Revolution (orbit) is Earth traveling around the Sun, which takes about a year.', 'One motion makes day and night. The other motion, together with tilt, is tied to the year.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q42', 'astronomy', 'day-night-seasons', 'A student says summer happens because Earth is closer to the Sun. Why is that idea wrong?', '[{"id":"a","text":"Earth does not orbit the Sun at all"},{"id":"b","text":"Earth''s distance from the Sun changes only a little, and the nearest point is not northern summer"},{"id":"c","text":"The Sun is closer in winter for every place on Earth"},{"id":"d","text":"Seasons are caused only by clouds"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Earth''s orbit is only slightly oval. The small change in distance is not what makes seasons, and Earth is actually a bit nearer the Sun in early January. Seasons come from the tilt of Earth''s axis, which changes how directly sunlight hits each hemisphere.', 'If closeness were the whole story, the whole Earth would have summer at the same time.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q43', 'astronomy', 'day-night-seasons', 'When it is summer in the United States, what is usually true in Australia?', '[{"id":"a","text":"Australia has summer too, because the whole planet is closer to the Sun"},{"id":"b","text":"Australia has no seasons because it is in the south"},{"id":"c","text":"Australia is having winter"},{"id":"d","text":"Australia is having night for several months"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Earth''s axis tilt means the Northern and Southern Hemispheres get opposite seasons. When the north is tilted toward the Sun, the south is tilted away.', 'Tilt leans one hemisphere toward the Sun while the other leans away.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q44', 'astronomy', 'day-night-seasons', 'Your shadow is much longer at 8 a.m. than at noon. Why?', '[{"id":"a","text":"The Sun is lower in the sky in the morning"},{"id":"b","text":"The Moon blocks more sunlight at noon"},{"id":"c","text":"Earth is farther from the Sun at breakfast time"},{"id":"d","text":"Shadows only form when the air is cold"}]'::jsonb, 'a', 'multiple-choice', NULL, 'When the Sun is low, its rays hit the ground at a shallow angle and stretch shadows. Near noon the Sun is higher, so shadows shrink.', 'Hold a flashlight high over a pencil, then low from the side, and watch the shadow.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q45', 'astronomy', 'day-night-seasons', 'How does Earth''s tilted axis help create seasons?', '[{"id":"a","text":"It makes the Sun stronger in space during July only"},{"id":"b","text":"It stops Earth from rotating in winter"},{"id":"c","text":"It moves Earth closer to the Moon each summer"},{"id":"d","text":"It changes how directly sunlight hits a hemisphere during the year"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Because Earth is tilted, one hemisphere leans toward the Sun for part of the orbit. That hemisphere gets more direct sunlight and longer days — summer — while the other gets winter.', 'Summer feels warmer where sunlight is more concentrated and days last longer.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q46', 'astronomy', 'day-night-seasons', 'Near the Arctic Circle in summer, why can daylight last most of the 24-hour day?', '[{"id":"a","text":"The Sun moves closer to Earth in June"},{"id":"b","text":"That region stays tilted toward the Sun as Earth spins"},{"id":"c","text":"The Moon reflects sunlight all night in summer"},{"id":"d","text":"Clouds store daylight and release it after sunset"}]'::jsonb, 'b', 'multiple-choice', NULL, 'In northern summer the Arctic is tilted toward the Sun. As Earth rotates, places far enough north can remain in sunlight for a very long time — even 24 hours at midsummer farther north.', 'If a tilted globe''s top stays in the lamp''s light while you spin it, that top may not enter the shadow.', NULL, NULL, NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q47', 'astronomy', 'day-night-seasons', 'Why are days longer in summer than in winter where you live (away from the equator)?', '[{"id":"a","text":"Earth rotates more slowly in summer"},{"id":"b","text":"The Sun shines for extra hours because it is hotter"},{"id":"c","text":"Your hemisphere is tilted toward the Sun, so it stays in sunlight longer each spin"},{"id":"d","text":"Winter nights are longer because the Moon is out more"}]'::jsonb, 'c', 'multiple-choice', NULL, 'When your hemisphere tilts toward the Sun, you spend more of each rotation in daylight. When it tilts away, nights last longer. Earth''s spin rate does not make summer days long.', 'The length of daylight is about how much of Earth''s spin you spend on the sunlit side.', NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
('astro-q48', 'astronomy', 'day-night-seasons', 'If it is daytime where you are, what is most likely true on the opposite side of Earth?', '[{"id":"a","text":"It is also daytime, because the Sun lights the whole planet at once"},{"id":"b","text":"It is summer there, no matter the month"},{"id":"c","text":"That side is facing the Moon instead of the Sun"},{"id":"d","text":"It is nighttime there"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Earth is a sphere. The Sun lights roughly half of it at a time. The opposite side faces away from the Sun, so it is night there.', 'Earth is a ball. Only about half of a ball can face a lamp at one time.', NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);

create index if not exists astronomy_questions_topic_id_idx on public.astronomy_questions (topic_id);
create index if not exists astronomy_questions_verification_status_idx on public.astronomy_questions (verification_status);

-- entomology_questions: 60 rows

create table if not exists public.entomology_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint entomology_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint entomology_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.entomology_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('ento-q1', 'entomology', 'taxonomy', 'Which order includes both cockroaches and termites?', '[{"id":"a","text":"Mantodea"},{"id":"b","text":"Blattodea"},{"id":"c","text":"Orthoptera"},{"id":"d","text":"Coleoptera"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The 2027 list gives Order Blattodea the common names cockroaches/termites. Mantodea is mantids; Orthoptera is printed as grasshoppers & crickets; Coleoptera is printed as beetles.', 'Look at the official common names printed next to that order.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Order Blattodea — cockroaches/termites.', NULL, '["Blattodea"]'::jsonb),
('ento-q2', 'entomology', 'taxonomy', 'What common names are listed for Subclass Collembola?', '[{"id":"a","text":"diplurans"},{"id":"b","text":"silverfish, firebrats"},{"id":"c","text":"thrips"},{"id":"d","text":"springtails, snow fleas"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The list prints Collembola as springtails, snow fleas. Diplurans are Order Diplura; silverfish and firebrats are Zygentoma; thrips are Thysanoptera.', 'Collembola is a subclass under Class Entognatha, not an insect order.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Subclass Collembola — springtails, snow fleas.', NULL, '["Collembola","Entognatha"]'::jsonb),
('ento-q3', 'entomology', 'visual-id', '[IMAGE REQUIRED: eight-legged arthropod with a fused body.] Look at the photo. How is this animal classified?', '[{"id":"a","text":"As an insect order in Class Insecta"},{"id":"b","text":"As a beetle family in Coleoptera"},{"id":"c","text":"As a true-bug family in Hemiptera"},{"id":"d","text":"As a non-insect arthropod family"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Ixodidae is listed under Non-Insect Arthropods with the common name hardback ticks. It is not an insect order or a beetle or true-bug family. Eight walking legs and a fused body are visible in the photo; those characters are not printed on the 2027 list.', 'Count the walking legs and find the list heading that is separate from Class Insecta.', NULL, NULL, NULL, 1, true, '/entomology/ento-q3.jpg', 'Photograph of a small arthropod on dry grass with eight walking legs and a flattened, fused body.', NULL, 'Hard tick in dorsal view: eight legs, fused body, no three insect tagmata. Not a beetle, true bug, or insect order.', 'verified', 'recognition', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Non-Insect Arthropods, Family Ixodidae — hardback ticks. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Ixodidae"]'::jsonb),
('ento-q4', 'entomology', 'taxonomy', 'Mayflies belong to which order?', '[{"id":"a","text":"Odonata"},{"id":"b","text":"Plecoptera"},{"id":"c","text":"Ephemeroptera"},{"id":"d","text":"Trichoptera"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Ephemeroptera is printed as mayflies. Odonata is dragon/damselflies; Plecoptera is stoneflies; Trichoptera is caddisflies.', 'Dragon/damselflies, stoneflies, and caddisflies are different listed orders.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Order Ephemeroptera — mayflies.', NULL, '["Ephemeroptera"]'::jsonb),
('ento-q5', 'entomology', 'visual-id', '[IMAGE REQUIRED: hairy flower-visiting insect with two pairs of wings.] Which family is this insect?', '[{"id":"a","text":"Bombyliidae — bee flies"},{"id":"b","text":"Formicidae — ants"},{"id":"c","text":"Apidae — bees"},{"id":"d","text":"Vespidae — paper wasps, hornets, yellowjackets"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Apidae is printed as bees under Hymenoptera. Bee flies (Bombyliidae) are a listed Diptera family. Ants are Formicidae; paper wasps, hornets, and yellowjackets are Vespidae.', 'Among listed Hymenoptera families, match the specimen to its official common name. Do not pick bee flies.', NULL, NULL, NULL, 2, true, '/entomology/ento-q5.jpg', 'Photograph of a hairy insect with banded abdomen visiting purple flowers.', NULL, 'Honey bee on flowers: hairy thorax, two pairs of wings, no long rigid bee-fly proboscis. Not an ant or a paper wasp.', 'verified', 'recognition', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Family Apidae — bees. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Apidae","Hymenoptera"]'::jsonb),
('ento-q6', 'entomology', 'visual-id', '[IMAGE REQUIRED: worker ant in side view.] Which family is this insect?', '[{"id":"a","text":"Vespidae — paper wasps, hornets, yellowjackets"},{"id":"b","text":"Formicidae — ants"},{"id":"c","text":"Cynipidae — gall wasps"},{"id":"d","text":"Apidae — bees"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Ants are family Formicidae in Hymenoptera. Wasps, gall wasps, and bees are other listed hymenopteran families with different body plans.', 'Among listed Hymenoptera families, match the specimen to its official common name. Do not pick bees, gall wasps, or paper wasps.', NULL, NULL, NULL, 1, true, '/entomology/ento-q6.jpg', 'Side-view photograph of a pinned insect with a narrow waist between the middle and rear body sections.', NULL, 'Clear side view of a worker ant: distinct head, thorax, petiole (narrow waist), and gaster; elbowed antennae; no wasp-like folded wings required. Not a bee (no pollen baskets / hairy bee shape) and not a paper wasp.', 'verified', 'recognition', 'generated', 'Official Formicidae common name. Wikimedia Commons specimen photo (see public/entomology/README.md). No taxon name on the image.', NULL, '["Formicidae","Hymenoptera"]'::jsonb),
('ento-q7', 'entomology', 'visual-id', '[IMAGE REQUIRED: butterfly with tailed hindwings.] Look at the photo. Which family is this butterfly?', '[{"id":"a","text":"Nymphalidae — brush-footed butterflies"},{"id":"b","text":"Saturniidae — Giant Silkworm moths"},{"id":"c","text":"Papilionidae — swallowtails"},{"id":"d","text":"No listed moth or butterfly family has hindwing tails"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Papilionidae (swallowtails) often have tail-like projections on the hindwings. Saturniidae are Giant Silkworm moths; Nymphalidae are brush-footed butterflies. Tails are a useful clue among the three listed lepidopteran families, not a proof for every swallowtail species.', 'Among the three listed Lepidoptera families, match the specimen to its official common name. Do not pick Giant Silkworm moths.', NULL, NULL, NULL, 2, true, '/entomology/ento-q7.jpg', 'Photograph of a butterfly with its wings open. A yellow circle marks thin projections on the hindwings.', NULL, 'Dorsal view of a swallowtail butterfly with obvious hindwing tails, clubbed antennae, and scaled wings. Do not use a saturniid moth (feathery antennae, no swallowtail tails) or a nymphalid without tails.', 'verified', 'recognition', 'generated', 'Official Papilionidae common name. Wikimedia Commons photo (see public/entomology/README.md); yellow circle marks hindwing projections only.', NULL, '["Papilionidae","Lepidoptera"]'::jsonb),
('ento-q8', 'entomology', 'visual-id', '[IMAGE REQUIRED: aquatic bug swimming upside down at the water surface.] Which listed family is this?', '[{"id":"a","text":"Notonectidae — backswimmers"},{"id":"b","text":"Corixidae — water boatmen"},{"id":"c","text":"Dytiscidae — predaceous diving beetles"},{"id":"d","text":"Hydrophilidae — water scavenger"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Notonectidae is printed as backswimmers. Orientation in the photo is not a list fact. Corixidae is printed as water boatmen. Dytiscidae and Hydrophilidae (water scavenger) are Coleoptera families, not Hemiptera.', 'Match the swimming pose in the photo to a listed aquatic family. Do not pick beetle families if the specimen is a true bug.', NULL, NULL, NULL, 2, true, '/entomology/ento-q8.jpg', 'Photograph of an aquatic insect swimming just under the water surface with its belly toward the surface and long hind legs.', NULL, 'Live or photo of a backswimmer at the surface, clearly oriented belly-up (keel/dorsum downward), long oar-like hind legs. Must not be a water boatman swimming right-side up or a beetle with elytra.', 'verified', 'recognition', 'generated', 'Official Notonectidae common name. Wikimedia Commons photo (see public/entomology/README.md). No taxon name on the image.', NULL, '["Notonectidae","Hemiptera"]'::jsonb),
('ento-q9', 'entomology', 'visual-id', '[IMAGE REQUIRED: beetle with a distinct snout.] Which listed family is this?', '[{"id":"a","text":"Tenebrionidae — darkling beetles"},{"id":"b","text":"Scarabaeidae — dung beetles"},{"id":"c","text":"Coccinellidae — lady-bird beetles (ladybugs)"},{"id":"d","text":"Curculionidae — weevils"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Curculionidae is printed as weevils. The snout diagnostic is not on the 2027 list. Tenebrionidae, Scarabaeidae, and Coccinellidae (lady-bird beetles(ladybugs)) are other listed beetle families.', 'Among listed beetle families, match the specimen to its official common name. Do not pick lady-bird beetles or dung beetles.', NULL, NULL, NULL, 2, true, '/entomology/ento-q9.jpg', 'Photograph of a beetle with a long snout on the front of the head.', NULL, 'Dorsal or three-quarter view of an adult weevil with a clear rostrum (snout) and clubbed/elbowed antennae arising from the snout. Not a round ladybug, not a scarab, not a smooth darkling beetle without a snout.', 'verified', 'recognition', 'generated', 'Official Curculionidae common name. Wikimedia Commons photo (see public/entomology/README.md). No taxon name on the image.', NULL, '["Curculionidae","Coleoptera"]'::jsonb),
('ento-q10', 'entomology', 'visual-id', '[IMAGE REQUIRED: tiny six-legged arthropod with a forked jumping organ under the abdomen, no wings.] What is the best identification?', '[{"id":"a","text":"Order Zygentoma — silverfish, firebrats"},{"id":"b","text":"Subclass Collembola — springtails, snow fleas"},{"id":"c","text":"Order Diplura — diplurans"},{"id":"d","text":"Order Thysanoptera — thrips"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Springtails (Collembola) are Class Entognatha. Many have a furcula used to jump. Silverfish are wingless insects (Zygentoma). Diplurans have paired tail filaments, not a ventral jumping fork. Thrips are slender insects in Thysanoptera, often with fringe wings as adults.', 'This taxon is listed under Entognatha, not as an insect order.', NULL, NULL, NULL, 3, true, '/entomology/ento-q10.jpg', 'Two photographs labeled A and B: a tiny wingless six-legged arthropod, and a close-up of a forked structure from under the abdomen.', NULL, 'Close-up of a springtail showing six legs, no wings, and a visible furcula (forked jumping structure) folded under the abdomen. Not a silverfish (flat, tapered, terminal filaments) and not a dipluran (two long cerci).', 'verified', 'distinction', 'generated', 'Official Collembola listing. Wikimedia Commons photo (see public/entomology/README.md). No taxon name on the image.', NULL, '["Collembola","Entognatha"]'::jsonb),
('ento-q11', 'entomology', 'comparison', 'Water boatmen (Corixidae) and backswimmers (Notonectidae) are both listed aquatic Hemiptera. Which statement best separates them?', '[{"id":"a","text":"Only water boatmen have six legs; backswimmers have eight."},{"id":"b","text":"Backswimmers typically swim on their backs; water boatmen typically swim dorsal-side up."},{"id":"c","text":"Water boatmen are beetles; backswimmers are true bugs."},{"id":"d","text":"Backswimmers belong to Coleoptera; water boatmen belong to Odonata."}]'::jsonb, 'b', 'multiple-choice', NULL, 'Both families are Hemiptera (true bugs) with six legs. The usual field split is orientation: Notonectidae often swim ventral-side up; Corixidae usually keep the back upward. Neither is a beetle or a dragonfly.', 'Use the official common name “backswimmers” as a clue.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'distinction', 'generated', 'Same taxon pair as Sample Test 1 style, new stem. Orientation diagnostic: needs-review for production photos/wording.', NULL, '["Corixidae","Notonectidae","Hemiptera"]'::jsonb),
('ento-q12', 'entomology', 'comparison', '[IMAGE REQUIRED: two aquatic beetles labeled A and B.] Look at beetles A and B. Which statement matches what you see?', '[{"id":"a","text":"A has clubbed antennae (Hydrophilidae); B has threadlike antennae (Dytiscidae)"},{"id":"b","text":"Both are Lampyridae because they glow underwater"},{"id":"c","text":"A has threadlike antennae (Dytiscidae); B has clubbed antennae (Hydrophilidae)"},{"id":"d","text":"Both are Curculionidae because they live in water"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Dytiscidae is printed as predaceous diving beetles; Hydrophilidae is printed as water scavenger. Threadlike vs clubbed antennae and palps are not official-list facts. Lampyridae is fireflies; Curculionidae is weevils.', 'Match each beetle to its official 2027 family common name. Antenna characters are not printed on the list.', NULL, NULL, NULL, 3, true, '/entomology/ento-q12.jpg', 'Two photographs of aquatic beetles labeled A and B.', NULL, 'Side-by-side adults: (1) dytiscid with visible filiform antennae and oar-like hind legs; (2) hydrophilid with short clubbed antennae and prominent palps, often a convex underside. Labels optional; diagnostics must be visible.', 'verified', 'distinction', 'generated', 'Official Dytiscidae and Hydrophilidae common names. Wikimedia Commons photos (see public/entomology/README.md); A/B labels only.', NULL, '["Dytiscidae","Hydrophilidae","Coleoptera"]'::jsonb),
('ento-q13', 'entomology', 'comparison', '[IMAGE REQUIRED: two flies labeled A and B.] Look at flies A and B. Which choice correctly names them, including the mosquito family?', '[{"id":"a","text":"A and B are crane flies (Tipulidae); mosquitoes (Culicidae) are not shown."},{"id":"b","text":"A and B are both bee flies (Bombyliidae)."},{"id":"c","text":"One is a mosquito (Culicidae) and one is a crane fly (Tipulidae)."},{"id":"d","text":"A and B are both blow flies (Calliphoridae)."}]'::jsonb, 'c', 'multiple-choice', NULL, 'Tipulidae are crane flies; Culicidae are mosquitoes. Adult crane flies do not have the scaled wings and piercing proboscis of mosquitoes. Bee flies and blow flies are other listed Diptera families with different shapes.', 'Crane flies are often mistaken for mosquitoes but are a different listed family.', NULL, NULL, NULL, 3, true, '/entomology/ento-q13.jpg', 'Two photographs of flies labeled A and B. No extra labels on the mouthparts.', NULL, 'Two adult flies to scale: a crane fly (very long legs, no long piercing proboscis, often V-shaped wing marking) and a mosquito (proboscis, scaled wing veins, shorter legs relative to crane flies). Not bee flies or blow flies.', 'verified', 'distinction', 'generated', 'Official Tipulidae and Culicidae common names. Wikimedia Commons photos (see public/entomology/README.md); A/B labels only, no mouthpart circles.', NULL, '["Tipulidae","Culicidae","Diptera"]'::jsonb),
('ento-q14', 'entomology', 'external-anatomy', 'An adult insect’s body is divided into which three main regions?', '[{"id":"a","text":"Head, thorax, and abdomen"},{"id":"b","text":"Head, neck, and tail"},{"id":"c","text":"Cephalothorax and abdomen only"},{"id":"d","text":"Proboscis, elytra, and cerci"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Insects have three main body regions: head, thorax, and abdomen. Proboscis, elytra, and cerci are parts, not those three regions. Family Ixodidae is listed under Non-Insect Arthropods, so do not treat ticks as if they used this insect body plan.', 'Ticks (Ixodidae) are built differently; think of a bee or a beetle.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Insect tagmata are in CURRICULUM_2027.md as expected knowledge (inferred/sample), not an official structure checklist in RULES_2027.md.', NULL, '["Insecta","Ixodidae"]'::jsonb),
('ento-q15', 'entomology', 'external-anatomy', 'What is one important job of an insect’s exoskeleton?', '[{"id":"a","text":"It pumps blood the way a human heart does"},{"id":"b","text":"It lets the insect hear only ultrasonic bat calls"},{"id":"c","text":"It supports the body and gives muscles a place to attach"},{"id":"d","text":"It stores pollen in every insect family"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The exoskeleton (cuticle) supports the body, protects internal parts, and is the attachment surface for muscles. It is not a heart, and pollen baskets are not universal.', 'Think of armor that is also a skeleton on the outside.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Exoskeleton function is curriculum/sample-adjacent, not an official organ checklist in RULES_2027.md.', NULL, '["Insecta"]'::jsonb),
('ento-q16', 'entomology', 'external-anatomy', 'Where do an adult insect’s three pairs of walking legs attach?', '[{"id":"a","text":"On the thorax"},{"id":"b","text":"On the abdomen"},{"id":"c","text":"On the head"},{"id":"d","text":"One pair on the head, thorax, and abdomen"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Adult insects have three pairs of walking legs attached on the thorax. Those walking pairs are not described as attaching to the head or abdomen.', 'Walking legs attach on the middle body region, not on the head or abdomen.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Thoracic leg attachment is curriculum/sample-adjacent (CURRICULUM_2027.md), not a restated official checklist.', NULL, '["Insecta"]'::jsonb),
('ento-q17', 'entomology', 'external-anatomy', '[IMAGE REQUIRED: labeled insect rear end.] When an insect has cerci, where are they?', '[{"id":"a","text":"On the antennae"},{"id":"b","text":"On the tarsi of the front legs"},{"id":"c","text":"At the end of the abdomen"},{"id":"d","text":"Inside the compound eyes"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Cerci arise at the posterior end of the abdomen. They are not parts of the antennae, tarsi, or eyes.', 'Look at the circled pair of structures. Do not pick antennae or eyes.', NULL, NULL, NULL, 2, true, '/entomology/ento-q17.jpg', 'Photograph of an insect. A yellow circle marks a pair of structures at the rear of the body.', NULL, 'Simple side or dorsal diagram of an insect with the abdomen tip highlighted, showing a pair of cerci. Do not label antennae as cerci. Optional: a dipluran for contrast, clearly not required for the correct choice.', 'verified', 'recognition', 'generated', 'Cerci location is sample-adjacent. Wikimedia Commons photo (see public/entomology/README.md); yellow circle marks the rear pair only, without naming them.', NULL, '["Insecta"]'::jsonb),
('ento-q18', 'entomology', 'dichotomous-keys', 'Use this key.

1a. Aquatic true bug that swims at the surface → go to 2
1b. Not an aquatic true bug → stop; not in this key
2a. Usually swims on its back → Notonectidae
2b. Usually swims right-side up → Corixidae

A water bug is swimming on its back. Which family does the key give?', '[{"id":"a","text":"Corixidae"},{"id":"b","text":"Notonectidae"},{"id":"c","text":"Dytiscidae"},{"id":"d","text":"The key cannot finish; this animal is a beetle, not a true bug"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Couplet 1 keeps aquatic Hemiptera. Couplet 2a matches swimming on the back → Notonectidae. Dytiscidae are beetles (Coleoptera), so 1b would exclude them if you treated them as not aquatic true bugs. Beetles are not Hemiptera.', 'Follow couplet 1, then couplet 2 using swimming orientation.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'needs-review', 'multi-step', 'generated', 'Keys are in official 2027 scope (description will / competition may). Original key. Orientation couplet is not on the official list.', NULL, '["Notonectidae","Corixidae","Hemiptera"]'::jsonb),
('ento-q19', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Listed common name is short-horned grasshoppers → Acrididae
1b. Any other grasshopper or cricket name → go to 2
2a. Listed common name is katydids → Tettigoniidae
2b. Listed common name is crickets/tree crickets → Gryllidae

A specimen’s listed common name is short-horned grasshoppers. Which family do you reach?', '[{"id":"a","text":"Tettigoniidae"},{"id":"b","text":"Gryllidae"},{"id":"c","text":"Acrididae"},{"id":"d","text":"Membracidae"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Couplet 1a matches the official common name short-horned grasshoppers → Acrididae. Couplet 2 is only for the other listed Orthoptera families. Membracidae are treehoppers (Hemiptera), so they are not in this key.', 'Start at couplet 1 using the official common-name string, not a look-alike Hemiptera family.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Orthoptera family official common names.', NULL, '["Acrididae","Tettigoniidae","Gryllidae","Orthoptera"]'::jsonb),
('ento-q20', 'entomology', 'dichotomous-keys', 'You are making a simple two-step key for these listed groups only: Dytiscidae, Hydrophilidae, Acrididae, and Gryllidae. What is the best first split?', '[{"id":"a","text":"Water beetles versus grasshoppers or crickets"},{"id":"b","text":"Has six legs versus has eight legs"},{"id":"c","text":"Can glow versus cannot glow"},{"id":"d","text":"Is a tick versus is an insect"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Dytiscidae is printed as predaceous diving beetles; Hydrophilidae is printed as water scavenger. Acrididae is printed as short-horned grasshoppers; Gryllidae is printed as crickets/tree crickets. Grouping by those official-name clues splits the four taxa evenly. All four are insects; none are Ixodidae. Glow belongs to Lampyridae, which is not in this set.', 'Look at the official common names: two mention diving or water; two are grasshoppers or crickets.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'First-couplet construction using RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md official common-name strings only (Hydrophilidae = water scavenger).', NULL, '["Dytiscidae","Hydrophilidae","Acrididae","Gryllidae"]'::jsonb),
('ento-q21', 'entomology', 'ecology-habitat', 'Where do Trichoptera (caddisflies) typically live as larvae?', '[{"id":"a","text":"Only in dry desert sand dunes"},{"id":"b","text":"Inside the fur of mammals as obligate parasites"},{"id":"c","text":"In the open ocean as plankton only"},{"id":"d","text":"In freshwater habitats such as streams and ponds"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Caddisfly larvae are aquatic in freshwater. They are not listed as mammal parasites or as exclusively marine plankton.', 'Caddisflies are often grouped with other aquatic insect orders on study lists.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Caddisfly larval habitat is not stated on TAXON_LIST_2027.md or RULES_2027.md.', NULL, '["Trichoptera"]'::jsonb),
('ento-q22', 'entomology', 'ecology-habitat', 'Mayfly naiads (immature Ephemeroptera) are most likely to be collected from which habitat?', '[{"id":"a","text":"Hot dry attic dust"},{"id":"b","text":"A freshwater stream or pond"},{"id":"c","text":"Open ocean surface slicks only"},{"id":"d","text":"Inside stored grain as the main pest"}]'::jsonb, 'b', 'multiple-choice', NULL, 'This item treats mayfly immatures as aquatic in freshwater. That habitat is not printed on the 2027 taxon list.', 'Adult mayflies stay near the water where they emerged.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Sample Test 1 included mayfly habitat; this stem is new. Freshwater naiad habitat is not in TAXON_LIST_2027.md.', NULL, '["Ephemeroptera"]'::jsonb),
('ento-q23', 'entomology', 'life-cycles', 'Which listed group has complete metamorphosis that includes a pupal stage?', '[{"id":"a","text":"Lepidoptera (for example Papilionidae)"},{"id":"b","text":"Hemiptera (for example Aphididae)"},{"id":"c","text":"Orthoptera (for example Acrididae)"},{"id":"d","text":"Odonata (dragon/damselflies)"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Lepidoptera are holometabolous: egg, larva, pupa, adult. Hemiptera, Orthoptera, and Odonata have incomplete development (naiad/nymph to adult) without a pupa.', 'Butterflies and moths have a resting pupal/chrysalis stage; true bugs and grasshoppers do not.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Complete vs incomplete metamorphosis is sample-adjacent, not restated in RULES_2027.md or TAXON_LIST_2027.md.', NULL, '["Lepidoptera","Papilionidae","Hemiptera","Orthoptera","Odonata"]'::jsonb),
('ento-q24', 'entomology', 'behavior-adaptations', '[IMAGE REQUIRED: aquatic beetle hind legs flattened like oars.] The photo shows flattened hind legs used for swimming. Which choice names that kind of leg and a beetle family that has it?', '[{"id":"a","text":"Fossorial legs in Acrididae"},{"id":"b","text":"Raptorial legs in Mantodea"},{"id":"c","text":"Natatorial legs in Dytiscidae"},{"id":"d","text":"Pollen-collecting legs in all Coleoptera"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Flattened, hair-fringed hind legs used to row through water are natatorial. Predaceous diving beetles (Dytiscidae) show this well. Fossorial legs dig; raptorial legs seize prey (mantids). Beetles do not all collect pollen.', 'Natatorial means adapted for swimming.', NULL, NULL, NULL, 2, true, '/entomology/ento-q24.jpg', 'Photograph of an aquatic beetle in water. A yellow circle marks a flattened hind leg.', NULL, 'Close-up of a predaceous diving beetle showing widened, oar-like hind legs with swimming hairs. Not a mole-cricket digging leg (not on the list) and not a mantid raptorial foreleg.', 'verified', 'application', 'generated', 'Natatorial legs on listed Dytiscidae. Wikimedia Commons photo (see public/entomology/README.md); yellow circle marks a flattened hind leg only.', NULL, '["Dytiscidae","Coleoptera"]'::jsonb),
('ento-q25', 'entomology', 'behavior-adaptations', 'Many crickets (Gryllidae) make the familiar night chirp. How is that sound usually produced?', '[{"id":"a","text":"By flashing light organs like fireflies"},{"id":"b","text":"By forcing air through lungs"},{"id":"c","text":"By chewing wood into powder"},{"id":"d","text":"By rubbing body parts together (stridulation)"}]'::jsonb, 'd', 'multiple-choice', NULL, 'This item treats cricket chirps as stridulation: rubbing body parts together. Lampyridae (fireflies) are listed separately. Insects are not described here as having mammal-like lungs. The exact structures used to stridulate are not on the 2027 list.', 'Katydids can make sound in a similar way; fireflies use light instead.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Stridulation is sample-adjacent (Sample Test 1). Mechanism details are not on TAXON_LIST_2027.md.', NULL, '["Gryllidae","Orthoptera"]'::jsonb),
('ento-q26', 'entomology', 'human-impact', 'Why are mosquitoes (Culicidae) an important public-health family?', '[{"id":"a","text":"They pollinate all U.S. food crops and never bite animals"},{"id":"b","text":"Some species can transmit pathogens that cause human and animal disease"},{"id":"c","text":"They are the only listed family that recycles dung nutrients"},{"id":"d","text":"They are non-insect hardback ticks"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Culicidae is printed as mosquitoes. RULES_2027.md includes public health. This item treats some mosquito species as able to transmit pathogens; the list does not name a disease. Apidae (bees), Scarabaeidae (dung beetles), and Ixodidae (hardback ticks) are other listed names, not the mosquito family.', 'Think of diseases spread by bites, not of bees or dung beetles.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Public-health domain from RULES_2027.md. Do not name a specific disease in the stem. Pathogen transmission is not printed on TAXON_LIST_2027.md.', NULL, '["Culicidae","Diptera"]'::jsonb),
('ento-q27', 'entomology', 'human-impact', 'Which listed family is most clearly tied to honey and to pollinating many flowering plants?', '[{"id":"a","text":"Tenebrionidae — darkling beetles"},{"id":"b","text":"Siphonaptera — fleas"},{"id":"c","text":"Reduviidae — Assassin bugs"},{"id":"d","text":"Apidae — bees"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Apidae is printed as bees. RULES_2027.md lists food as an economic theme, but the list does not by itself prove honey production or pollination. Darkling beetles, fleas, and assassin bugs are other listed names, not the bee family.', 'Use official common names. Do not pick fleas, assassin bugs, or darkling beetles.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Apidae = bees is TAXON_LIST_2027.md. Honey and pollination are not printed on the list; food is only a RULES_2027.md domain name.', NULL, '["Apidae","Hymenoptera"]'::jsonb),
('ento-q28', 'entomology', 'interactions', 'Gall wasps (Cynipidae) are listed because of their relationship with plants. What do they typically cause plants to grow?', '[{"id":"a","text":"Mushrooms on the soil only"},{"id":"b","text":"Honey in a wax comb"},{"id":"c","text":"Galls — abnormal plant growths that house the developing wasp"},{"id":"d","text":"Silk cocoons identical to Saturniidae moths"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Cynipidae is printed as gall wasps. RULES_2027.md includes relationships with plants. What a gall is, and silk cocoons in Saturniidae, are not printed on the taxon list.', 'Do not pick mushrooms, honey, or moth cocoons.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Official common name gall wasps plus RULES_2027.md plant relationships. Gall anatomy is not in TAXON_LIST_2027.md.', NULL, '["Cynipidae","Hymenoptera"]'::jsonb),
('ento-q29', 'entomology', 'internal-anatomy', 'How do insects typically get oxygen to their tissues?', '[{"id":"a","text":"With a pair of lungs like mammals"},{"id":"b","text":"Only by absorbing oxygen through eight walking legs"},{"id":"c","text":"Only through a single gill on the head"},{"id":"d","text":"Through openings called spiracles that lead into tracheal tubes"}]'::jsonb, 'd', 'multiple-choice', NULL, 'This item treats spiracles as openings into tracheal tubes. Mammalian lungs are not the insect system described here. A fuller organ list is not in RULES_2027.md.', 'Look along the sides of the thorax and abdomen for tiny breathing holes.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Internal anatomy is in RULES_2027.md with no organ checklist. Tracheal details are not on TAXON_LIST_2027.md.', NULL, '["Insecta"]'::jsonb),
('ento-q30', 'entomology', 'climate', 'Mayflies (Ephemeroptera) and stoneflies (Plecoptera) often need cool, well-oxygenated freshwater as young insects. If a stream becomes warmer and holds less oxygen, what is the most reasonable concern?', '[{"id":"a","text":"Those aquatic naiads may decline because the habitat no longer matches what they need"},{"id":"b","text":"They will immediately become terrestrial beetles (Coleoptera)"},{"id":"c","text":"They will switch to complete metamorphosis with a pupa"},{"id":"d","text":"They will be reclassified as Ixodidae"}]'::jsonb, 'a', 'multiple-choice', NULL, 'RULES_2027.md includes climate-change impacts. This item treats warmer, lower-oxygen water as a habitat mismatch for listed mayflies and stoneflies. That oxygen mechanism is not printed on TAXON_LIST_2027.md. They are not Coleoptera or Ixodidae, and climate is not described as changing their metamorphosis type.', 'Climate-change impacts are an official 2027 topic. Think habitat, not a sudden change of order.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Climate-change impacts domain from RULES_2027.md. Mechanism (warm water / oxygen / sensitive naiads) is not printed on TAXON_LIST_2027.md.', NULL, '["Ephemeroptera","Plecoptera"]'::jsonb),
('ento-q31', 'entomology', 'taxonomy', 'What common name is listed for family Scutelleridae?', '[{"id":"a","text":"Stink bugs"},{"id":"b","text":"metallic shield bugs"},{"id":"c","text":"treehoppers"},{"id":"d","text":"cicadas"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Scutelleridae is printed as metallic shield bugs. Stink bugs (official capitals) are Pentatomidae; treehoppers are Membracidae; cicadas are Cicadidae. The list strings are what students should record.', 'Match the exact printed common-name string. Nearby true-bug families on the list use different strings.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'TAXON_LIST_2027.md Family Scutelleridae common names.', NULL, '["Scutelleridae","Hemiptera"]'::jsonb),
('ento-q32', 'entomology', 'taxonomy', '“Stink bugs” is the listed common name for which family?', '[{"id":"a","text":"Scutelleridae"},{"id":"b","text":"Membracidae"},{"id":"c","text":"Pentatomidae"},{"id":"d","text":"Cicadidae"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Pentatomidae is printed as Stink bugs. Scutelleridae is metallic shield bugs; Membracidae is treehoppers; Cicadidae is cicadas. Using the official string avoids mixing two listed true-bug families.', 'Match the printed common name to the family — nearby Hemiptera names are different families.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027_OFFICIAL.md / TAXON_LIST_2027.md Family Pentatomidae — Stink bugs.', NULL, '["Pentatomidae","Hemiptera"]'::jsonb),
('ento-q33', 'entomology', 'visual-id', '[IMAGE REQUIRED: large insect with clear wings folded roof-like over the back.] Which family is this insect?', '[{"id":"a","text":"Membracidae — treehoppers"},{"id":"b","text":"Cicadidae — cicadas"},{"id":"c","text":"Scutelleridae — metallic shield bugs"},{"id":"d","text":"Coccinellidae — lady-bird beetles (ladybugs)"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Cicadidae is printed as cicadas under Hemiptera. Treehoppers are Membracidae; metallic shield bugs are Scutelleridae; lady-bird beetles(ladybugs) are Coccinellidae in Coleoptera.', 'Match the specimen to a listed Hemiptera family common name. Do not pick a beetle family.', NULL, NULL, NULL, 2, true, '/entomology/ento-q33.jpg', 'Photograph of a stout insect with large compound eyes and long clear wings folded over its back.', NULL, 'Adult cicada: wide head, membranous wings past the abdomen. Not a treehopper, shield bug, or lady-bird beetle.', 'verified', 'recognition', 'rules-derived', 'TAXON_LIST_2027.md Family Cicadidae. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Cicadidae","Hemiptera"]'::jsonb),
('ento-q34', 'entomology', 'taxonomy', 'What common name is listed for Order Megaloptera?', '[{"id":"a","text":"stoneflies"},{"id":"b","text":"dragon/damselflies"},{"id":"c","text":"caddisflies"},{"id":"d","text":"dobsonflies"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Megaloptera is printed as dobsonflies. Stoneflies are Plecoptera; dragon/damselflies are Odonata; caddisflies are Trichoptera. Those nearby order names are easy to mix if you only remember “aquatic insect.”', 'Several aquatic-looking order names are on the list; match this order’s printed string.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'TAXON_LIST_2027.md Order Megaloptera common names.', NULL, '["Megaloptera"]'::jsonb),
('ento-q35', 'entomology', 'visual-id', '[IMAGE REQUIRED: round beetles with spotted wing covers.] Which family is this?', '[{"id":"a","text":"Curculionidae — weevils"},{"id":"b","text":"Scarabaeidae — dung beetles"},{"id":"c","text":"Tenebrionidae — darkling beetles"},{"id":"d","text":"Coccinellidae — lady-bird beetles (ladybugs)"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Coccinellidae is printed as lady-bird beetles(ladybugs). Weevils are Curculionidae; dung beetles are Scarabaeidae; darkling beetles are Tenebrionidae. Spot pattern is not printed on the 2027 list.', 'Among listed beetle families, match the specimen to its official common name. Keep the official punctuation.', NULL, NULL, NULL, 2, true, '/entomology/ento-q35.jpg', 'Photograph of two round beetles with spotted wing covers on a green plant.', NULL, 'Lady-bird beetles in dorsal view: round spotted elytra, no snout. Not weevils, dung beetles, or darkling beetles.', 'verified', 'recognition', 'rules-derived', 'TAXON_LIST_2027.md Family Coccinellidae — lady-bird beetles(ladybugs). Wikimedia Commons photo (see public/entomology/README.md). Buprestidae family-to-order remains in ento-q50.', NULL, '["Coccinellidae","Coleoptera"]'::jsonb),
('ento-q36', 'entomology', 'taxonomy', 'What common name is listed for Family Zopheridae?', '[{"id":"a","text":"diabolical ironclad Beetles"},{"id":"b","text":"dung beetles"},{"id":"c","text":"darkling beetles"},{"id":"d","text":"weevils"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Zopheridae is printed as diabolical ironclad Beetles. Dung beetles are Scarabaeidae; darkling beetles are Tenebrionidae; weevils are Curculionidae. All four are listed beetle families with different official strings.', 'This Coleoptera family has a long, distinctive official common name on the list.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'TAXON_LIST_2027.md Family Zopheridae common names.', NULL, '["Zopheridae","Coleoptera"]'::jsonb),
('ento-q37', 'entomology', 'taxonomy', 'A listed specimen is family Tephritidae (fruit flies, husk fly). Which order should be recorded?', '[{"id":"a","text":"Hymenoptera"},{"id":"b","text":"Lepidoptera"},{"id":"c","text":"Diptera"},{"id":"d","text":"Hemiptera"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Tephritidae is a family of Order Diptera (true flies). Hymenoptera is printed as bees/ants/wasps.; Lepidoptera as moths and butterflies; Hemiptera as true bugs. Family-to-order placement is a list skill.', 'Find the parent order printed above Tephritidae on the 2027 list.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'TAXON_LIST_2027.md Diptera → Tephritidae.', NULL, '["Tephritidae","Diptera"]'::jsonb),
('ento-q38', 'entomology', 'visual-id', '[IMAGE REQUIRED: insect with a triangular head and folded grasping front legs.] Which order is this?', '[{"id":"a","text":"Zygentoma — silverfish, firebrats"},{"id":"b","text":"Blattodea — cockroaches/termites"},{"id":"c","text":"Orthoptera — grasshoppers & crickets"},{"id":"d","text":"Mantodea — mantids"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Mantodea is printed as mantids. Silverfish and firebrats are Zygentoma; cockroaches/termites are Blattodea; grasshoppers & crickets are Orthoptera. Folded grasping front legs are visible in the photo; that character is not printed on the 2027 list.', 'Match the specimen to the listed order’s official common name. Do not pick cockroaches or crickets.', NULL, NULL, NULL, 1, true, '/entomology/ento-q38.jpg', 'Photograph of a green insect with a triangular head and folded, spiny front legs.', NULL, 'Mantid: triangular head, raptorial forelegs folded. Not a cockroach, cricket, or silverfish.', 'verified', 'recognition', 'rules-derived', 'TAXON_LIST_2027.md Order Mantodea — mantids. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Mantodea"]'::jsonb),
('ento-q39', 'entomology', 'taxonomy', 'Siphonaptera is listed as fleas. How is it grouped?', '[{"id":"a","text":"As an insect order with no families listed"},{"id":"b","text":"As a family under Diptera"},{"id":"c","text":"As a non-insect arthropod family"},{"id":"d","text":"As a subclass under Entognatha"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Siphonaptera is an insect order whose official common name is fleas, and the list prints no families under it. It is not a fly family, not Ixodidae, and not a subclass of Entognatha. Rank and “families listed: none” both come from the list.', 'Check whether the list prints families under this name, and whether it sits in Insecta.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'TAXON_LIST_2027.md Order Siphonaptera (common names: fleas; families listed: none).', NULL, '["Siphonaptera","Insecta"]'::jsonb),
('ento-q40', 'entomology', 'comparison', '[IMAGE REQUIRED: two flower-visiting insects labeled A and B.] Look at insects A and B. Which pairing is correct?', '[{"id":"a","text":"A and B are both Apidae in Hymenoptera"},{"id":"b","text":"A = Bombyliidae in Diptera; B = Apidae in Hymenoptera"},{"id":"c","text":"A = Apidae in Hymenoptera; B = Bombyliidae in Diptera"},{"id":"d","text":"A and B are both Bombyliidae in Diptera"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Bombyliidae is printed as bee flies under Diptera. Apidae is printed as bees under Hymenoptera. Specimen A has one pair of wings and a long rigid mouthpart; specimen B has two pairs of wings. Those photo characters are not printed on the 2027 list.', 'Match each specimen to a listed family and its parent order. Similar everyday words can sit in different orders.', NULL, NULL, NULL, 3, true, '/entomology/ento-q40.jpg', 'Two photographs of flower-visiting insects labeled A and B. No extra labels on the mouthparts or wings.', NULL, 'A: bee fly with one wing pair and long rigid proboscis. B: honey bee with two wing pairs. Do not print family names on the image.', 'verified', 'distinction', 'rules-derived', 'TAXON_LIST_2027.md Bombyliidae (bee flies) vs Apidae (bees). Wikimedia Commons photos (see public/entomology/README.md); A/B labels only.', NULL, '["Bombyliidae","Apidae","Diptera","Hymenoptera"]'::jsonb),
('ento-q41', 'entomology', 'visual-id', '[IMAGE REQUIRED: yellow-and-black flying insect with a narrow waist.] Which family is this?', '[{"id":"a","text":"Formicidae — ants"},{"id":"b","text":"Apidae — bees"},{"id":"c","text":"Vespidae — paper wasps, hornets, yellowjackets"},{"id":"d","text":"Cynipidae — gall wasps"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Vespidae is printed as paper wasps, hornets, yellowjackets. Ants are Formicidae; bees are Apidae; gall wasps are Cynipidae. A narrow waist is visible in the photo; that character is not printed on the 2027 list.', 'All four choices are listed Hymenoptera families; match the specimen to the official common-name string.', NULL, NULL, NULL, 1, true, '/entomology/ento-q41.jpg', 'Photograph of a yellow-and-black perched insect with a narrow waist and banded abdomen.', NULL, 'Yellowjacket in flight: yellow and black bands, narrow waist. Not an ant, bee, or gall wasp.', 'verified', 'recognition', 'rules-derived', 'TAXON_LIST_2027.md Family Vespidae. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Vespidae","Hymenoptera"]'::jsonb),
('ento-q42', 'entomology', 'taxonomy', 'Saturniidae (Giant Silkworm moths) belong to which order?', '[{"id":"a","text":"Lepidoptera"},{"id":"b","text":"Diptera"},{"id":"c","text":"Hymenoptera"},{"id":"d","text":"Coleoptera"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Saturniidae is a family of Lepidoptera (moths and butterflies). Diptera is printed as true flies; Hymenoptera as bees/ants/wasps.; Coleoptera as beetles. Keep the list’s capitalization of Giant Silkworm moths, and still place the family in Lepidoptera.', 'Find the parent order printed above Saturniidae on the 2027 list.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'TAXON_LIST_2027.md Lepidoptera → Saturniidae.', NULL, '["Saturniidae","Lepidoptera"]'::jsonb),
('ento-q43', 'entomology', 'taxonomy', 'On the list, what ranks are Collembola and Diplura?', '[{"id":"a","text":"Both are families in Class Insecta"},{"id":"b","text":"Both are insect orders in Class Insecta"},{"id":"c","text":"Collembola is an order; Diplura is a subclass"},{"id":"d","text":"Collembola is a subclass of Entognatha; Diplura is an order of Entognatha"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Collembola is Subclass Collembola under Class Entognatha. Diplura is Order Diplura under the same class. They are not Insecta families or Insecta orders, and the subclass/order labels are not interchangeable.', 'Neither name is a family. One is the list’s only subclass.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'TAXON_LIST_2027.md Class Entognatha: Subclass Collembola vs Order Diplura.', NULL, '["Collembola","Diplura","Entognatha"]'::jsonb),
('ento-q44', 'entomology', 'visual-id', '[IMAGE REQUIRED: small insect with a peaked shield over the back.] Which family is this?', '[{"id":"a","text":"Acrididae — short-horned grasshoppers"},{"id":"b","text":"Cicadidae — cicadas"},{"id":"c","text":"Membracidae — treehoppers"},{"id":"d","text":"Pentatomidae — Stink bugs"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Membracidae is printed as treehoppers under Hemiptera. Cicadas are Cicadidae; Stink bugs are Pentatomidae; short-horned grasshoppers are Acrididae in Orthoptera. A peaked dorsal shield is visible in the photo; that character is not printed on the 2027 list.', 'Match the specimen to a listed Hemiptera family common name. Do not pick a grasshopper family.', NULL, NULL, NULL, 2, true, '/entomology/ento-q44.jpg', 'Side photograph of a small green insect with a peaked shield-shaped back on a stem.', NULL, 'Treehopper in side view: enlarged pronotum forming a peak. Not a cicada, stink bug, or short-horned grasshopper.', 'verified', 'recognition', 'rules-derived', 'TAXON_LIST_2027.md Family Membracidae. Wikimedia Commons photo (see public/entomology/README.md).', NULL, '["Membracidae","Hemiptera"]'::jsonb),
('ento-q45', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Listed under Non-Insect Arthropods → Ixodidae
1b. Listed in Class Insecta → go to 2
2a. Listed common name is bees → Apidae
2b. Listed common name is ants → Formicidae

The specimen is a hardback tick. Which family do you reach?', '[{"id":"a","text":"Ixodidae"},{"id":"b","text":"Apidae"},{"id":"c","text":"Formicidae"},{"id":"d","text":"Collembola"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Hardback ticks are Family Ixodidae under Non-Insect Arthropods, so 1a finishes the key. Couplet 2 is only for Insecta. Bees and ants are listed hymenopteran families; Collembola is Entognatha, not the tick family.', 'Start at couplet 1 using the list heading, not the insect families in couplet 2.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using TAXON_LIST_2027.md Non-Insect Arthropods vs Insecta and official Apidae/Formicidae names.', NULL, '["Ixodidae","Apidae","Formicidae"]'::jsonb),
('ento-q46', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Family in Hemiptera (true bugs) → go to 2
1b. Family in Coleoptera (beetles) → stop; not in this key
2a. Listed common name is cicadas → Cicadidae
2b. Listed common name is metallic shield bugs → Scutelleridae

A specimen’s listed common name is metallic shield bugs. Which family do you reach?', '[{"id":"a","text":"Cicadidae"},{"id":"b","text":"Pentatomidae"},{"id":"c","text":"Scutelleridae"},{"id":"d","text":"Coccinellidae"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Couplet 1a keeps Hemiptera. Couplet 2b matches metallic shield bugs → Scutelleridae. Cicadidae is 2a. Pentatomidae (Stink bugs) is a listed hemipteran family not in this key. Coccinellidae is a beetle family, so 1b would exclude it.', 'Stay on the Hemiptera branch, then match the official common name in couplet 2.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using TAXON_LIST_2027.md Hemiptera vs Coleoptera and Scutelleridae/Cicadidae common names.', NULL, '["Scutelleridae","Cicadidae","Hemiptera"]'::jsonb),
('ento-q47', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Listed common name is thrips → Thysanoptera
1b. Not thrips → go to 2
2a. Listed common name is dobsonflies → Megaloptera
2b. Listed common name is caddisflies → Trichoptera

A specimen’s listed common name is dobsonflies. Which order do you reach?', '[{"id":"a","text":"Thysanoptera"},{"id":"b","text":"Megaloptera"},{"id":"c","text":"Trichoptera"},{"id":"d","text":"Siphonaptera"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Dobsonflies are not thrips, so 1b leads to couplet 2. Couplet 2a matches dobsonflies → Megaloptera. Trichoptera is caddisflies; Siphonaptera is fleas and is not in this key. The splits use official common names only.', 'Reject couplet 1a, then read couplet 2 using the printed common name.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using TAXON_LIST_2027.md official common names for Thysanoptera, Megaloptera, and Trichoptera.', NULL, '["Megaloptera","Thysanoptera","Trichoptera"]'::jsonb),
('ento-q48', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Family in Diptera (true flies) → go to 2
1b. Family in Hymenoptera (bees, ants, wasps) → stop; not in this key
2a. Listed common name is mosquitoes → Culicidae
2b. Listed common name is fruit flies, husk fly → Tephritidae

A specimen’s listed common name is fruit flies, husk fly. Which family do you reach?', '[{"id":"a","text":"Culicidae"},{"id":"b","text":"Apidae"},{"id":"c","text":"Bombyliidae"},{"id":"d","text":"Tephritidae"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Couplet 1a keeps Diptera. Couplet 2b matches fruit flies, husk fly → Tephritidae. Culicidae is mosquitoes (2a). Apidae is bees in Hymenoptera (1b). Bombyliidae is bee flies, a listed dipteran family not used in this key.', 'Stay on Diptera, then match the exact official common-name string in couplet 2.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using TAXON_LIST_2027.md Diptera vs Hymenoptera and Tephritidae/Culicidae common names.', NULL, '["Tephritidae","Culicidae","Diptera"]'::jsonb),
('ento-q49', 'entomology', 'dichotomous-keys', 'You are making a simple key for these listed groups only: Collembola, Blattodea, and Ixodidae. What is the best first split?', '[{"id":"a","text":"Lives in water versus lives on land"},{"id":"b","text":"Entognatha versus Insecta versus non-insect arthropods"},{"id":"c","text":"Has wings versus has no wings"},{"id":"d","text":"Can glow versus cannot glow"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Collembola is a subclass of Entognatha, Blattodea is an insect order, and Ixodidae is under Non-Insect Arthropods. That list grouping splits the three taxa cleanly. Water vs land, wings, and glowing are not characters this key is allowed to assume from the list.', 'Use how the 2027 list groups the three names, not unsourced habits.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'TAXON_LIST_2027.md headings: Entognatha (Collembola), Insecta (Blattodea), Non-Insect Arthropods (Ixodidae).', NULL, '["Collembola","Blattodea","Ixodidae","Entognatha","Insecta"]'::jsonb),
('ento-q50', 'entomology', 'dichotomous-keys', 'Follow this key from the top.

1a. Family in Coleoptera (beetles) → go to 2
1b. Family in Diptera (true flies) → stop; not in this key
2a. Listed common name is metallic wood-boring/jewel beetles → Buprestidae
2b. Listed common name is diabolical ironclad Beetles → Zopheridae

A specimen’s listed common name is metallic wood-boring/jewel beetles. Which family do you reach?', '[{"id":"a","text":"Buprestidae"},{"id":"b","text":"Zopheridae"},{"id":"c","text":"Lampyridae"},{"id":"d","text":"Tephritidae"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Couplet 1a keeps Coleoptera. Couplet 2a matches metallic wood-boring/jewel beetles → Buprestidae. Zopheridae is 2b. Lampyridae (fireflies) is a listed beetle family not in this key. Tephritidae is a fly family, so 1b would exclude it.', 'Stay on Coleoptera, then read couplet 2’s official common names.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'Original key using TAXON_LIST_2027.md Coleoptera vs Diptera and Buprestidae/Zopheridae common names.', NULL, '["Buprestidae","Zopheridae","Coleoptera"]'::jsonb),
('ento-q51', 'entomology', 'external-anatomy', 'An insect’s three main body regions are head, thorax, and abdomen. Which region sits in the middle?', '[{"id":"a","text":"Abdomen"},{"id":"b","text":"Thorax"},{"id":"c","text":"Head"},{"id":"d","text":"Neck"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The thorax is the middle region, between the head and the abdomen. Neck is not one of the three insect tagmata used in this curriculum. Knowing the middle region matters because that is also where walking legs attach.', 'The three regions run front to back: head, then the middle piece, then the abdomen.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recognition', 'generated', 'Insect tagmata from CURRICULUM_2027.md external-anatomy and existing ento-q14 (head, thorax, abdomen). New stem asks which region is middle.', NULL, '["Insecta"]'::jsonb),
('ento-q52', 'entomology', 'external-anatomy', 'An insect’s three main body regions are head, thorax, and abdomen. Which region is at the rear?', '[{"id":"a","text":"Head"},{"id":"b","text":"Thorax"},{"id":"c","text":"Abdomen"},{"id":"d","text":"Neck"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The abdomen is the rear region. Head is at the front; thorax is in the middle. Neck is not one of the three insect body regions in this curriculum. Rear vs middle matters when locating abdominal appendages such as cerci.', 'The rear region is the last of the three tagmata, not the middle thorax.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recognition', 'generated', 'Insect tagmata from CURRICULUM_2027.md and existing ento-q14. New stem asks which region is rear.', NULL, '["Insecta"]'::jsonb),
('ento-q53', 'entomology', 'external-anatomy', 'Where is an insect’s supporting skeleton found?', '[{"id":"a","text":"Inside the body like a typical mammal backbone"},{"id":"b","text":"Only in the wings when wings are present"},{"id":"c","text":"Only inside the compound eyes"},{"id":"d","text":"On the outside of the body"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Insects have an exoskeleton: the supporting cuticle is on the outside of the body, where muscles can attach. It is not a mammal-style internal backbone, and it is not limited to wings or eyes. That outside position is why it both supports and protects.', 'The word “exoskeleton” means the skeleton is on the outside.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Exoskeleton location from CURRICULUM_2027.md and existing ento-q15 (outside skeleton / cuticle). New stem asks where it is, not only its job.', NULL, '["Insecta"]'::jsonb),
('ento-q54', 'entomology', 'external-anatomy', 'Which listed grouping is not an insect built with head, thorax, and abdomen as its three main regions?', '[{"id":"a","text":"Family Apidae"},{"id":"b","text":"Order Coleoptera"},{"id":"c","text":"Family Ixodidae (hardback ticks)"},{"id":"d","text":"Order Blattodea"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Ixodidae is listed under Non-Insect Arthropods as hardback ticks, not as Class Insecta. Apidae, Coleoptera, and Blattodea are insects on the list, so the three insect body regions apply to them. List grouping, not a new tick diagram, is what separates Ixodidae here.', 'Find the name that the 2027 list places outside Class Insecta.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'distinction', 'generated', 'TAXON_LIST_2027.md Ixodidae under Non-Insect Arthropods; insect tagmata from CURRICULUM_2027.md and ento-q14.', NULL, '["Ixodidae","Insecta","Apidae","Coleoptera","Blattodea"]'::jsonb),
('ento-q55', 'entomology', 'life-cycles', 'Dragonflies and damselflies are listed as Order Odonata. Do they have a pupal stage?', '[{"id":"a","text":"Yes; Odonata are holometabolous like Lepidoptera"},{"id":"b","text":"No; Odonata have incomplete development without a pupa"},{"id":"c","text":"Only when they are listed as Ixodidae"},{"id":"d","text":"Only the family Papilionidae inside Odonata has a pupa"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The existing life-cycle item treats Lepidoptera as holometabolous (egg, larva, pupa, adult) and treats Odonata, Hemiptera, and Orthoptera as incomplete development without a pupa. Odonata is not Ixodidae, and Papilionidae is a lepidopteran family, not an odonate family.', 'Complete metamorphosis with a pupa was taught for Lepidoptera, not for Odonata.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'Same complete vs incomplete split as existing ento-q23 (Odonata without a pupa). New stem asks about Odonata rather than which group is holometabolous.', NULL, '["Odonata","Lepidoptera"]'::jsonb),
('ento-q56', 'entomology', 'ecology-habitat', 'Caddisflies are listed under which order?', '[{"id":"a","text":"Ephemeroptera"},{"id":"b","text":"Plecoptera"},{"id":"c","text":"Odonata"},{"id":"d","text":"Trichoptera"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Caddisflies are Order Trichoptera on the 2027 list. Ephemeroptera is mayflies; Plecoptera is stoneflies; Odonata is dragon/damselflies — different official names.', 'Match the official common name to its order on the 2027 list.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'TAXON_LIST_2027.md Trichoptera = caddisflies. The item tests the official list mapping only.', NULL, '["Trichoptera"]'::jsonb),
('ento-q57', 'entomology', 'internal-anatomy', 'In insects, what are spiracles?', '[{"id":"a","text":"Openings that lead into tracheal tubes"},{"id":"b","text":"A pair of lungs like those of mammals"},{"id":"c","text":"The pupal stage of complete metamorphosis"},{"id":"d","text":"The three pairs of walking legs"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Spiracles are openings into the tracheal tubes that carry air to insect tissues. Insects do not have mammal lungs. A pupa is a life-cycle stage, and walking legs are thoracic appendages — neither is a spiracle.', 'They are breathing openings, not lungs and not legs.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recall', 'generated', 'Spiracles/tracheal tubes from existing ento-q29 and CURRICULUM_2027.md internal-anatomy-gas-exchange. New stem names the openings.', NULL, '["Insecta"]'::jsonb),
('ento-q58', 'entomology', 'behavior-adaptations', 'Which listed family is known for a familiar night chirp made by rubbing body parts together (stridulation)?', '[{"id":"a","text":"Lampyridae"},{"id":"b","text":"Culicidae"},{"id":"c","text":"Gryllidae"},{"id":"d","text":"Ixodidae"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The existing behavior item treats Gryllidae (crickets/tree crickets) as stridulating by rubbing body parts together. Lampyridae are fireflies (light, not this chirp example). Culicidae are mosquitoes. Ixodidae are hardback ticks, not an insect cricket family.', 'Do not pick fireflies, mosquitoes, or hardback ticks.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'recognition', 'generated', 'Stridulation example taxon from existing ento-q25 (Gryllidae). New stem asks which listed family, not how the sound is produced.', NULL, '["Gryllidae","Orthoptera"]'::jsonb),
('ento-q59', 'entomology', 'interactions', 'Gall wasps (Cynipidae) are known for their relationship with what?', '[{"id":"a","text":"Plants"},{"id":"b","text":"Hardback ticks only"},{"id":"c","text":"Marine plankton only"},{"id":"d","text":"Mammalian lungs"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Cynipidae is printed as gall wasps. The existing interactions item treats them as causing plant galls — a plant–insect relationship on the official scope. They are not defined by ticks, marine plankton, or lungs.', 'The official common name includes “gall,” a plant growth in this curriculum’s gall-wasp item.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'needs-review', 'application', 'generated', 'TAXON_LIST_2027.md Cynipidae = gall wasps; plant galls from existing ento-q28 and RULES_2027.md relationships with plants.', NULL, '["Cynipidae","Hymenoptera"]'::jsonb),
('ento-q60', 'entomology', 'human-impact', 'Which listed family includes species that can transmit pathogens to people or animals?', '[{"id":"a","text":"Apidae"},{"id":"b","text":"Scarabaeidae"},{"id":"c","text":"Saturniidae"},{"id":"d","text":"Culicidae"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The existing public-health item treats Culicidae (mosquitoes) as a family in which some species can transmit pathogens. Apidae are bees (food/pollination). Scarabaeidae are dung beetles. Saturniidae are Giant Silkworm moths. This stem does not name a specific disease.', 'Eliminate bees, dung beetles, and Giant Silkworm moths using their official common names.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'needs-review', 'recognition', 'generated', 'Public-health example taxon from existing ento-q26 (Culicidae). New stem asks which family, without naming a disease.', NULL, '["Culicidae","Diptera"]'::jsonb);

create index if not exists entomology_questions_topic_id_idx on public.entomology_questions (topic_id);
create index if not exists entomology_questions_verification_status_idx on public.entomology_questions (verification_status);

-- anatomy_physiology_questions: 45 rows

create table if not exists public.anatomy_physiology_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint anatomy_physiology_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint anatomy_physiology_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.anatomy_physiology_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('ap-q1', 'anatomy-physiology', 'integument-functions', 'Which skin layer uses keratin and glycolipids to help stop the body from losing water?', '[{"id":"a","text":"The hypodermis"},{"id":"b","text":"The stratum corneum"},{"id":"c","text":"The red bone marrow"},{"id":"d","text":"The synovial joint cavity"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Keratin and glycolipids in the stratum corneum form a barrier against water loss. The same outer skin also helps defend against microbes and chemicals.', 'The outer barrier is keratin and glycolipids in the outer epidermal stratum.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-140.', '["E-AP-140"]'::jsonb, NULL),
('ap-q2', 'anatomy-physiology', 'integument-functions', 'Where does the body begin making vitamin D when the skin is exposed to UV radiation?', '[{"id":"a","text":"In the red marrow of long bones"},{"id":"b","text":"In the synovial fluid of joints"},{"id":"c","text":"In the intercalated discs of the heart"},{"id":"d","text":"In the epidermal layer"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The epidermis synthesizes vitamin D3 (cholecalciferol) when exposed to UV radiation. The liver and kidneys later convert it to active calcitriol.', 'The starting step happens in the outer covering of the body, not inside a bone.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-144.', '["E-AP-144"]'::jsonb, NULL),
('ap-q3', 'anatomy-physiology', 'integument-functions', 'After a long run on a hot day, a student’s skin is wet with sweat. How does that sweat help cool the body?', '[{"id":"a","text":"The sweat freezes on the skin and stores cold"},{"id":"b","text":"The sweat plugs hair follicles so heat cannot escape"},{"id":"c","text":"The sweat evaporates from the skin surface, and the body is cooled"},{"id":"d","text":"The sweat turns into vitamin D and lowers temperature"}]'::jsonb, 'c', 'multiple-choice', NULL, 'When the sweat evaporates from the skin surface, the body is cooled.', 'Cooling is described as happening when sweat evaporates from the skin.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-143.', '["E-AP-143"]'::jsonb, NULL),
('ap-q4', 'anatomy-physiology', 'integument-functions', 'During hard exercise in heat, the integumentary system uses sweat and a change in dermal blood vessels. What happens to those vessels, and why?', '[{"id":"a","text":"They constrict so heat stays trapped in the skin only"},{"id":"b","text":"They dilate so extra heat in the blood can leave through the skin"},{"id":"c","text":"They close completely so no blood reaches the dermis"},{"id":"d","text":"They fill with synovial fluid to cushion the skin"}]'::jsonb, 'b', 'multiple-choice', NULL, 'When the body is too warm, arterioles in the dermis dilate so excess heat can dissipate through the skin. Sweat evaporating from the skin surface also cools the body.', 'When the body is too warm, dermal arterioles change so excess heat can dissipate.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-143.', '["E-AP-143"]'::jsonb, NULL),
('ap-q5', 'anatomy-physiology', 'integument-functions', 'Which substance in sweat helps limit the growth of microbes on the skin?', '[{"id":"a","text":"Melanin"},{"id":"b","text":"Dermcidin"},{"id":"c","text":"Acetylcholine"},{"id":"d","text":"Urate"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Sweat contains dermcidin, which has antibiotic properties that help deter microbes from over-colonizing the skin surface.', 'OpenStax names this substance in sweat as having antibiotic properties.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-141.', '["E-AP-141"]'::jsonb, NULL),
('ap-q6', 'anatomy-physiology', 'integument-structure', 'Why can the epidermis be described as avascular?', '[{"id":"a","text":"It contains blood vessels"},{"id":"b","text":"It is the deepest layer of skin"},{"id":"c","text":"It is made entirely of connective tissue"},{"id":"d","text":"It contains no blood vessels"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The epidermis is keratinized stratified squamous epithelium and does not have any blood vessels within it; it is avascular.', 'Avascular means there are no blood vessels inside that layer.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §5.1; E-AP-021.', '["E-AP-021"]'::jsonb, NULL),
('ap-q7', 'anatomy-physiology', 'integument-structure', 'Thin skin has four epidermal strata. What extra layer is present in thick skin?', '[{"id":"a","text":"Stratum basale"},{"id":"b","text":"Stratum spinosum"},{"id":"c","text":"Stratum lucidum"},{"id":"d","text":"Stratum corneum"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Thin skin has four layers (basale, spinosum, granulosum, and corneum). Thick skin has a fifth layer, the stratum lucidum.', 'Thick skin has a fifth named layer that thin skin does not.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §5.1; E-AP-022, E-AP-023.', '["E-AP-022","E-AP-023"]'::jsonb, NULL),
('ap-q8', 'anatomy-physiology', 'integument-structure', 'A student compares two touch receptors in the skin. Which pairing is correct?', '[{"id":"a","text":"Meissner corpuscle detects vibration; Pacinian corpuscle detects light touch"},{"id":"b","text":"Meissner corpuscle detects light touch; Pacinian corpuscle detects vibration"},{"id":"c","text":"Both corpuscles detect only pain and temperature"},{"id":"d","text":"Both corpuscles are found only in hyaline cartilage"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Meissner (tactile) corpuscles respond to light touch. Pacinian (lamellated) corpuscles respond to vibration.', 'One receptor is for a gentle brush; the other is for a buzzing or vibrating stimulus.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-142.', '["E-AP-142"]'::jsonb, NULL),
('ap-q9', 'anatomy-physiology', 'integument-structure', 'Which glands are the main cooling-sweat glands over much of the skin?', '[{"id":"a","text":"Apocrine sweat glands"},{"id":"b","text":"Eccrine sweat glands"},{"id":"c","text":"Meissner corpuscles in the papillary dermis"},{"id":"d","text":"Red marrow in spongy bone"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Eccrine sweat glands produce sweat for thermoregulation and are especially abundant on the palms, soles, and forehead.', 'These are the common cooling-sweat glands over much of the skin.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax A&P 2e §5.2; E-AP-034.', '["E-AP-034"]'::jsonb, NULL),
('ap-q10', 'anatomy-physiology', 'integument-structure', 'How do apocrine sweat glands differ from eccrine sweat glands?', '[{"id":"a","text":"Apocrine glands are associated with hair follicles, and their sweat includes organic compounds that bacteria can break down; eccrine glands are the main cooling glands"},{"id":"b","text":"Apocrine glands are the main cooling glands; eccrine glands are associated with hair follicles and their sweat includes organic compounds that bacteria can break down"},{"id":"c","text":"Apocrine glands are associated with hair follicles but their sweat has no organic compounds; eccrine glands are the main cooling glands"},{"id":"d","text":"Apocrine glands are the main cooling glands and their sweat has no organic compounds; eccrine glands are associated with hair follicles"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Apocrine sweat glands are usually associated with hair follicles in densely hairy areas such as armpits and genital regions. Their sweat includes organic compounds that bacteria can decompose, which can cause odor. Eccrine glands, not apocrine glands, are the main thermoregulatory glands on palms, soles, and forehead.', 'Think about location (hairy regions) and why the sweat can smell after bacteria act on it.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §5.2; E-AP-034, E-AP-035.', '["E-AP-034","E-AP-035"]'::jsonb, NULL),
('ap-q11', 'anatomy-physiology', 'integument-structure', 'Wrinkling of aging skin occurs due to decreased production of which proteins in the dermis?', '[{"id":"a","text":"Melanin from melanocytes"},{"id":"b","text":"Keratin of the stratum corneum"},{"id":"c","text":"Collagen and elastin"},{"id":"d","text":"Acetylcholine at the neuromuscular junction"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Wrinkling of the skin occurs due to decreased collagen and elastin production in the dermis. Aging skin also has a thinner epidermis because mitosis in the stratum basale decreases.', 'The dermal proteins are collagen and elastin.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax A&P 2e §5.3; E-AP-146.', '["E-AP-146"]'::jsonb, NULL),
('ap-q12', 'anatomy-physiology', 'integument-conditions', 'Which exposure is a documented risk factor for skin cancer?', '[{"id":"a","text":"Vitamin D made in the epidermis"},{"id":"b","text":"Eccrine sweat on the palms"},{"id":"c","text":"Meissner corpuscles in the dermis"},{"id":"d","text":"Ultraviolet radiation from sunlight or tanning beds"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Exposure to ultraviolet (UV) radiation is a risk factor for skin cancer. Sunlamps and tanning beds also give off UV radiation.', 'The risk comes from a kind of invisible energy, not from normal sweat or touch receptors.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'nci', 'NCI Skin Cancer Prevention PDQ; E-AP-147.', '["E-AP-147"]'::jsonb, NULL),
('ap-q13', 'anatomy-physiology', 'integument-conditions', 'A person had chickenpox as a child. Years later they develop shingles. What does that later illness tell you about the virus?', '[{"id":"a","text":"A completely new virus species caused the second illness"},{"id":"b","text":"Chickenpox is caused by HPV, and shingles is caused by tetanus bacteria"},{"id":"c","text":"The same varicella-zoster virus stayed dormant and later reactivated"},{"id":"d","text":"Shingles can occur only if the person never had chickenpox"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Chickenpox is caused by varicella-zoster virus (VZV). After recovery, VZV can remain dormant and later reactivate as shingles.', 'One virus can cause two illnesses at different times of life.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'cdc', 'CDC About Chickenpox; E-AP-053, E-AP-054.', '["E-AP-053","E-AP-054"]'::jsonb, NULL),
('ap-q14', 'anatomy-physiology', 'integument-conditions', 'Melanoma is a cancer of which skin cells?', '[{"id":"a","text":"Melanocytes"},{"id":"b","text":"Osteoclasts"},{"id":"c","text":"Cardiac pacemaker cells"},{"id":"d","text":"Chondrocytes of hyaline cartilage"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Melanoma is characterized by the uncontrolled growth of melanocytes. Basal cell carcinoma instead affects stem cells in the stratum basale, and squamous cell carcinoma affects keratinocytes of the stratum spinosum.', 'These are the pigment cells of the epidermis.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §5.4; E-AP-044 (related: E-AP-042, E-AP-043).', '["E-AP-044","E-AP-042","E-AP-043"]'::jsonb, NULL),
('ap-q15', 'anatomy-physiology', 'integument-conditions', 'HPV is a common virus that can cause cancers later in life. What is one way to protect against those HPV cancers?', '[{"id":"a","text":"Avoiding all eccrine sweating"},{"id":"b","text":"Removing the epiphyseal plate"},{"id":"c","text":"HPV vaccination"},{"id":"d","text":"Stretching the sarcomere to 200% of resting length"}]'::jsonb, 'c', 'multiple-choice', NULL, 'HPV can cause cancers later in life, and HPV vaccination can protect against those cancers. CDC recommends 2 doses starting at ages 11–12 (and vaccination can start at age 9).', 'The protection is a vaccine, not a change to bone or muscle structure.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'cdc', 'CDC About HPV; E-AP-051, E-AP-052.', '["E-AP-051","E-AP-052"]'::jsonb, NULL),
('ap-q16', 'anatomy-physiology', 'bone-tissue', 'The skeleton is divided into axial and appendicular parts. Which bones belong to the appendicular skeleton?', '[{"id":"a","text":"Only the skull and vertebral column"},{"id":"b","text":"Only the thoracic cage"},{"id":"c","text":"Only the bones of the head and neck"},{"id":"d","text":"The bones of the upper and lower limbs, plus the girdle bones that attach the limbs"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The appendicular skeleton includes all bones of the upper and lower limbs, plus the bones that attach each limb to the axial skeleton. The axial skeleton includes the head, neck, chest, and back.', 'Appendicular is the appendages plus the bones that attach them to the trunk.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §7.1; E-AP-070, E-AP-071, E-AP-072.', '["E-AP-070","E-AP-071","E-AP-072"]'::jsonb, NULL),
('ap-q17', 'anatomy-physiology', 'bone-tissue', 'What is the microscopic structural unit of compact bone?', '[{"id":"a","text":"A sarcomere"},{"id":"b","text":"An osteon (Haversian system)"},{"id":"c","text":"A Meissner corpuscle"},{"id":"d","text":"An intercalated disc"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The microscopic structural unit of compact bone is called an osteon, or Haversian system.', 'This unit is also called a Haversian system.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §6.3; E-AP-076.', '["E-AP-076"]'::jsonb, NULL),
('ap-q18', 'anatomy-physiology', 'bone-tissue', 'In some spongy bone, red marrow fills the spaces. What process happens there?', '[{"id":"a","text":"Hematopoiesis (blood-cell production)"},{"id":"b","text":"Evaporative cooling of sweat"},{"id":"c","text":"Release of acetylcholine at the NMJ"},{"id":"d","text":"Formation of a synovial joint cavity"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Spaces in some spongy bones contain red marrow, where hematopoiesis (blood-cell production) occurs. Bones also store calcium and phosphate.', 'Red marrow is where new blood cells are made.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §6.3 and §7.1; E-AP-078, E-AP-073.', '["E-AP-078","E-AP-073"]'::jsonb, NULL),
('ap-q19', 'anatomy-physiology', 'bone-tissue', 'Blood calcium is too low. What does parathyroid hormone (PTH) do to bone tissue in that situation?', '[{"id":"a","text":"It stimulates osteoclasts so calcium is released from bone into the blood"},{"id":"b","text":"It converts cartilage directly into vitamin D inside the osteon"},{"id":"c","text":"It stops all hematopoiesis in red marrow"},{"id":"d","text":"It turns synovial joints into synarthroses"}]'::jsonb, 'a', 'multiple-choice', NULL, 'When blood calcium is low, PTH stimulates osteoclast proliferation and bone resorption, releasing calcium into the blood.', 'PTH raises blood calcium by taking mineral from bone.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'OpenStax A&P 2e §6.7; E-AP-079.', '["E-AP-079"]'::jsonb, NULL),
('ap-q20', 'anatomy-physiology', 'bone-tissue', 'Cartilage is described as avascular. What does that mean?', '[{"id":"a","text":"It is a freely moveable synovial joint"},{"id":"b","text":"It is the same tissue as compact bone osteons"},{"id":"c","text":"It pumps blood into arteries"},{"id":"d","text":"It has no blood vessels supplying it"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Cartilage is avascular: it has no blood vessels. That is why damaged cartilage does not repair itself as readily as most tissues.', 'Avascular means there are no blood vessels in that tissue.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §6.4; E-AP-150.', '["E-AP-150"]'::jsonb, NULL),
('ap-q21', 'anatomy-physiology', 'bone-tissue', 'In endochondral ossification, a hyaline cartilage model is present before bone appears. What is the correct relationship between that cartilage and the bone that follows?', '[{"id":"a","text":"The cartilage itself turns into bone by changing cell type in place"},{"id":"b","text":"The cartilage is a template that is replaced by new bone; cartilage does not become bone"},{"id":"c","text":"The cartilage remains forever as the only tissue of the diaphysis"},{"id":"d","text":"The cartilage is converted into epidermis by UV light"}]'::jsonb, 'b', 'multiple-choice', NULL, 'In endochondral ossification, bone develops by replacing hyaline cartilage. Cartilage does not become bone; it serves as a template that is completely replaced by new bone.', 'Think replace the model, not the model magically becomes mineral.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §6.4; E-AP-151.', '["E-AP-151"]'::jsonb, NULL),
('ap-q22', 'anatomy-physiology', 'bone-tissue', 'What is the epiphyseal plate, and what happens when its cartilage is fully replaced by bone?', '[{"id":"a","text":"It is compact bone that stores yellow marrow; replacement starts hematopoiesis"},{"id":"b","text":"It is a layer of hyaline cartilage that lets a long bone grow in length; after replacement, an epiphyseal line remains and length growth stops"},{"id":"c","text":"It is a Meissner corpuscle that detects light touch"},{"id":"d","text":"It is a motor end-plate that releases acetylcholine"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The epiphyseal plate is a layer of hyaline cartilage and is the area of growth in a long bone. When cartilage there is replaced by bone, longitudinal growth stops and an epiphyseal line remains.', 'This plate is why children can still get taller.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax A&P 2e §6.4; E-AP-152.', '["E-AP-152"]'::jsonb, NULL),
('ap-q23', 'anatomy-physiology', 'joints', 'How is a synovial joint structurally different from a fibrous joint?', '[{"id":"a","text":"A synovial joint unites bones only with fibrous connective tissue and has no cavity"},{"id":"b","text":"A synovial joint has a fluid-filled joint cavity; a fibrous joint unites bones with fibrous connective tissue"},{"id":"c","text":"A synovial joint is always immobile, and a fibrous joint is always freely moveable"},{"id":"d","text":"A synovial joint is found only in the epidermis"}]'::jsonb, 'b', 'multiple-choice', NULL, 'In a fibrous joint, adjacent bones are united by fibrous connective tissue. In a synovial joint, the bones meet inside a fluid-filled joint cavity rather than being directly connected that way. Cartilaginous joints are joined by hyaline cartilage or fibrocartilage.', 'Look for the lubricating space between the bones.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §9.1; E-AP-154.', '["E-AP-154"]'::jsonb, NULL),
('ap-q24', 'anatomy-physiology', 'joints', 'A synarthrosis is a joint that is best described as:', '[{"id":"a","text":"Freely moveable like every synovial joint"},{"id":"b","text":"The microscopic unit of compact bone"},{"id":"c","text":"A hypotonic sweat gland"},{"id":"d","text":"Immobile"}]'::jsonb, 'd', 'multiple-choice', NULL, 'A synarthrosis is an immobile joint. An amphiarthrosis is slightly moveable, and a diarthrosis is a freely moveable joint.', 'This functional class is the immobile one, not the freely moveable one.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §9.1; E-AP-155.', '["E-AP-155"]'::jsonb, NULL),
('ap-q25', 'anatomy-physiology', 'joints', 'Which two joints are the body’s only ball-and-socket joints?', '[{"id":"a","text":"Elbow and knee"},{"id":"b","text":"Hip and shoulder"},{"id":"c","text":"An osteon and a sarcomere"},{"id":"d","text":"The epiphyseal plate and the stratum corneum"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The hip joint and the glenohumeral (shoulder) joint are the only ball-and-socket joints of the body. Ball-and-socket joints also have the greatest range of motion among synovial types.', 'These two joints are named as the only ball-and-socket joints of the body.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §9.4; E-AP-087, E-AP-088.', '["E-AP-087","E-AP-088"]'::jsonb, NULL),
('ap-q26', 'anatomy-physiology', 'joints', 'Which pair names the functional class of synovial joints and the synovial type with the greatest range of motion?', '[{"id":"a","text":"Synarthrosis; hinge"},{"id":"b","text":"Amphiarthrosis; pivot"},{"id":"c","text":"Diarthrosis; ball-and-socket"},{"id":"d","text":"Synarthrosis; plane"}]'::jsonb, 'c', 'multiple-choice', NULL, 'All synovial joints are functionally classified as diarthroses (freely moveable). The joint with the greatest range of motion is the ball-and-socket joint.', 'Freely moveable is one functional class; the ball-and-socket type has the greatest range of motion.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'OpenStax A&P 2e §9.1 and §9.4; E-AP-156, E-AP-088.', '["E-AP-156","E-AP-088"]'::jsonb, NULL),
('ap-q27', 'anatomy-physiology', 'joints', 'How is a tendon different from a ligament?', '[{"id":"a","text":"A tendon attaches a muscle to bone; ligaments are strong bands of fibrous connective tissue"},{"id":"b","text":"A tendon stores red marrow; a ligament synthesizes vitamin D in the epidermis"},{"id":"c","text":"A tendon is a Meissner corpuscle; a ligament is a Pacinian corpuscle"},{"id":"d","text":"A tendon is an osteon; a ligament is a sarcomere"}]'::jsonb, 'a', 'multiple-choice', NULL, 'A tendon is the dense connective tissue structure that attaches a muscle to bone. Ligaments are strong bands of fibrous connective tissue.', 'One structure is named as the muscle-to-bone attachment.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §9.4; E-AP-089.', '["E-AP-089"]'::jsonb, NULL),
('ap-q28', 'anatomy-physiology', 'skeletal-conditions', 'Osteoarthritis is best described as:', '[{"id":"a","text":"A softening of bone from vitamin D deficiency in children only"},{"id":"b","text":"Needle-shaped urate crystals in a joint"},{"id":"c","text":"A toxin made by Clostridium botulinum"},{"id":"d","text":"A degenerative joint disease in which joint tissues break down over time"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Osteoarthritis is a degenerative joint disease in which the tissues in the joint break down over time.', 'This is wear-and-breakdown of joint tissues, not an infection toxin.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'nih-niams', 'NIAMS Osteoarthritis; E-AP-096.', '["E-AP-096"]'::jsonb, NULL),
('ap-q29', 'anatomy-physiology', 'skeletal-conditions', 'Osteoporosis develops when bone mineral density and bone mass decrease. When do people typically notice it?', '[{"id":"a","text":"They typically do not have symptoms until they break a bone"},{"id":"b","text":"It is noticed as soon as sweat evaporates from the skin"},{"id":"c","text":"It is noticed only as a first-degree sunburn"},{"id":"d","text":"It is noticed when varicella-zoster virus reactivates"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Osteoporosis develops when bone mineral density and bone mass decrease, which increases fracture risk. People typically do not have symptoms until they break a bone.', 'This bone-mass disease often stays quiet until a fracture happens.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'nih-niams', 'NIAMS Osteoporosis; E-AP-101.', '["E-AP-101"]'::jsonb, NULL),
('ap-q30', 'anatomy-physiology', 'skeletal-conditions', 'Vitamin D is needed to absorb calcium and phosphorus. If that vitamin is lacking, which pair of outcomes matches age?', '[{"id":"a","text":"Children may develop rickets; elderly people may develop osteomalacia (softening of the bones)"},{"id":"b","text":"Children develop melanoma; elderly people develop HPV"},{"id":"c","text":"Children develop tetanus lockjaw; elderly people develop chickenpox only"},{"id":"d","text":"Children develop synovial cavities; elderly people develop stratum lucidum"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Vitamin D is essential for absorption of calcium and phosphorus. Lack of vitamin D can lead to rickets in children and to osteomalacia, a softening of the bones, in elderly individuals.', 'The same nutrient problem shows up with different names in growing versus older bones.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'OpenStax A&P 2e §5.3 and MedlinePlus Osteomalacia; E-AP-145, E-AP-157.', '["E-AP-145","E-AP-157"]'::jsonb, NULL),
('ap-q31', 'anatomy-physiology', 'skeletal-conditions', 'In the Salter-Harris system, a Type I (Slipped) fracture goes:', '[{"id":"a","text":"Through the physis (growth plate) only"},{"id":"b","text":"Through the physis and the metaphysis"},{"id":"c","text":"Through the physis into the epiphysis"},{"id":"d","text":"Through the epiphysis, physis, and metaphysis together"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Salter-Harris Type I (Slipped) goes through the physis. Type II also involves the metaphysis, Type III involves the epiphysis, and Type IV goes through epiphysis, physis, and metaphysis.', 'Type I stays in the growth-plate layer rather than adding a bone-end fragment.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'ncbi-statpearls', 'StatPearls Salter-Harris Fracture; E-AP-093.', '["E-AP-093"]'::jsonb, NULL),
('ap-q32', 'anatomy-physiology', 'muscle-physiology', 'Besides producing movement, skeletal muscle also helps maintain posture and contributes to homeostasis by:', '[{"id":"a","text":"Synthesizing cholecalciferol from UV light"},{"id":"b","text":"Storing yellow marrow in the epidermis"},{"id":"c","text":"Forming a fluid-filled synovial cavity"},{"id":"d","text":"Generating heat when ATP is used"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Skeletal muscles produce movement, help maintain posture, and generate heat. Muscle contraction requires ATP, and breaking down ATP produces heat.', 'Think about why you warm up when you exercise or shiver when you are cold.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §10.2; E-AP-139, E-AP-160.', '["E-AP-139","E-AP-160"]'::jsonb, NULL),
('ap-q33', 'anatomy-physiology', 'muscle-physiology', 'The functional unit of a skeletal muscle fiber, running from one Z-disc to the next, is the:', '[{"id":"a","text":"Osteon"},{"id":"b","text":"Sarcomere"},{"id":"c","text":"Pacinian corpuscle"},{"id":"d","text":"Epiphyseal line"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The sarcomere is the functional unit of the muscle fiber, bordered by Z-discs. Thin filaments are actin; thick filaments are myosin.', 'Thin actin filaments and thick myosin filaments are arranged inside this unit.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §10.2; E-AP-164.', '["E-AP-164"]'::jsonb, NULL),
('ap-q34', 'anatomy-physiology', 'muscle-physiology', 'At the neuromuscular junction, what chemical messenger does the motor neuron release to signal the muscle fiber?', '[{"id":"a","text":"Melanin"},{"id":"b","text":"Acetylcholine (ACh)"},{"id":"c","text":"Vitamin D3 (cholecalciferol)"},{"id":"d","text":"Urate"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The neuromuscular junction is where a motor neuron’s terminal meets the muscle fiber. The axon terminal releases acetylcholine (ACh), which binds receptors on the motor end-plate.', 'The messenger crosses a tiny synaptic cleft to receptors on the motor end-plate.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §10.2; E-AP-165.', '["E-AP-165"]'::jsonb, NULL),
('ap-q35', 'anatomy-physiology', 'muscle-physiology', 'In excitation-contraction coupling, what must happen before a skeletal muscle fiber can contract?', '[{"id":"a","text":"The fiber must fire an action potential; calcium ions are then released from the sarcoplasmic reticulum"},{"id":"b","text":"The epidermis must make vitamin D; phosphate is then stored in sweat"},{"id":"c","text":"The synovial cavity must fill with marrow; sodium is stored in cartilage"},{"id":"d","text":"The hair follicle must enter telogen; melanin is released from osteoclasts"}]'::jsonb, 'a', 'multiple-choice', NULL, 'For a skeletal muscle fiber to contract, its membrane must be excited—it must fire an action potential. That excitation is coupled to contraction by release of calcium ions (Ca++) from the sarcoplasmic reticulum (SR).', 'First the membrane is excited electrically; then calcium is freed inside the fiber.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax A&P 2e §10.2; E-AP-166.', '["E-AP-166"]'::jsonb, NULL),
('ap-q36', 'anatomy-physiology', 'muscle-physiology', 'T-tubules carry an action potential into the interior of a skeletal muscle fiber. What happens next that lets sarcomeres contract?', '[{"id":"a","text":"Keratin in the stratum corneum absorbs the action potential"},{"id":"b","text":"Calcium channels in the nearby SR open, calcium enters the sarcoplasm, and sarcomeres contract"},{"id":"c","text":"The epiphyseal plate converts to an epiphyseal line immediately"},{"id":"d","text":"Apocrine glands release organic sweat into the synaptic cleft"}]'::jsonb, 'b', 'multiple-choice', NULL, 'T-tubules carry the action potential into the fiber, triggering opening of calcium channels in the adjacent sarcoplasmic reticulum. Arrival of Ca++ in the sarcoplasm initiates contraction of the sarcomeres. That sequence is the heart of excitation-contraction coupling.', 'The tubules are a path for the electrical signal to the calcium store.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'OpenStax A&P 2e §10.2; E-AP-167, E-AP-166.', '["E-AP-167","E-AP-166"]'::jsonb, NULL),
('ap-q37', 'anatomy-physiology', 'muscle-physiology', 'When the biceps brachii flexes the forearm, the triceps brachii can extend it. In that pairing, the triceps is acting as:', '[{"id":"a","text":"The antagonist (opposite action of the prime mover)"},{"id":"b","text":"An eccrine sweat gland"},{"id":"c","text":"A Pacinian corpuscle"},{"id":"d","text":"Red marrow"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The biceps brachii flexes the forearm, and the triceps brachii extends it. A muscle with the opposite action of the prime mover (agonist) is called an antagonist.', 'The muscle with the opposite action is not the prime mover.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §11.1; E-AP-121. Biceps/triceps actions: EVIDENCE_MATRIX_2027.md §3 (SOURCE-VERIFIED).', '["E-AP-121"]'::jsonb, NULL),
('ap-q38', 'anatomy-physiology', 'muscle-types', 'Cardiac muscle tissue is found only in the heart. What is a main job of its coordinated contractions?', '[{"id":"a","text":"To evaporate sweat from the epidermis"},{"id":"b","text":"To replace hyaline cartilage in the epiphyseal plate"},{"id":"c","text":"To produce hypotonic eccrine sweat"},{"id":"d","text":"To pump blood into the vessels of the circulatory system"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Cardiac muscle tissue is found only in the heart. Highly coordinated contractions pump blood into the vessels of the circulatory system.', 'This tissue’s job is moving blood, not cooling the skin.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'OpenStax A&P 2e §10.7; E-AP-161.', '["E-AP-161"]'::jsonb, NULL),
('ap-q39', 'anatomy-physiology', 'muscle-types', 'Which description of cardiac muscle tissue is correct?', '[{"id":"a","text":"It is striated, organized into sarcomeres, and connected at the ends of fibers by intercalated discs"},{"id":"b","text":"It is nonstriated and found only in the epidermis"},{"id":"c","text":"It is the microscopic structural unit of compact bone"},{"id":"d","text":"It is found in the walls of arteries and veins as involuntary smooth muscle"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Cardiac muscle is striated and organized into sarcomeres. Fibers are connected to one another at their ends by intercalated discs. Coordinated cardiac contractions pump blood into the circulatory vessels.', 'Look for striations, sarcomeres, and the discs that join neighboring fibers.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax A&P 2e §10.7; E-AP-162, E-AP-161.', '["E-AP-162","E-AP-161"]'::jsonb, NULL),
('ap-q40', 'anatomy-physiology', 'muscle-types', 'Smooth muscle is described as involuntary. Where is it found?', '[{"id":"a","text":"Only in the epidermis between Meissner corpuscles"},{"id":"b","text":"In the walls of hollow organs and in the walls of arteries and veins"},{"id":"c","text":"Only as the osteon of compact bone"},{"id":"d","text":"Only attaching biceps brachii to the forearm bones"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Smooth muscle is nonstriated and is not under voluntary control. It is present in the walls of hollow organs and in the walls of passageways such as arteries and veins.', 'Look for hollow organs and the walls of arteries and veins.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'OpenStax A&P 2e §10.8; E-AP-163.', '["E-AP-163"]'::jsonb, NULL),
('ap-q41', 'anatomy-physiology', 'listed-muscles', 'Which description matches rectus abdominis?', '[{"id":"a","text":"It originates on the sternum, ribs 6–12, and lumbar vertebrae; inserts on the central tendon; and changes thoracic volume during inhalation and exhalation"},{"id":"b","text":"It originates on the pubis; inserts on the sternum and ribs 5 and 7; and flexes the vertebral column during a sit-up"},{"id":"c","text":"It originates on the anterior superior iliac spine; inserts on the medial side of the proximal tibia; and flexes the knee and flexes, abducts, and laterally rotates at the hip"},{"id":"d","text":"It originates on the skull and vertebral column; inserts on the acromion and spine of the scapula and the clavicle; and elevates the shoulders"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Rectus abdominis originates on the pubis and inserts on the sternum and ribs 5 and 7. It is the prime mover for sitting up (flexion of the vertebral column).', 'This muscle is the prime mover for sitting up.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'EVIDENCE_MATRIX_2027.md §3 Rectus abdominis (SOURCE-VERIFIED O/I/A); OpenStax A&P 2e §11.4 Table 11.6.', '["E-AP-120"]'::jsonb, NULL),
('ap-q42', 'anatomy-physiology', 'listed-muscles', 'Which description matches the diaphragm?', '[{"id":"a","text":"On the pubis; it flexes the vertebral column in a sit-up"},{"id":"b","text":"On the central tendon; it changes thoracic volume during inhalation and exhalation"},{"id":"c","text":"On the acromion of the scapula; it shrugs the shoulders"},{"id":"d","text":"On the medial side of the proximal tibia; it flexes the knee and flexes, abducts, and laterally rotates at the hip"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The diaphragm inserts on the central tendon. It is the prime mover that changes thoracic volume for inhalation and exhalation.', 'This muscle’s insertion is a tendon in the center, not a limb bone.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'EVIDENCE_MATRIX_2027.md §3 Diaphragm (SOURCE-VERIFIED O/I/A); OpenStax A&P 2e §11.4 Table 11.7.', '["E-AP-120"]'::jsonb, NULL),
('ap-q43', 'anatomy-physiology', 'listed-muscles', 'What is one action of trapezius?', '[{"id":"a","text":"It flexes the forearm at the elbow"},{"id":"b","text":"It elevates the shoulders, as in shrugging"},{"id":"c","text":"It is the prime mover of sitting up"},{"id":"d","text":"It pumps blood into the aorta"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Trapezius inserts on the acromion and spine of the scapula and on the clavicle. One action is elevating the shoulders (shrugging). It can also pull the shoulder blades together and tilt the head backwards.', 'Picture raising the shoulders toward the ears.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'EVIDENCE_MATRIX_2027.md §3 Trapezius (SOURCE-VERIFIED O/I/A); OpenStax A&P 2e §11.5 Table 11.8.', '["E-AP-120"]'::jsonb, NULL),
('ap-q44', 'anatomy-physiology', 'listed-muscles', 'Sartorius extends from the anterior superior iliac spine to the medial side of the proximal tibia. Which set of actions matches that muscle?', '[{"id":"a","text":"It only plantarflexes the foot at the ankle"},{"id":"b","text":"It flexes the leg at the knee and flexes, abducts, and laterally rotates at the hip"},{"id":"c","text":"It is the prime mover of inhalation by inserting on a central tendon"},{"id":"d","text":"It produces hypotonic sweat on the forehead"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Sartorius runs from the anterior superior iliac spine to the medial proximal tibia. It flexes the leg at the knee and flexes, abducts, and laterally rotates at the hip.', 'This long strap muscle acts at both the knee and the hip.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'openstax', 'EVIDENCE_MATRIX_2027.md §3 Sartorius (SOURCE-VERIFIED O/I/A); OpenStax A&P 2e §11.6.', '["E-AP-120"]'::jsonb, NULL),
('ap-q45', 'anatomy-physiology', 'listed-muscles', 'What is one action of serratus anterior on the scapula?', '[{"id":"a","text":"It extends the forearm"},{"id":"b","text":"It synthesizes vitamin D in the epidermis"},{"id":"c","text":"It stores red marrow"},{"id":"d","text":"It protracts the scapula"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Serratus anterior inserts on the anterior surface of the vertebral border of the scapula and protracts the scapula. (This item does not use a single rib-number origin, because sources give a range.)', 'Protraction is the action of this muscle on the scapula.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'EVIDENCE_MATRIX_2027.md §3 Serratus anterior (SOURCE-VERIFIED insertion and action; origin rib range is HUMAN-REVIEW and is not tested); OpenStax A&P 2e §11.5 Table 11.8.', '["E-AP-120"]'::jsonb, NULL);

create index if not exists anatomy_physiology_questions_topic_id_idx on public.anatomy_physiology_questions (topic_id);
create index if not exists anatomy_physiology_questions_verification_status_idx on public.anatomy_physiology_questions (verification_status);

-- ecology_questions: 40 rows

create table if not exists public.ecology_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint ecology_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint ecology_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.ecology_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('eco-q1', 'ecology', 'organization-and-energy', 'Levels of ecological organization are listed as Individual → Population → Community → Ecosystem → Biome → Biosphere. Which level comes immediately after Community?', '[{"id":"a","text":"Population"},{"id":"b","text":"Individual"},{"id":"c","text":"Biosphere"},{"id":"d","text":"Ecosystem"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The printed order is Individual → Population → Community → Ecosystem → Biome → Biosphere, so Ecosystem follows Community. Population and Individual come earlier; Biosphere is last.', 'Use the printed arrow sequence. Skip levels that appear before Community and the last level in the list.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md organization sequence; EVIDENCE_MATRIX_2027.md V-ORG.', '["V-ORG"]'::jsonb, NULL),
('eco-q2', 'ecology', 'organization-and-energy', 'Which description matches a population?', '[{"id":"a","text":"All parts of Earth inhabited by life"},{"id":"b","text":"A large area of land with similar climate, plants, and animals"},{"id":"c","text":"A group of interbreeding organisms of the same species living in the same area at the same time"},{"id":"d","text":"The different species in an area and the interactions among them"}]'::jsonb, 'c', 'multiple-choice', NULL, 'A population is a group of interbreeding organisms that are members of the same species living in the same area at the same time. The other choices describe the biosphere, a biome, and a community.', 'Look for one species sharing a place and time, not every species in an area and not the whole planet.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'OpenStax Biology 2e §44.1; V-F6. Distractors from V-F7, V-F9, V-F10.', '["V-F6","V-F7","V-F9","V-F10"]'::jsonb, NULL),
('eco-q3', 'ecology', 'organization-and-energy', 'How does a biological community differ from a population?', '[{"id":"a","text":"A community is one species in one area; a population includes every living and nonliving thing there"},{"id":"b","text":"A community is all of Earth inhabited by life; a population is a climate zone"},{"id":"c","text":"A community includes the different species in an area and their interactions; a population is one species in one area at one time"},{"id":"d","text":"A community is only the nonliving parts of an area; a population is only plants"}]'::jsonb, 'c', 'multiple-choice', NULL, 'A biological community consists of the different species within an area and the interactions among them. A population is one species living in the same area at the same time. An ecosystem, not a community, adds abiotic components.', 'Ask whether more than one species is included, and whether nonliving things are part of the definition.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F6 and V-F7. Ecosystem contrast V-F8.', '["V-F6","V-F7","V-F8"]'::jsonb, NULL),
('eco-q4', 'ecology', 'organization-and-energy', 'Which statement describes an ecosystem?', '[{"id":"a","text":"It is only the members of one species that can interbreed in one place"},{"id":"b","text":"It is a name for Earth’s atmosphere above the clouds only"},{"id":"c","text":"It is a list of greenhouse gases that trap heat"},{"id":"d","text":"It includes the living organisms in an area and their interactions with nonliving parts of that area, such as air, water, and soil"}]'::jsonb, 'd', 'multiple-choice', NULL, 'An ecosystem is composed of the biotic components in an area along with the abiotic components, including air, water, and soil. One interbreeding species is a population. Greenhouse gases are a climate topic, not the definition of an ecosystem.', 'Look for both living (biotic) and nonliving (abiotic) parts.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'V-F8.', '["V-F8"]'::jsonb, NULL),
('eco-q5', 'ecology', 'organization-and-energy', 'What do food webs illustrate?', '[{"id":"a","text":"How alleles move across a species’ range"},{"id":"b","text":"How mountains create dry leeward climates"},{"id":"c","text":"How sulfur dioxide becomes acid rain"},{"id":"d","text":"How energy flows directionally through ecosystems"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Food webs illustrate how energy flows directionally through ecosystems. Gene flow, rain shadows, and acid rain are different processes.', 'Think about what is passed from one feeding level to the next, and in which direction.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F12.', '["V-F12"]'::jsonb, NULL),
('eco-q6', 'ecology', 'organization-and-energy', 'Which statement about ecological pyramids is accurate?', '[{"id":"a","text":"Energy pyramids are often inverted because heat is created at every step"},{"id":"b","text":"Pyramids of numbers are always upright in every ecosystem"},{"id":"c","text":"Energy pyramids must stay upright because some energy is lost as heat at each transfer, so less energy is available at each higher trophic level"},{"id":"d","text":"Biomass pyramids can never be inverted"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Energy pyramids must always be upright because during energy transfer some energy is lost as heat, so less energy is available at each higher trophic level. Pyramids of numbers can be upright or inverted. Biomass pyramids can also be inverted in some ecosystems.', 'Compare energy pyramids with pyramids of numbers or biomass. Which shape is required by energy loss as heat?', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F15, V-F16, V-F17. Does not use the 10% rule (SN1).', '["V-F15","V-F16","V-F17"]'::jsonb, NULL),
('eco-q7', 'ecology', 'organization-and-energy', 'What is a biogeochemical cycle?', '[{"id":"a","text":"The always-upright shape of an energy pyramid"},{"id":"b","text":"The maximum population size an environment can support"},{"id":"c","text":"The deflection of moving air to the right in the Northern Hemisphere"},{"id":"d","text":"The recycling of inorganic matter between living organisms and their environment"}]'::jsonb, 'd', 'multiple-choice', NULL, 'A biogeochemical cycle is the recycling of inorganic matter between living organisms and their environment. The other choices describe energy pyramids, carrying capacity, and the Coriolis effect.', 'The name combines biology with geology and chemistry. What is being recycled?', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F18.', '["V-F18"]'::jsonb, NULL),
('eco-q8', 'ecology', 'communities-and-succession', 'When does primary succession occur?', '[{"id":"a","text":"When two species compete for all the same resources in one niche"},{"id":"b","text":"When a disturbance leaves remnants of the previous community"},{"id":"c","text":"When newly exposed or newly formed land is colonized by living things"},{"id":"d","text":"When a community stays unchanged until the next fire or storm"}]'::jsonb, 'c', 'multiple-choice', NULL, 'In primary succession, newly exposed or newly formed land is colonized by living things. Secondary succession is when part of an ecosystem is disturbed and remnants of the previous community remain. Competitive exclusion and climax are different ideas.', 'Compare brand-new ground with a place that still has leftover community.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'V-F19. Seral stages are not tested (SN5).', '["V-F19"]'::jsonb, NULL),
('eco-q9', 'ecology', 'communities-and-succession', 'In a mutualism, what happens to the two species?', '[{"id":"a","text":"One species benefits and the other is harmed"},{"id":"b","text":"One species benefits and the other is neither helped nor harmed"},{"id":"c","text":"Both species are harmed by sharing a niche"},{"id":"d","text":"Both species benefit from the interaction"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Mutualism is a symbiotic relationship in which two species benefit from their interaction. Parasitism benefits the parasite and harms the host. Commensalism benefits one species and neither helps nor harms the other.', 'Compare mutualism with parasitism and commensalism.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F24. Uses the broad OpenStax definition of symbiosis (HR9).', '["V-F24"]'::jsonb, NULL),
('eco-q10', 'ecology', 'communities-and-succession', 'The competitive exclusion principle says that two species cannot coexist in a community if they are competing for all the same resources. What does that mean about their niches?', '[{"id":"a","text":"Two species must always live in different biomes"},{"id":"b","text":"Two species cannot share a food web at any trophic level"},{"id":"c","text":"Two species cannot both be r-selected"},{"id":"d","text":"Two species cannot occupy the same niche in a habitat"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The competitive exclusion principle states that two species cannot occupy the same niche in a habitat: they cannot coexist if they compete for all the same resources. It does not require different biomes or forbid sharing a food web at different niches.', 'The principle is about the same niche and the same full set of resources, not about biomes or life-history labels.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'V-F23.', '["V-F23"]'::jsonb, NULL),
('eco-q11', 'ecology', 'populations-and-evolution', 'What is carrying capacity, often written as K?', '[{"id":"a","text":"The number of trophic levels in a food web"},{"id":"b","text":"The fraction of energy lost as heat at one transfer"},{"id":"c","text":"The maximum population size that a particular environment can support"},{"id":"d","text":"The number of species in a community"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Carrying capacity, or K, is the maximum population size that a particular environment can support. It is not a count of trophic levels or species.', 'This quantity is an environmental limit on population size, not a count of species or food-web steps.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F26. Overshoot and dieback are not tested (SN3).', '["V-F26"]'::jsonb, NULL),
('eco-q12', 'ecology', 'populations-and-evolution', 'How does logistic growth differ from exponential growth in a limited environment?', '[{"id":"a","text":"Logistic growth assumes unlimited resources and never levels off"},{"id":"b","text":"Logistic growth occurs only in deserts, and exponential growth occurs only in rainforests"},{"id":"c","text":"Exponential growth is possible only when resources are unlimited; with limited resources, growth slows and can plateau at carrying capacity"},{"id":"d","text":"Exponential growth is the same as a Type I survivorship curve"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Exponential growth is possible only when infinite natural resources are available, which is not the case in the real world. With limited resources, growth can slow and plateau at carrying capacity (logistic growth). This item does not use a doubling-time formula.', 'Ask whether resources stay unlimited, and whether population size can level off.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F27 qualitative only; no equations (SN24).', '["V-F27"]'::jsonb, NULL),
('eco-q13', 'ecology', 'populations-and-evolution', 'Most density-dependent factors that regulate population growth are biological. Which set matches that description?', '[{"id":"a","text":"Weather, earthquakes, and chemical pollution"},{"id":"b","text":"Coriolis deflection and rain shadows"},{"id":"c","text":"Predation, competition, accumulated waste, and disease"},{"id":"d","text":"Solar panel manufacturing and nuclear waste storage"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Most density-dependent factors are biotic and include predation, inter- and intraspecific competition, accumulation of waste, and diseases. Weather, natural disasters, and pollution are typically density-independent.', 'Density-dependent examples here are living interactions and their by-products, not weather.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'V-F28. Contrast V-F29.', '["V-F28","V-F29"]'::jsonb, NULL),
('eco-q14', 'ecology', 'populations-and-evolution', 'A forest fire kills deer whether the deer population is dense or sparse. What kind of factor is the fire?', '[{"id":"a","text":"A density-dependent factor, because fires only start when deer are crowded"},{"id":"b","text":"A biogeochemical cycle, because ash returns nutrients"},{"id":"c","text":"A climax community, because fire ends succession"},{"id":"d","text":"A density-independent factor, because it influences mortality regardless of population density"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Density-independent factors influence mortality regardless of density. OpenStax includes weather, natural disasters, and pollution in that set. A forest fire is a natural disaster, so it fits that class.', 'Does the chance of dying in the fire depend on how many deer are present?', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'V-F29.', '["V-F29"]'::jsonb, NULL),
('eco-q15', 'ecology', 'populations-and-evolution', 'Which life-history pattern matches r-selected species?', '[{"id":"a","text":"They live long, mature late, and give long-term parental care to few offspring"},{"id":"b","text":"They always occupy the same niche as a K-selected species"},{"id":"c","text":"They mature early, have short lifespans, and produce many offspring that receive no parental care"},{"id":"d","text":"They cannot live below carrying capacity"}]'::jsonb, 'c', 'multiple-choice', NULL, 'r-selected species mature early, have short lifespans, and produce many offspring that receive no parental care. K-selected species live long, mature late, and provide long-term parental care to few offspring.', 'Compare early maturity and many unattended offspring with long life and few, well-cared-for offspring.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F32. Official names V-LHS. Does not treat r/K as outdated (HR10) in the keyed answer.', '["V-F32","V-LHS"]'::jsonb, NULL),
('eco-q16', 'ecology', 'populations-and-evolution', 'Stabilizing selection favors which phenotypes?', '[{"id":"a","text":"Only the two most extreme phenotypes, while selecting against the average"},{"id":"b","text":"Only phenotypes at one end of the range of variation"},{"id":"c","text":"Only alleles that arrive by gene flow"},{"id":"d","text":"An average phenotype, while selecting against extreme variation"}]'::jsonb, 'd', 'multiple-choice', NULL, 'If natural selection favors an average phenotype, selecting against extreme variation, the population undergoes stabilizing selection. Directional selection favors one end of the range. Diversifying/disruptive selection is not used as a keyed definition here.', 'Which part of the trait range is favored, and what happens to the extremes?', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F34. Disruptive vs diversifying is not keyed (HR11).', '["V-F34","V-F35"]'::jsonb, NULL),
('eco-q17', 'ecology', 'populations-and-evolution', 'How does allopatric speciation differ from sympatric speciation?', '[{"id":"a","text":"Allopatric speciation happens in the same location; sympatric speciation requires a new continent"},{"id":"b","text":"Allopatric speciation involves geographic separation of populations; sympatric speciation occurs while the parent species remains in one location"},{"id":"c","text":"Allopatric speciation is the same as genetic drift; sympatric speciation is the same as gene flow"},{"id":"d","text":"Allopatric speciation produces energy pyramids; sympatric speciation produces biomass pyramids"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Allopatric speciation involves geographic separation of populations from a parent species and subsequent evolution. Sympatric speciation occurs within a parent species remaining in one location.', 'The prefixes refer to “other homeland” versus “same homeland.”', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F39; official names V-SPE.', '["V-F39","V-SPE"]'::jsonb, NULL),
('eco-q18', 'ecology', 'populations-and-evolution', 'What is gene flow?', '[{"id":"a","text":"The movement of alleles across a species’ range as individuals move and mate"},{"id":"b","text":"A chance change in allele frequencies, including a founder effect"},{"id":"c","text":"Selection for an average phenotype"},{"id":"d","text":"Colonization of newly formed land"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Gene flow is the movement of alleles across a species’ range, relatively free because individuals can move and then mate in a new location. Genetic drift is a chance change in allele frequencies.', 'Gene flow is about alleles traveling with individuals that move, not about random sampling alone.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F41. Contrast V-F42.', '["V-F41","V-F42"]'::jsonb, NULL),
('eco-q19', 'ecology', 'terrestrial-ecosystems', 'Because Earth rotates, moving air is deflected. In the Northern Hemisphere, that deflection is toward which side of the direction of motion?', '[{"id":"a","text":"To the left"},{"id":"b","text":"Straight up, away from the surface"},{"id":"c","text":"To the right"},{"id":"d","text":"Only toward the equator, never sideways"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The Coriolis force causes moving objects, including air, to veer to the right in the Northern Hemisphere and to the left in the Southern Hemisphere. This item does not test Hadley-cell biome belts.', 'Northern and Southern Hemispheres deflect opposite ways.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'nws', 'V-F44. Mechanism of biome belts not tested (SN12).', '["V-F44"]'::jsonb, NULL),
('eco-q20', 'ecology', 'terrestrial-ecosystems', 'Winds blow perpendicular to a mountain range. Where is precipitation enhanced, and where is it drastically reduced?', '[{"id":"a","text":"Enhanced on the leeward side; reduced on the windward side"},{"id":"b","text":"Equal on both sides because of the Coriolis effect"},{"id":"c","text":"Enhanced on the windward side; drastically reduced on the leeward side"},{"id":"d","text":"Enhanced only at the equator, never on mountains"}]'::jsonb, 'c', 'multiple-choice', NULL, 'In the rain shadow effect, winds normal to a mountain range result in enhanced precipitation on the windward side and drastically reduced precipitation on the leeward side.', 'Windward faces the incoming wind; leeward is the other side of the range.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'nws', 'V-F45.', '["V-F45"]'::jsonb, NULL),
('eco-q21', 'ecology', 'terrestrial-ecosystems', 'Temperate grasslands in central North America are also known as prairies. What dominates that biome?', '[{"id":"a","text":"Broadleaf evergreen trees that never lose leaves"},{"id":"b","text":"Grasses"},{"id":"c","text":"Giant kelp forests"},{"id":"d","text":"Lichens on polar ice only"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Temperate grasslands are found throughout central North America, where they are also known as prairies. Savannas and temperate grasslands are dominated by grasses.', 'Think of open plains rather than closed-canopy forest or ocean.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F50. Does not treat savanna as a featured North American biome (HR1, HR3).', '["V-F50"]'::jsonb, NULL),
('eco-q22', 'ecology', 'terrestrial-ecosystems', 'Which statement describes subtropical deserts?', '[{"id":"a","text":"They are found only north of the Arctic Circle"},{"id":"b","text":"They have the same rainfall as tropical rainforests"},{"id":"c","text":"They are grasslands with scattered trees in Africa only"},{"id":"d","text":"They are very dry; in some years evaporation exceeds precipitation"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Subtropical deserts are very dry; in some years evaporation exceeds precipitation. They are not Arctic, not rainforest-wet, and not grasslands with scattered trees.', 'Deserts are defined here by dryness and water loss, not by polar location.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'V-F51. Distractors are not additional official biome catalog entries.', '["V-F51"]'::jsonb, NULL),
('eco-q23', 'ecology', 'terrestrial-ecosystems', 'How do many desert plants reduce water loss?', '[{"id":"a","text":"They grow giant thin leaves that stay on the plant all year"},{"id":"b","text":"They have tiny leaves or no leaves at all"},{"id":"c","text":"They live only underwater in oases"},{"id":"d","text":"They rely on rain shadows to stay wet"}]'::jsonb, 'b', 'multiple-choice', NULL, 'To reduce water loss, many desert plants have tiny leaves or no leaves at all. Ocotillo leaves, for example, appear only after rainfall and then are shed.', 'Less leaf surface means less water can evaporate from the plant.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'V-F52. No extra adaptation catalog (SN11).', '["V-F52"]'::jsonb, NULL),
('eco-q24', 'ecology', 'terrestrial-ecosystems', 'Where does Arctic tundra lie relative to boreal forest?', '[{"id":"a","text":"South of tropical rainforests at the equator"},{"id":"b","text":"North of the subarctic boreal forest, in Arctic regions of the northern hemisphere"},{"id":"c","text":"Only on the leeward side of the Sierra Nevada"},{"id":"d","text":"Only in the deep ocean"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The Arctic tundra lies north of the subarctic boreal forest and is located throughout the Arctic regions of the northern hemisphere. This item does not treat taiga and boreal forest as two different biomes.', 'Use the north-of-boreal-forest location in the Arctic, not the equator or the ocean.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F48. HR2: no taiga-versus-boreal distinction.', '["V-F48"]'::jsonb, NULL),
('eco-q25', 'ecology', 'terrestrial-ecosystems', 'When ecologists measure biodiversity, what do they take into account?', '[{"id":"a","text":"Only the height of the tallest trees"},{"id":"b","text":"Both the number of species and their relative abundance"},{"id":"c","text":"Only greenhouse-gas concentrations"},{"id":"d","text":"Only the carrying capacity of one population"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Biodiversity is a general term for the number of species present in the biosphere, taking into account both the number of species and their relative abundance to each other.', 'Diversity is not only a species count; how common each species is also matters.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F53.', '["V-F53"]'::jsonb, NULL),
('eco-q26', 'ecology', 'terrestrial-ecosystems', 'What is genetic diversity?', '[{"id":"a","text":"The number of different ecosystems on the planet or in a geographic area"},{"id":"b","text":"Genetic variation that is the raw material for evolution and adaptation in a species"},{"id":"c","text":"The always-upright shape of an energy pyramid"},{"id":"d","text":"The IUCN category Data Deficient"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Genetic diversity, or genetic variation, defines the raw material for evolution and adaptation in a species. Ecosystem diversity is the number of different ecosystems on the planet or within a given geographic area.', 'This is variation within a species that evolution can use, not a count of ecosystem types.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'openstax', 'V-F54 vs V-F55.', '["V-F54","V-F55"]'::jsonb, NULL),
('eco-q27', 'ecology', 'terrestrial-ecosystems', 'Which set is the four named ecosystem-service categories?', '[{"id":"a","text":"Primary, Secondary, Climax, Seral"},{"id":"b","text":"Solar, Hydroelectric, Wind, Nuclear"},{"id":"c","text":"Directional, Stabilizing, Disruptive, Sexual"},{"id":"d","text":"Provisioning, Regulating, Supporting, Cultural"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The four printed ecosystem-service names are Provisioning, Regulating, Supporting, and Cultural. This item does not map examples such as pollination onto those four headings.', 'Match the four service names, not succession types, energy types, or selection types.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-ES. Mapping examples to categories is SN8 / HR12.', '["V-ES"]'::jsonb, NULL),
('eco-q28', 'ecology', 'human-impact', 'What are greenhouse gases?', '[{"id":"a","text":"Gases that trap heat in the atmosphere"},{"id":"b","text":"Gases that make ocean water more basic by removing hydrogen ions"},{"id":"c","text":"Only the noble gases in Earth’s core"},{"id":"d","text":"Particles of dry acid deposition that never include gases"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Gases that trap heat in the atmosphere are called greenhouse gases. EPA’s main inventory gases include carbon dioxide, methane, nitrous oxide, and fluorinated gases. This item does not mix in OpenStax’s water-vapor list as a keyed catalog.', 'Think about what happens to heat in the air when these gases are present.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'epa', 'V-F58. Does not key OpenStax’s longer list (HR13).', '["V-F58"]'::jsonb, NULL),
('eco-q29', 'ecology', 'human-impact', 'When the ocean absorbs carbon dioxide from the atmosphere, which chemical change makes it harder for oysters and corals to build shells and skeletons?', '[{"id":"a","text":"Hydrogen-ion concentration increases, and fewer carbonate ions remain available for calcifying organisms"},{"id":"b","text":"The ocean becomes more alkaline, so carbonate ions disappear for no chemical reason"},{"id":"c","text":"Nitrogen gas turns directly into acid rain over the sea"},{"id":"d","text":"Carrying capacity of the ocean falls to zero"}]'::jsonb, 'a', 'multiple-choice', NULL, 'When CO2 is absorbed by seawater, reactions increase hydrogen-ion concentration. Excess hydrogen bonds with carbonate ions, leaving fewer carbonate ions for calcifying organisms to build shells and skeletons. This item stays qualitative and does not require a pH-unit change.', 'Follow carbon dioxide into seawater, then to hydrogen ions and carbonate.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'noaa', 'V-F60 qualitative only.', '["V-F60"]'::jsonb, NULL),
('eco-q30', 'ecology', 'human-impact', 'Which three are described as the greatest proximate threats to biodiversity?', '[{"id":"a","text":"Habitat loss, overharvesting, and the introduction of exotic species"},{"id":"b","text":"Rain shadows, Coriolis deflection, and Type I survivorship"},{"id":"c","text":"Mutualism, commensalism, and parasitism"},{"id":"d","text":"Solar, wind, and geothermal energy"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The three greatest proximate threats to biodiversity are habitat loss, overharvesting, and the introduction of exotic species. Anthropogenic climate change is named as a fourth major cause predicted to grow, not as one of those three.', 'These threats come from how people use land, harvest wild species, and move species to new places.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F61, V-F63.', '["V-F61","V-F63"]'::jsonb, NULL),
('eco-q31', 'ecology', 'human-impact', 'Which organisms are invasive species?', '[{"id":"a","text":"Native keystone species that stay inside their historic range"},{"id":"b","text":"Nonnative organisms that, when introduced outside their native range, threaten the ecosystem balance of that habitat"},{"id":"c","text":"Any species listed as Least Concern on the IUCN Red List"},{"id":"d","text":"Only plants with tiny leaves in subtropical deserts"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Invasive species are nonnative organisms that, when introduced to an area out of their native range, threaten the ecosystem balance of that habitat. No official invasive-species list is used here.', 'Two parts matter: not native to the place, and a threat to that habitat’s balance.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'openstax', 'V-F25. No invented species list (SN16).', '["V-F25"]'::jsonb, NULL),
('eco-q32', 'ecology', 'human-impact', 'Biological control of invasive species is the intentional use of which living tools?', '[{"id":"a","text":"Natural enemies (biocontrol agents) chosen to reduce the target population"},{"id":"b","text":"Pesticides, herbicides, fungicides, and insecticides only"},{"id":"c","text":"Mowing, hoeing, tilling, and barriers made with machines only"},{"id":"d","text":"Public-awareness signs with no living agents"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Biological control is the intentional manipulation of natural enemies by humans to control pests or plants. Chemical control uses pesticides and similar products. Mechanical control uses tools or machines. Cultural control includes changing practices and human behavior. Physical/manual control is not treated as a fifth official method here.', 'Match the control method to the kind of tool it uses: living agents, chemicals, machines, or human practices.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'nisic', 'V-F62; official method names V-INV-M. HR14: physical/manual not keyed as official.', '["V-F62","V-INV-M"]'::jsonb, NULL),
('eco-q33', 'ecology', 'human-impact', 'Acid rain, a form of acid deposition, forms after which pollutants are emitted and react in the atmosphere?', '[{"id":"a","text":"Sulfur dioxide (SO2) and nitrogen oxides (NOX), which form sulfuric and nitric acids"},{"id":"b","text":"Only water vapor, which becomes carbonic acid in every desert"},{"id":"c","text":"Only ozone from the IUCN Red List"},{"id":"d","text":"Only methane from biomass combustion"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Acid rain, or acid deposition, includes precipitation with acidic components such as sulfuric or nitric acid. Acid rain results when sulfur dioxide and nitrogen oxides are emitted, transported, and react with water, oxygen, and other chemicals.', 'The mineral acids in acid rain come from two common air pollutants, not from an IUCN category.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'epa', 'V-F64.', '["V-F64"]'::jsonb, NULL),
('eco-q34', 'ecology', 'human-impact', 'What is biomagnification?', '[{"id":"a","text":"The increasing concentration of persistent, toxic substances in organisms at each trophic level, from primary producers to apex consumers"},{"id":"b","text":"The always-upright shape of a pyramid of numbers"},{"id":"c","text":"The colonization of new volcanic rock"},{"id":"d","text":"The deflection of winds to the left in the Northern Hemisphere"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Biomagnification is the increasing concentration of persistent, toxic substances in organisms at each trophic level, from the primary producers to the apex consumers. Many such substances also bioaccumulate. A sharper bioaccumulation-only definition is not keyed.', 'Follow a persistent toxin from producers up to top predators.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'openstax', 'V-F65. SN19 not used as a separate definition item.', '["V-F65"]'::jsonb, NULL),
('eco-q35', 'ecology', 'human-impact', 'Nutrient runoff can cause eutrophication. What happens in that process?', '[{"id":"a","text":"Excess growth of microorganisms depletes dissolved oxygen and kills ecosystem fauna"},{"id":"b","text":"The ocean absorbs CO2 and immediately becomes a desert"},{"id":"c","text":"Energy pyramids invert because heat is created"},{"id":"d","text":"Allopatric speciation begins on every farm"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Eutrophication is a process whereby nutrient runoff causes excess growth of microorganisms, depleting dissolved oxygen levels and killing ecosystem fauna. Nitrogen and phosphorus are major limiting nutrients in most aquatic environments. Eutrophication stages are not tested as a numbered ladder.', 'Connect extra nutrients to microbial blooms, then to oxygen and animals.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'V-F66; supporting V-F67. No stage catalog (SN18).', '["V-F66","V-F67"]'::jsonb, NULL),
('eco-q36', 'ecology', 'human-impact', 'Which environmental concern is tied to nuclear power?', '[{"id":"a","text":"Nuclear reactors release large amounts of carbon dioxide while they operate"},{"id":"b","text":"Radioactive waste can remain radioactive and dangerous to human health for thousands of years, and the United States has no permanent disposal facility for high-level nuclear waste"},{"id":"c","text":"Nuclear plants cannot use metal or concrete in construction"},{"id":"d","text":"Nuclear power is the same as biomass combustion"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Nuclear reactors do not produce air pollution or carbon dioxide while operating. A major environmental concern is radioactive waste that can remain dangerous for thousands of years. The United States does not have a permanent disposal facility for high-level nuclear waste.', 'Separate what happens while a reactor runs from what happens to used fuel afterward.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'eia', 'V-F70.', '["V-F70"]'::jsonb, NULL),
('eco-q37', 'ecology', 'human-impact', 'Do solar energy technologies produce air pollution or greenhouse gases while they operate?', '[{"id":"a","text":"Yes; operating solar panels emit the same stack gases as coal plants"},{"id":"b","text":"No; they do not produce air pollution or greenhouse gases when operating, though making and disposing of the equipment still has environmental effects"},{"id":"c","text":"No, and manufacturing solar equipment has no environmental effects at all"},{"id":"d","text":"Yes; they emit sulfur dioxide in order to create acid rain"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Solar energy technologies and power plants do not produce air pollution or greenhouse gases when operating. Producing and disposing of solar technologies still have environmental effects, including land clearing that can affect habitats.', 'Separate the operating plant from the factories that make panels.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'eia', 'V-F69.', '["V-F69"]'::jsonb, NULL),
('eco-q38', 'ecology', 'human-impact', 'Which wildlife risk is described for wind turbines?', '[{"id":"a","text":"Birds and bats can be injured or killed if they fly into turbine blades"},{"id":"b","text":"Wind turbines require river water for cooling, like many steam plants"},{"id":"c","text":"Wind turbines release nitrogen oxides that become acid rain while they spin"},{"id":"d","text":"Wind turbines always invert energy pyramids"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Wind turbines do not release emissions that pollute air or water in normal operation and do not require water for cooling. Birds and bats are at risk of injury or death if they fly into turbine blades.', 'Think about flying animals and moving blades, not smokestack gases.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'eia', 'V-F72.', '["V-F72"]'::jsonb, NULL),
('eco-q39', 'ecology', 'human-impact', 'Hydropower generators do not directly emit air pollutants. What environmental problem can a dam and reservoir still cause?', '[{"id":"a","text":"They may obstruct fish migration and change water temperature, chemistry, flow, and silt loads"},{"id":"b","text":"They make energy pyramids invert in every river"},{"id":"c","text":"They are the same as nuclear high-level waste storage"},{"id":"d","text":"They always increase ocean carbonate ions"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Hydropower generators produce energy without directly emitting air pollutants, but dams and reservoirs can obstruct fish migration and change natural water temperatures, chemistry, river flow, and silt loads.', 'Think about a river that is blocked and turned into a lake.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'eia', 'V-F73.', '["V-F73"]'::jsonb, NULL),
('eco-q40', 'ecology', 'human-impact', 'On the IUCN Red List, which three categories are considered threatened with extinction?', '[{"id":"a","text":"Least Concern, Data Deficient, and Not Evaluated"},{"id":"b","text":"Vulnerable, Endangered, and Critically Endangered"},{"id":"c","text":"Extinct, Extinct in the Wild, and Near Threatened"},{"id":"d","text":"Provisioning, Regulating, and Supporting"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Species are classified into nine Red List categories. Vulnerable, Endangered, and Critically Endangered species are considered to be threatened with extinction. Criteria A–E thresholds are not tested.', 'Threatened status is the high-risk living categories, not Least Concern and not the four ecosystem-service names.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'iucn', 'V-F75. No criteria numbers (SN25).', '["V-F75"]'::jsonb, NULL);

create index if not exists ecology_questions_topic_id_idx on public.ecology_questions (topic_id);
create index if not exists ecology_questions_verification_status_idx on public.ecology_questions (verification_status);

-- water_quality_questions: 40 rows

create table if not exists public.water_quality_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint water_quality_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint water_quality_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.water_quality_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('wq-q1', 'water-quality', 'indicator-classes', 'On the 2027 adult-macroinvertebrate table, what is the title of Class 1?', '[{"id":"a","text":"Class 1 - Moderately Tolerant"},{"id":"b","text":"Class 1 - Pollution Sensitive"},{"id":"c","text":"Class 1 - Air Breathing"},{"id":"d","text":"Class 1 - Pollution Tolerant"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The table heading is Class 1 - Pollution Sensitive. Moderately Tolerant is Class 3; Pollution Tolerant is Class 4; Air Breathing is Class 5.', 'Match the Class 1 heading printed on the 2027 table. Do not reuse a Class 4 or Class 5 title.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md table header; EVIDENCE_MATRIX_2027.md V-C1.', '["V-C1"]'::jsonb, NULL),
('wq-q2', 'water-quality', 'water-monitoring', 'A water-treatment plant lets heavy particles settle before water moves through a filter. Why is this sequence useful?', '[{"id":"a","text":"Settling can remove some solids before filtration and later treatment steps."},{"id":"b","text":"Settling turns every dissolved pollutant into oxygen."},{"id":"c","text":"Settling makes untreated water safe without any more treatment."},{"id":"d","text":"Settling adds nutrients so algae can clean the water."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Settling can remove some suspended solids before filtration and other treatment steps. It does not make water safe by itself or remove every dissolved substance.', 'Think about what happens to particles that are heavy enough to sink before the water is filtered.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Ecology scope: potable water treatment.', '["RS18"]'::jsonb, NULL),
('wq-q3', 'water-quality', 'water-monitoring', 'A wastewater plant treats water before releasing it to a river. Which goal best describes why treatment is needed?', '[{"id":"a","text":"Reduce solids, harmful substances, and microbes so the release is less damaging."},{"id":"b","text":"Add untreated waste so river organisms can get more food."},{"id":"c","text":"Make the released water contain no dissolved substances at all."},{"id":"d","text":"Change every organism in the wastewater into a macroinvertebrate."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Wastewater treatment reduces solids, harmful substances, and microbes before treated water is released. Treatment does not remove every dissolved substance or turn waste into organisms.', 'Think about which unwanted materials treatment should remove or reduce before water returns to the environment.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Ecology scope: wastewater treatment.', '["RS18"]'::jsonb, NULL),
('wq-q4', 'water-quality', 'water-monitoring', 'A pond has very little dissolved oxygen. Which result is most likely for many aquatic animals?', '[{"id":"a","text":"They may become stressed because less oxygen is available for them to use."},{"id":"b","text":"They may grow faster because low oxygen always increases growth."},{"id":"c","text":"They may become pollution-sensitive organisms."},{"id":"d","text":"They may make the pond''s water less salty."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Aquatic animals use dissolved oxygen, so very little dissolved oxygen can stress them or make survival difficult. It does not turn animals into plants or change the pond''s salinity.', 'Dissolved oxygen is the oxygen available to living aquatic organisms.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'usgs-water-science-school', 'USGS Water Science School dissolved-oxygen definition and aquatic-life implications; dissolved oxygen is also a 2027 monitoring parameter.', '["V-U1","V-W5"]'::jsonb, NULL),
('wq-q5', 'water-quality', 'indicator-classes', 'On the 2027 list, which class includes Mayfly?', '[{"id":"a","text":"Class 4 - Pollution Tolerant"},{"id":"b","text":"Class 1 - Pollution Sensitive"},{"id":"c","text":"Class 5 - Air Breathing"},{"id":"d","text":"Class 3 - Moderately Tolerant"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Mayfly is a Class 1 - Pollution Sensitive name. It is not printed under Class 3, Class 4, or Class 5.', 'Find Mayfly on the adult-macroinvertebrate table and read the heading above it.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md table; V-M01, V-C1.', '["V-M01","V-C1"]'::jsonb, NULL),
('wq-q6', 'water-quality', 'macroinvertebrates', 'An adult aquatic insect has two pairs of wings, two or three tail filaments, and wings held upright. Which listed common name best matches it?', '[{"id":"a","text":"Mayfly"},{"id":"b","text":"Caddisfly"},{"id":"c","text":"Stonefly"},{"id":"d","text":"Water Penny"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Mayfly is the listed common name that matches an adult insect with two pairs of wings and tail filaments. Caddisflies, stoneflies, and water pennies have different adult features.', 'Mayflies are known for their delicate wings and tail filaments.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md adult macroinvertebrate list; common-name identification uses Mayfly, Caddisfly, Stonefly, and Water Penny.', '["V-M01","V-M02","V-M03","V-M05"]'::jsonb, NULL),
('wq-q7', 'water-quality', 'macroinvertebrates', 'Which general feeding habit best describes Tubifex in freshwater?', '[{"id":"a","text":"It feeds on organic matter in sediment."},{"id":"b","text":"It grazes algae from rocks."},{"id":"c","text":"It hunts small aquatic animals."},{"id":"d","text":"It filters tiny food particles from flowing water."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Tubifex are generally deposit feeders: they take in organic matter from bottom sediment. They are not photosynthetic plants or animals that hunt flying insects.', 'Think about an organism that lives in or near soft bottom sediment.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Macroinvertebrates scope: general ecology and feeding habits of listed organisms; Tubifex is listed.', '["RS18","V-M17"]'::jsonb, NULL),
('wq-q8', 'water-quality', 'indicator-classes', 'A stream has many mayflies and stoneflies, but very few pollution-tolerant organisms. What does this most likely suggest?', '[{"id":"a","text":"The stream likely has relatively good water quality."},{"id":"b","text":"The stream likely has poor water quality because sensitive organisms need pollution."},{"id":"c","text":"The stream has no living organisms besides the listed ones."},{"id":"d","text":"The organisms prove that the stream has a particular temperature."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Many pollution-sensitive organisms and few pollution-tolerant organisms are evidence consistent with relatively good water quality. The organisms do not prove the water is salt water or reveal its exact temperature.', 'Mayflies and stoneflies are pollution-sensitive listed organisms.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Macroinvertebrates scope: indicator classes and pollution tolerance.', '["RS18","V-M01","V-M03"]'::jsonb, NULL),
('wq-q9', 'water-quality', 'water-monitoring', 'A frog population in a pond grows for several years. Then food and space become limited, and the population stays near the same size despite new births. What idea best explains this pattern?', '[{"id":"a","text":"The pond''s carrying capacity limits the population size."},{"id":"b","text":"The frogs have stopped being part of the food web."},{"id":"c","text":"The pond has become an aquatic nuisance plant."},{"id":"d","text":"The frogs have changed into pollution-sensitive organisms."}]'::jsonb, 'a', 'multiple-choice', NULL, 'A carrying capacity is the population size an environment can support with its available resources. Limited food and space can keep a population near that level.', 'Look for the idea that food, space, and other resources set a limit on how large a population can remain.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Ecology scope: population dynamics.', '["RS18"]'::jsonb, NULL),
('wq-q10', 'water-quality', 'water-monitoring', 'After rain falls, some water flows over land into a stream. Why is this part of the water cycle important to freshwater ecosystems?', '[{"id":"a","text":"Runoff returns water to streams and can carry materials into the ecosystem."},{"id":"b","text":"Runoff changes every freshwater organism into a land organism."},{"id":"c","text":"Runoff stops evaporation from all lakes and rivers."},{"id":"d","text":"Runoff makes every stream have the same temperature."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Runoff is part of the water cycle. It returns water to freshwater systems and can carry soil, nutrients, or other materials into them, affecting the ecosystem.', 'Runoff is water moving over land toward a stream, lake, or other body of water.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Ecology scope: water cycle and freshwater ecosystem relationships.', '["RS18"]'::jsonb, NULL),
('wq-q11', 'water-quality', 'macroinvertebrates', 'In a freshwater food web, algae are eaten by mayflies, and mayflies are eaten by fish. If mayflies become much less common, what is a likely short-term effect?', '[{"id":"a","text":"Fish may have less food available."},{"id":"b","text":"Algae will stop needing sunlight."},{"id":"c","text":"The water will become saltier."},{"id":"d","text":"All fish will become pollution-sensitive organisms."}]'::jsonb, 'a', 'multiple-choice', NULL, 'If mayflies become less common, fish that eat them may have less food available. This is a population and food-web effect; it does not change the water''s salinity or the fish into another type of organism.', 'Follow the feeding relationship from algae to mayflies to fish.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Ecology and Freshwater Macroinvertebrates scope: aquatic food webs and general ecology of listed organisms.', '["RS18","V-M01"]'::jsonb, NULL),
('wq-q12', 'water-quality', 'macroinvertebrates', 'Which feeding role is common for many mayfly nymphs in freshwater?', '[{"id":"a","text":"Scraping algae and collecting small organic particles"},{"id":"b","text":"Filtering tiny food particles from the water"},{"id":"c","text":"Hunting large fish as its main food"},{"id":"d","text":"Shredding fallen leaves as its main food"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Many mayfly nymphs graze on algae and collect small organic particles. They are not plants, large-fish predators, or consumers of human-made materials.', 'Many mayfly nymphs feed on material growing on or settling over underwater surfaces.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Macroinvertebrates scope: general ecology and feeding habits of listed organisms; Mayfly is listed.', '["RS18","V-M01"]'::jsonb, NULL),
('wq-q13', 'water-quality', 'macroinvertebrates', 'On the 2027 table, which class includes Tubifex?', '[{"id":"a","text":"Class 1 - Pollution Sensitive"},{"id":"b","text":"Class 3 - Moderately Tolerant"},{"id":"c","text":"Class 4 - Pollution Tolerant"},{"id":"d","text":"Class 5 - Air Breathing"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Tubifex is Class 4 - Pollution Tolerant.', 'Find Tubifex on the table and read the heading above it.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'V-M17, V-C4.', '["V-M17","V-C4"]'::jsonb, NULL),
('wq-q14', 'water-quality', 'macroinvertebrates', 'Which habitat is most typical for many stoneflies?', '[{"id":"a","text":"Cool, moving water with plenty of dissolved oxygen"},{"id":"b","text":"A dry desert with no surface water"},{"id":"c","text":"A salty ocean beach with no freshwater"},{"id":"d","text":"A warm puddle with no oxygen"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Many stoneflies are associated with cool, flowing freshwater that has plenty of dissolved oxygen. The other choices describe places that do not fit this general habitat.', 'Stoneflies are commonly associated with clean, flowing freshwater.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Macroinvertebrates scope: general ecology and habitat of listed organisms; Stonefly is listed.', '["RS18","V-M03"]'::jsonb, NULL),
('wq-q15', 'water-quality', 'indicator-classes', 'Site A has mayflies and stoneflies. Site B has mostly Tubifex and leeches. Which site most likely has better water quality?', '[{"id":"a","text":"Site A, because mayflies and stoneflies are more pollution-sensitive indicators."},{"id":"b","text":"Site A, because mayflies always make water colder."},{"id":"c","text":"Site B, because Tubifex and leeches cannot live in freshwater."},{"id":"d","text":"Site B, because pollution-sensitive organisms prefer more pollution."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Site A most likely has better water quality because mayflies and stoneflies are listed as pollution-sensitive, while Tubifex and leeches are associated with more pollution-tolerant groups.', 'Compare the pollution-tolerance classes of the organisms found at each site.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md adult macroinvertebrate table and indicator-class headings; comparison uses listed organisms.', '["V-M01","V-M03","V-M14","V-M17","V-C1","V-C3","V-C4"]'::jsonb, NULL),
('wq-q16', 'water-quality', 'macroinvertebrates', 'What is a common ecological role of Water Penny larvae in a stream?', '[{"id":"a","text":"They scrape algae and other growth from rocks."},{"id":"b","text":"They shred fallen leaves in the stream."},{"id":"c","text":"They filter tiny food particles from the water."},{"id":"d","text":"They prey on fish as their main food."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Water Penny larvae commonly graze on algae and other growth on rocks. The other choices do not describe a freshwater macroinvertebrate feeding role.', 'Think about a small larva attached to hard surfaces in flowing water.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Freshwater Macroinvertebrates scope: general ecology and feeding habits of listed organisms; Water Penny is listed.', '["RS18","V-M05"]'::jsonb, NULL),
('wq-q17', 'water-quality', 'macroinvertebrates', 'Which observation is an example of a community interaction involving a listed macroinvertebrate?', '[{"id":"a","text":"A fish eats a mayfly nymph."},{"id":"b","text":"A thermometer measures water temperature."},{"id":"c","text":"A pH test measures how acidic or basic water is."},{"id":"d","text":"Rainwater moves over land into a stream."}]'::jsonb, 'a', 'multiple-choice', NULL, 'A fish eating a mayfly nymph is an interaction between living organisms in a freshwater community. The other choices describe monitoring or water-cycle processes rather than an interaction between organisms.', 'A community interaction involves living organisms affecting one another.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md Freshwater Ecology and Freshwater Macroinvertebrates scope: community interactions and listed organisms.', '["RS18","V-M01"]'::jsonb, NULL),
('wq-q18', 'water-quality', 'nuisance-species', 'Why can Zebra Mussels harm a freshwater ecosystem?', '[{"id":"a","text":"They can filter large amounts of food from the water and compete with native organisms."},{"id":"b","text":"They can increase water clarity without changing food availability."},{"id":"c","text":"They can make native organisms grow faster by adding food."},{"id":"d","text":"They can change only the water temperature and no other resource."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Zebra Mussels can filter plankton and other food from the water and compete with native organisms, changing resource availability and food-web relationships.', 'Think about how a nuisance species can change available food and resources.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md harmful species and Aquatic Nuisance Animals scope; Zebra Mussel is listed.', '["RS18","V-A1"]'::jsonb, NULL),
('wq-q19', 'water-quality', 'macroinvertebrates', 'A small aquatic beetle larva clings to rocks and scrapes algae from their surfaces. Which listed common name best matches it?', '[{"id":"a","text":"Water Penny"},{"id":"b","text":"Blackfly"},{"id":"c","text":"Stonefly"},{"id":"d","text":"Tubifex"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Water Penny is the listed common name that best matches an aquatic beetle larva associated with scraping algae from rocks. Blackfly, stonefly, and Tubifex have different forms and feeding roles.', 'Look for the listed name associated with a small beetle that lives on stream rocks.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md adult macroinvertebrate list; common-name identification uses Water Penny, Blackfly, Stonefly, and Tubifex.', '["V-M05","V-M12","V-M03","V-M17"]'::jsonb, NULL),
('wq-q20', 'water-quality', 'macroinvertebrates', 'An adult aquatic insect is a small beetle with hardened wing covers and is found crawling on rocks in fast-flowing streams. Which listed common name best matches it?', '[{"id":"a","text":"Riffle Beetle"},{"id":"b","text":"Mayfly"},{"id":"c","text":"Caddisfly"},{"id":"d","text":"Blackfly"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Riffle Beetle is the listed common name that best matches a small beetle associated with rocks in flowing water. Mayfly, caddisfly, and blackfly are different types of listed aquatic insects.', 'Use the beetle body covering and the flowing-stream habitat together, not just one feature.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md adult macroinvertebrate list and general ecology of listed organisms; Riffle Beetle is listed.', '["RS18","V-M06","V-M01","V-M02","V-M12"]'::jsonb, NULL),
('wq-q21', 'water-quality', 'nuisance-species', 'Eurasian Water Milfoil forms a dense mat near the surface of a lake. What is one likely ecological effect?', '[{"id":"a","text":"It can block light and crowd out native aquatic plants."},{"id":"b","text":"It can add unlimited dissolved oxygen to deep water."},{"id":"c","text":"It can turn all freshwater into salt water."},{"id":"d","text":"It can make every aquatic animal tolerate pollution."}]'::jsonb, 'a', 'multiple-choice', NULL, 'A dense Eurasian Water Milfoil mat can block light and use space and resources that native aquatic plants need. It does not add unlimited oxygen or change freshwater into salt water.', 'Think about what a thick floating plant mat can block and what resources nearby plants need.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md Aquatic Nuisance Plants scope; Eurasian Water Milfoil is listed.', '["RS18","V-P2"]'::jsonb, NULL),
('wq-q22', 'water-quality', 'nuisance-species', 'Which of these 2027 official strings is an Aquatic Nuisance Plant, not an Aquatic Nuisance Animal?', '[{"id":"a","text":"Zebra Mussel"},{"id":"b","text":"Spiny Water Flea"},{"id":"c","text":"Water Hyacinth"},{"id":"d","text":"Asian Carp"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Water Hyacinth is a nuisance plant. Zebra Mussel, Spiny Water Flea, and Asian Carp are nuisance-animal strings.', 'Compare the Aquatic Nuisance Plants list with the Aquatic Nuisance Animals list.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'V-P3 vs V-A1, V-A2, V-A4.', '["V-P3","V-A1","V-A2","V-A4"]'::jsonb, NULL),
('wq-q23', 'water-quality', 'nuisance-species', 'What is one possible ecological effect of Water Hyacinth spreading across the surface of a pond?', '[{"id":"a","text":"A dense mat can block light and reduce space available for native plants."},{"id":"b","text":"A dense mat can increase light for plants growing below it."},{"id":"c","text":"A dense mat can make every native plant grow equally well."},{"id":"d","text":"A dense mat changes the pond''s water into seawater."}]'::jsonb, 'a', 'multiple-choice', NULL, 'A dense Water Hyacinth mat can block sunlight and cover space that native plants use. Those changes can disrupt habitats and community relationships.', 'Think about what a thick floating plant mat can block or cover.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md harmful species and Aquatic Nuisance Plants scope; Water Hyacinth is listed.', '["RS18","V-P3"]'::jsonb, NULL),
('wq-q24', 'water-quality', 'nuisance-species', 'Which statement correctly compares two listed aquatic nuisance species?', '[{"id":"a","text":"Purple Loosestrife is a plant that can form dense stands, while Zebra Mussel is an animal that can compete for food."},{"id":"b","text":"Purple Loosestrife is an animal that filters plankton, while Zebra Mussel is a plant."},{"id":"c","text":"Both are monitoring parameters used to measure dissolved oxygen."},{"id":"d","text":"Both are pollution-sensitive macroinvertebrates found only in clean streams."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Purple Loosestrife is a listed nuisance plant that can form dense stands. Zebra Mussel is a listed nuisance animal that can compete with native organisms for food and other resources.', 'First identify whether each listed nuisance species is a plant or an animal.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'RULES_2027.md Aquatic Nuisance Plants and Aquatic Nuisance Animals scope; ecological comparison uses listed species.', '["RS18","V-P1","V-A1"]'::jsonb, NULL),
('wq-q25', 'water-quality', 'nuisance-species', 'Why can Asian Carp alter a freshwater community or food web?', '[{"id":"a","text":"They can compete with native fish for food and change how energy moves through the food web."},{"id":"b","text":"They are plants that compete with native fish by blocking sunlight."},{"id":"c","text":"They make native fish produce their own food."},{"id":"d","text":"They can affect only water temperature and not populations or food webs."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Asian Carp can compete with native fish for shared food resources. That competition can change population sizes and food-web relationships.', 'Consider what could happen if a new animal uses food that native animals also need.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md harmful species and Aquatic Nuisance Animals scope; Asian Carp is listed.', '["RS18","V-A4"]'::jsonb, NULL),
('wq-q26', 'water-quality', 'nuisance-species', 'The 2027 rules print both Mosquito and Asian Tiger Mosquito. How are those two strings placed?', '[{"id":"a","text":"Both are Class 5 - Air Breathing table names"},{"id":"b","text":"Both are Aquatic Nuisance Animals strings"},{"id":"c","text":"Mosquito is a Class 5 table name; Asian Tiger Mosquito is an Aquatic Nuisance Animals string"},{"id":"d","text":"Asian Tiger Mosquito is Class 5; Mosquito is an Aquatic Nuisance Plants name"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Mosquito is printed under Class 5 - Air Breathing. Asian Tiger Mosquito is an Aquatic Nuisance Animals string. They are separate official strings; this item does not claim extra biology about either name.', 'Compare the Class 5 column with the Aquatic Nuisance Animals sentence. Do not merge the two printed strings.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'V-M20 vs V-A3.', '["V-M20","V-A3"]'::jsonb, NULL),
('wq-q27', 'water-quality', 'water-monitoring', 'A stream was measured after a storm:

Time | Dissolved oxygen | Turbidity
Before rain | 8 mg/L | 3 NTU
Soon after rain | 6 mg/L | 18 NTU
Two days later | 7 mg/L | 6 NTU

Which conclusion is best supported by the data?', '[{"id":"a","text":"The storm temporarily made the water cloudier and lowered dissolved oxygen."},{"id":"b","text":"The storm permanently removed all oxygen from the stream."},{"id":"c","text":"The stream became salt water after the storm."},{"id":"d","text":"Turbidity and dissolved oxygen always increase together."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Soon after the storm, turbidity increased from 3 to 18 NTU while dissolved oxygen fell from 8 to 6 mg/L. Two days later, both values moved closer to their starting levels, supporting a temporary change.', 'Compare both measurements before rain, soon after rain, and two days later.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: interpreting sample data and relationships among parameters.', '["RS18","V-W4","V-W5"]'::jsonb, NULL),
('wq-q28', 'water-quality', 'water-monitoring', 'A water sample has a high BOD. What does that suggest, and why can it matter?', '[{"id":"a","text":"Microorganisms may use a lot of oxygen while decomposing organic matter, leaving less for aquatic life."},{"id":"b","text":"The water must contain no organisms that can decompose anything."},{"id":"c","text":"The sample must have the highest possible dissolved oxygen."},{"id":"d","text":"BOD measures how salty the water is."}]'::jsonb, 'a', 'multiple-choice', NULL, 'High BOD means microorganisms may consume a lot of oxygen while decomposing organic matter. That can leave less dissolved oxygen available for other aquatic organisms.', 'BOD describes oxygen used by microorganisms as they decompose organic matter.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'USGS Water Science School BOD definition and aquatic-life implication; BOD is also a 2027 monitoring parameter.', '["V-U7","V-W8"]'::jsonb, NULL),
('wq-q29', 'water-quality', 'water-monitoring', 'Why can a pH far outside the usual range for a freshwater ecosystem be a problem?', '[{"id":"a","text":"It can stress aquatic organisms and change how some substances behave in the water."},{"id":"b","text":"It guarantees that every organism will grow faster."},{"id":"c","text":"It proves that the water contains no dissolved substances."},{"id":"d","text":"It measures the number of macroinvertebrate species without any sample."}]'::jsonb, 'a', 'multiple-choice', NULL, 'pH describes how acidic or basic water is. A value far outside the range that organisms tolerate can stress aquatic life and affect water chemistry.', 'pH describes how acidic or basic water is, and organisms have ranges they can tolerate.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: pH and aquatic chemistry implications.', '["RS18","V-W2"]'::jsonb, NULL),
('wq-q30', 'water-quality', 'water-monitoring', 'What can increased turbidity indicate or cause in a freshwater ecosystem?', '[{"id":"a","text":"It can indicate suspended particles and reduce the light available to aquatic plants."},{"id":"b","text":"It proves that the water has no sediment or particles."},{"id":"c","text":"It always increases the amount of light reaching underwater plants."},{"id":"d","text":"It identifies the exact species of every macroinvertebrate present."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Increased turbidity can result from suspended particles such as sediment. Cloudier water can reduce light reaching aquatic plants and may affect aquatic habitats.', 'Turbidity is related to how much suspended material makes water look cloudy.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: turbidity, sedimentation pollution, and aquatic-ecology implications.', '["RS18","V-W4"]'::jsonb, NULL),
('wq-q31', 'water-quality', 'water-monitoring', 'How can high levels of nitrates and phosphates affect a freshwater ecosystem?', '[{"id":"a","text":"They can add nutrients that increase algal or plant growth and later reduce dissolved oxygen."},{"id":"b","text":"They remove all nutrients and stop plant growth."},{"id":"c","text":"They always make dissolved oxygen increase without limit."},{"id":"d","text":"They turn macroinvertebrates into monitoring instruments."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Nitrates and phosphates are nutrients. In excess, they can stimulate algal or aquatic-plant growth; decomposition and other processes can then reduce dissolved oxygen. The 2027 rules specifically list nitrates and phosphates as monitoring parameters.', 'Nitrates and phosphates are nutrients; too much of a nutrient can change plant and algae growth.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: nitrates, phosphates, nutrient cycling, and aquatic-ecology implications.', '["RS18","V-W3","V-W7"]'::jsonb, NULL),
('wq-q32', 'water-quality', 'water-monitoring', 'Two freshwater sites were tested. Site A had DO 8, BOD 2, turbidity 2, and nitrate 1. Site B had DO 3, BOD 7, turbidity 25, and nitrate 8. Which site appears healthier for many aquatic organisms?', '[{"id":"a","text":"Site A, because it has more dissolved oxygen and lower BOD, turbidity, and nitrate."},{"id":"b","text":"Site A, because higher turbidity always means cleaner water."},{"id":"c","text":"Site B, because lower dissolved oxygen gives aquatic animals more energy."},{"id":"d","text":"Site B, because higher BOD always means more oxygen is available."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Site A appears healthier for many aquatic organisms in this comparison: it has more dissolved oxygen and lower BOD, turbidity, and nitrate. The values are supplied for comparison; no single cutoff is assumed.', 'Compare all four values. More dissolved oxygen and less BOD, turbidity, and nitrate are the useful clues here.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: analysis, relationships among parameters, and inference from sample data.', '["RS18","V-W3","V-W4","V-W5","V-W7","V-W8"]'::jsonb, NULL),
('wq-q33', 'water-quality', 'water-monitoring', 'What is dissolved oxygen (DO)?', '[{"id":"a","text":"A measure of how much oxygen is dissolved in the water — the amount of oxygen available to living aquatic organisms"},{"id":"b","text":"The official 2027 title of Class 1 - Pollution Sensitive"},{"id":"c","text":"A listed Aquatic Nuisance Plant"},{"id":"d","text":"The printed common name for Tubifex"}]'::jsonb, 'a', 'multiple-choice', NULL, 'USGS: “Dissolved oxygen (DO) is a measure of how much oxygen is dissolved in the water - the amount of oxygen available to living aquatic organisms.” It is also a named 2027 monitoring parameter, but the definition comes from USGS, not from the rules table.', 'Use the USGS definition of oxygen dissolved in water. Do not pick a 2027 organism or class title.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'EVIDENCE_MATRIX_2027.md V-U1; T2-USGS-DO. Parameter name V-W5.', '["V-U1","V-W5"]'::jsonb, NULL),
('wq-q34', 'water-quality', 'water-monitoring', 'Two samples of the same water body differ only in temperature. Which sample can hold more dissolved oxygen?', '[{"id":"a","text":"The warmer sample"},{"id":"b","text":"Neither sample; temperature does not affect dissolved oxygen"},{"id":"c","text":"The colder sample"},{"id":"d","text":"Only a sample labeled Class 5 - Air Breathing"}]'::jsonb, 'c', 'multiple-choice', NULL, 'USGS: “Cold water can hold more dissolved oxygen than warm water.” Also: “Warm water holds less dissolved oxygen than cool water.” No milligram-per-liter threshold is used here.', 'USGS compares cold water and warm water. No graph or numeric cutoff is required.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'usgs-water-science-school', 'V-U2 (T2-USGS-DO and T2-USGS-TEMP).', '["V-U2"]'::jsonb, NULL),
('wq-q35', 'water-quality', 'water-monitoring', 'A team wants to compare turbidity at two stream sites. Which procedure makes the comparison fairest?', '[{"id":"a","text":"Collect equal-volume samples at comparable depths and times, then use the same test method."},{"id":"b","text":"Collect one sample from the surface at one site and a bottom sample at the other using different tests."},{"id":"c","text":"Choose whichever sample looks clearest and record only that result."},{"id":"d","text":"Change the sample volume at each site until the readings match."}]'::jsonb, 'a', 'multiple-choice', NULL, 'Using comparable depths and times, equal sample volumes, and the same test method helps make differences in turbidity more likely to reflect the sites rather than the sampling procedure.', 'A fair comparison keeps the sampling conditions and measurement method as similar as possible.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: collecting and interpreting water-quality data.', '["RS18"]'::jsonb, NULL),
('wq-q36', 'water-quality', 'water-monitoring', 'Nitrates are a monitoring parameter. Nitrogen in the form of nitrate is which of the following?', '[{"id":"a","text":"A Class 4 - Pollution Tolerant common name"},{"id":"b","text":"An Aquatic Nuisance Plant"},{"id":"c","text":"A measure of how much oxygen is dissolved in the water"},{"id":"d","text":"A nutrient needed for plant growth"}]'::jsonb, 'd', 'multiple-choice', NULL, 'USGS: “Nitrogen, in the forms of nitrate, nitrite, or ammonium, is a nutrient needed for plant growth.” Dissolved oxygen is a different USGS definition (V-U1). This item does not use ppm or drinking-water cutoffs.', 'USGS describes nitrate as a form of nitrogen used as a plant nutrient. Do not use unsourced concentration limits.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'usgs-water-science-school', 'V-U4; nitrates as a rules name V-W7.', '["V-U4","V-W7"]'::jsonb, NULL),
('wq-q37', 'water-quality', 'water-monitoring', 'A water sample has 9 mg/L of dissolved oxygen before microorganisms decompose organic matter and 4 mg/L afterward. What is the oxygen demand shown by this change?', '[{"id":"a","text":"5 mg/L"},{"id":"b","text":"13 mg/L"},{"id":"c","text":"4 mg/L"},{"id":"d","text":"9 mg/L"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The oxygen demand shown is 9 − 4 = 5 mg/L. Microorganisms used that amount of oxygen while decomposing organic matter, which is the idea behind biochemical oxygen demand.', 'Find the oxygen decrease by subtracting the later dissolved-oxygen value from the earlier value.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: biochemical oxygen demand and relationships among parameters.', '["RS18","V-W8"]'::jsonb, NULL),
('wq-q38', 'water-quality', 'water-monitoring', 'What can too much phosphate in water do?', '[{"id":"a","text":"Increase nutrient levels that can speed up eutrophication"},{"id":"b","text":"Replace salinity on the 2027 eight-parameter list"},{"id":"c","text":"Increase dissolved oxygen without limit"},{"id":"d","text":"Prove that every listed macroinvertebrate needs the same pH"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Phosphate is a form of phosphorus nutrient. Too much phosphate can contribute to eutrophication, in which excess growth and decomposition can reduce dissolved oxygen. Phosphates are one of the 2027 monitoring parameters.', 'Phosphate is a nutrient, and too much nutrient input can cause excessive growth.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Water Monitoring and Analysis scope: phosphates, nutrient cycling, and aquatic-ecology implications.', '["RS18","V-W3"]'::jsonb, NULL),
('wq-q39', 'water-quality', 'water-monitoring', 'Salinity is a monitoring parameter. Water that is saline contains which of the following?', '[{"id":"a","text":"Only Class 5 - Air Breathing organisms"},{"id":"b","text":"Significant amounts (concentrations) of dissolved salts, the most common being sodium chloride (NaCl)"},{"id":"c","text":"No dissolved salts at any concentration"},{"id":"d","text":"Purple Loosestrife as a required dissolved mineral"}]'::jsonb, 'b', 'multiple-choice', NULL, 'USGS: “Water that is saline contains significant amounts (referred to as ‘concentrations’) of dissolved salts, the most common being … sodium chloride (NaCl).” Freshwater/ocean ppm bands from that page are not used in this MVP item.', 'USGS defines saline water using dissolved salts. Do not use parts-per-million classification bands.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'usgs-water-science-school', 'V-U6; parameter name V-W1. No ppm bands.', '["V-U6","V-W1"]'::jsonb, NULL),
('wq-q40', 'water-quality', 'water-monitoring', 'What does biochemical oxygen demand (BOD) represent?', '[{"id":"a","text":"The official 2027 title of Class 2 - Moderately Sensitive"},{"id":"b","text":"An Aquatic Nuisance Animals string"},{"id":"c","text":"How much oxygen is dissolved in the water available to living aquatic organisms"},{"id":"d","text":"The amount of oxygen consumed by bacteria and other microorganisms while they decompose organic matter under aerobic conditions at a specified temperature"}]'::jsonb, 'd', 'multiple-choice', NULL, 'USGS: “Biochemical oxygen demand (BOD) represents the amount of oxygen consumed by bacteria and other microorganisms while they decompose organic matter under aerobic (oxygen is present) conditions at a specified temperature.” Dissolved oxygen’s definition is V-U1, a different claim. No 5-day/20 °C method details are tested.', 'BOD is about oxygen used while microbes break down organic matter. That is not the same sentence USGS uses for dissolved oxygen.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'usgs-water-science-school', 'V-U7 vs V-U1; parameter name V-W8.', '["V-U7","V-U1","V-W8"]'::jsonb, NULL);

create index if not exists water_quality_questions_topic_id_idx on public.water_quality_questions (topic_id);
create index if not exists water_quality_questions_verification_status_idx on public.water_quality_questions (verification_status);

-- crime_busters_questions: 50 rows

create table if not exists public.crime_busters_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint crime_busters_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint crime_busters_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.crime_busters_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('cb-q1', 'crime-busters', 'fingerprints', 'Name the three main fingerprint pattern families.', '[{"id":"a","text":"Waves, spirals, and tents"},{"id":"b","text":"Loops, Whorls, and Arches"},{"id":"c","text":"Cores, deltas, and ridges"},{"id":"d","text":"Ulnar, Radial, and Accidental"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The rules name Loops, Whorls, and Arches as the fundamental patterns. Ulnar and Radial are loop subtypes; Accidental is a whorl subtype.', 'Use the three family headings in the Fingerprint Analysis section, not the subtype lists.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md Fingerprint Analysis; V-P1–V-P3.', '["V-P1","V-P2","V-P3"]'::jsonb, NULL),
('cb-q2', 'crime-busters', 'fingerprints', 'Name the subtype names listed under Loops.', '[{"id":"a","text":"Ulnar, Radial, and Central Pocket"},{"id":"b","text":"Plain, Accidental, and Double Loop"},{"id":"c","text":"Plain and Tented"},{"id":"d","text":"Left slant and right slant only"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules print Loops (Ulnar, Radial, Central Pocket). Plain, Accidental, and Double Loop are listed under Whorls. Plain and Tented are listed under Arches.', 'Read the parenthetical list printed beside Loops, not beside Whorls or Arches.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md loop subtypes; V-P4–V-P6. Keep Central Pocket under Loops as printed (HR8).', '["V-P4","V-P5","V-P6"]'::jsonb, NULL),
('cb-q3', 'crime-busters', 'fingerprints', 'Name the subtype names listed under Whorls.', '[{"id":"a","text":"Ulnar, Radial, and Central Pocket"},{"id":"b","text":"Plain and Tented"},{"id":"c","text":"Plain, Accidental, and Double Loop"},{"id":"d","text":"Core, delta, and ridge count"}]'::jsonb, 'c', 'multiple-choice', NULL, 'The rules print Whorls (Plain, Accidental, Double Loop). Ulnar, Radial, and Central Pocket are listed under Loops.', 'Use the parenthetical list printed beside Whorls.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md whorl subtypes; V-P7–V-P9.', '["V-P7","V-P8","V-P9"]'::jsonb, NULL),
('cb-q4', 'crime-busters', 'fingerprints', 'Name the subtype names listed under Arches.', '[{"id":"a","text":"Ulnar and Radial"},{"id":"b","text":"Accidental and Double Loop"},{"id":"c","text":"Central Pocket and Plain"},{"id":"d","text":"Plain and Tented"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The rules print Arches (Plain, Tented). Ulnar and Radial are loop subtypes; Accidental and Double Loop are whorl subtypes.', 'Use the parenthetical list printed beside Arches.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md arch subtypes; V-P10, V-P11.', '["V-P10","V-P11"]'::jsonb, NULL),
('cb-q5', 'crime-busters', 'fingerprints', 'During a Crime Busters investigation, which comparison is explicitly part of Fingerprint Analysis?', '[{"id":"a","text":"Compare crime-scene prints with prints from the suspects"},{"id":"b","text":"Compare the crime-scene print with the soil pH only"},{"id":"c","text":"Compare the suspect list with the fiber list"},{"id":"d","text":"Compare the powder formulas with the fingerprint families"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules explicitly require students to identify and compare fingerprints from the crime scene with those of the suspects. The other comparisons are not the stated fingerprint task.', 'Look at the first numbered skill under Fingerprint Analysis.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Fingerprint Analysis §1.1; RS3.', '["RS3"]'::jsonb, NULL),
('cb-q6', 'crime-busters', 'fingerprints', 'Loops that flow toward the little finger are called what?', '[{"id":"a","text":"Ulnar loops"},{"id":"b","text":"Radial loops"},{"id":"c","text":"Plain arches"},{"id":"d","text":"Double loops"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The handbook says loops that flow in the direction of the ulna bone (toward the little finger) are ulnar loops. Radial loops flow toward the radius bone.', 'The handbook ties each loop name to a forearm bone and a direction of ridge flow.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'fbi-handbook', 'FBI Science of Fingerprints; E-CB-004.', '["E-CB-004"]'::jsonb, NULL),
('cb-q7', 'crime-busters', 'fingerprints', 'The terms radial and ulnar for fingerprint loops are derived from which bones?', '[{"id":"a","text":"Tibia and fibula"},{"id":"b","text":"Radius and ulna of the forearm"},{"id":"c","text":"Carpals and metacarpals"},{"id":"d","text":"Clavicle and scapula"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The handbook states that the terms radial and ulnar are derived from the radius and ulna bones of the forearm.', 'The handbook derives the two loop names from bones, not from the lower leg or shoulder girdle.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'fbi-handbook', 'E-CB-004.', '["E-CB-004"]'::jsonb, NULL),
('cb-q8', 'crime-busters', 'fingerprints', 'In a loop pattern, ridges enter one side, recurve, and then do what?', '[{"id":"a","text":"Stop at the core without exiting"},{"id":"b","text":"Make a complete circuit with two deltas"},{"id":"c","text":"Pass out upon the same side the ridges entered"},{"id":"d","text":"Flow out the opposite side with a wave in the center"}]'::jsonb, 'c', 'multiple-choice', NULL, 'NIST defines a loop as ridges that enter upon one side, recurve, touch or pass an imaginary line between delta and core, and pass out upon the same side the ridges entered. Flowing out the other side with a wave describes a plain arch.', 'Use the full NIST loop definition, including what happens after the ridges recurve.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'nist', 'E-CB-002; contrast E-CB-005.', '["E-CB-002","E-CB-005"]'::jsonb, NULL),
('cb-q9', 'crime-busters', 'fingerprints', 'How is a plain arch described?', '[{"id":"a","text":"Ridges enter one side, recurve, and exit the same side"},{"id":"b","text":"Two separate loop formations with two cores and two deltas"},{"id":"c","text":"At least two deltas with a recurve in front of each"},{"id":"d","text":"Ridges enter one side and flow out the other with a rise or wave in the center"}]'::jsonb, 'd', 'multiple-choice', NULL, 'NIST: plain arches have ridges which enter on one side of the impression and flow out the other with a rise or wave in the center.', 'Use the NIST sentence for plain arches, not the sentences for loops or whorls.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'nist', 'E-CB-005.', '["E-CB-005"]'::jsonb, NULL),
('cb-q10', 'crime-busters', 'fingerprints', 'A tented arch may look similar to a loop except that it lacks one of which three loop requirements?', '[{"id":"a","text":"Ink, paper, and pressure"},{"id":"b","text":"Recurve, delta, or ridge count"},{"id":"c","text":"Core, shoulder, and type line"},{"id":"d","text":"Ulnar flow, radial flow, or a pocket"}]'::jsonb, 'b', 'multiple-choice', NULL, 'NIST states that tented arches may be similar to a loop, except that they lack one of the three requirements (recurve, delta, or ridge count).', 'A tented arch can look like a loop but is missing one of three loop requirements, not a printing condition.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'nist', 'E-CB-006.', '["E-CB-006"]'::jsonb, NULL),
('cb-q11', 'crime-busters', 'fingerprints', 'Which pair is identified by NIST as fingerprint minutiae in the inspected source?', '[{"id":"a","text":"Ridge endings and bifurcations"},{"id":"b","text":"Cores and ink pressure"},{"id":"c","text":"Loops and whorls"},{"id":"d","text":"Skin and hair follicles"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The inspected NIST source identifies ridge endings and bifurcations as minutiae. A bifurcation is where one ridge splits into two; the source does not establish the other choices as this pair.', 'Choose the two major ridge features named in the minutiae source.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'nist', 'NIST AFIS training — Minutiae; E-CB-013, E-CB-014.', '["E-CB-013","E-CB-014"]'::jsonb, NULL),
('cb-q12', 'crime-busters', 'fingerprints', 'Fingerprints form in a growing fetus where cells of the stratum basale meet what?', '[{"id":"a","text":"The hypodermis only"},{"id":"b","text":"The nails and hair follicles"},{"id":"c","text":"The papillae of the underlying dermal layer (papillary layer)"},{"id":"d","text":"The stratum corneum surface only"}]'::jsonb, 'c', 'multiple-choice', NULL, 'OpenStax: fingerprints form where the cells of the stratum basale meet the papillae of the underlying dermal layer (papillary layer). The same chapter says the two main skin layers are epidermis and dermis.', 'Think about where the stratum basale meets the dermis.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'openstax', 'OpenStax A&P §5.1; E-CB-017, E-CB-016.', '["E-CB-017","E-CB-016"]'::jsonb, NULL),
('cb-q13', 'crime-busters', 'hair-fiber', 'Which five hair sources should you be able to distinguish in this event?', '[{"id":"a","text":"Human, dog, cat, squirrel, and mouse"},{"id":"b","text":"Human, horse, cow, sheep, and goat"},{"id":"c","text":"Dog, cat, rabbit, deer, and fox"},{"id":"d","text":"Human, dog, cat, bird, and fish"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules name human, dog, cat, squirrel, and mouse hair. Other mammals are not on that closed list.', 'Use the five sources named in Hair/Fiber Analysis. Do not add unlisted animals.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-H1–V-H5. Image ID is deferred; this item is list literacy only.', '["V-H1","V-H2","V-H3","V-H4","V-H5"]'::jsonb, NULL),
('cb-q14', 'crime-busters', 'hair-fiber', 'The hair shaft is made of which three layers?', '[{"id":"a","text":"Epidermis, dermis, and hypodermis"},{"id":"b","text":"Cuticle, cortex, and medulla"},{"id":"c","text":"Root, follicle, and papilla"},{"id":"d","text":"Scale, pigment, and keratin only"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The DOJ document states that the shaft is made of three layers called the cuticle, cortex, and medulla.', 'The document compares the shaft to three layers from outside to center.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'doj-hair', 'E-CB-019.', '["E-CB-019"]'::jsonb, NULL),
('cb-q15', 'crime-busters', 'hair-fiber', 'How is the human hair medulla typically described relative to shaft width?', '[{"id":"a","text":"Always absent"},{"id":"b","text":"Always more than one-half the shaft width"},{"id":"c","text":"Less than one-third the width of the shaft, with an amorphous irregular appearance"},{"id":"d","text":"Exactly one-half the shaft width with a ladder pattern in every hair"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Table 1 describes the human medulla as less than one-third the width of the shaft with an amorphous irregular appearance. Animal hair is often greater than one-third with a defined structure. That does not identify dog versus cat versus squirrel versus mouse.', 'The table contrasts a human fraction of shaft width with a typical animal fraction.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'doj-hair', 'E-CB-020.', '["E-CB-020"]'::jsonb, NULL),
('cb-q16', 'crime-busters', 'hair-fiber', 'Which cuticle description matches human hair?', '[{"id":"a","text":"Spinous scales that always look like flower petals"},{"id":"b","text":"A wide range of repeating crown-like patterns along the shaft"},{"id":"c","text":"Coronal scales only, never flattened"},{"id":"d","text":"Imbricate (no repeating pattern), flattened scales, relatively smooth along the shaft"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Human cuticle: imbricate (no repeating pattern), flattened scales, similar along the length of the shaft and relatively smooth. Animal hair is described as having a wide range of scale patterns.', 'Use the human row of the DOJ cuticle column, not the animal row.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'doj-hair', 'E-CB-021.', '["E-CB-021"]'::jsonb, NULL),
('cb-q17', 'crime-busters', 'hair-fiber', 'Which six fibers should you be able to tell apart in this event?', '[{"id":"a","text":"Wool, acrylic, spandex, hemp, jute, and acetate"},{"id":"b","text":"Cotton, linen, silk, nylon, rayon, and polyester"},{"id":"c","text":"Cotton, wool, silk, nylon, Kevlar, and fiberglass"},{"id":"d","text":"Linen, silk, wool, cashmere, mohair, and alpaca"}]'::jsonb, 'b', 'multiple-choice', NULL, 'The closed fiber-name list is cotton, linen, silk, nylon, rayon, and polyester.', 'Use the six names printed under Hair/Fiber Analysis.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-F4–V-F9.', '["V-F4","V-F5","V-F6","V-F7","V-F8","V-F9"]'::jsonb, NULL),
('cb-q18', 'crime-busters', 'hair-fiber', 'Fibers are grouped into which three classes?', '[{"id":"a","text":"Animal, vegetable, and synthetic"},{"id":"b","text":"Natural, manufactured, and mineral"},{"id":"c","text":"Plant, protein, and plastic"},{"id":"d","text":"Organic, inorganic, and blended"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules ask students to identify differences between animal, vegetable, and synthetic fibers. This item is list literacy only; it does not assign each named fiber to a class.', 'Use the three class words in the rules sentence about microscopic images, not FTC labeling terms.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-F1–V-F3. Class mapping of rayon/nylon/polyester is HR-FIB.', '["V-F1","V-F2","V-F3"]'::jsonb, NULL),
('cb-q19', 'crime-busters', 'hair-fiber', 'Which name is not one of the six fibers you should distinguish in this event?', '[{"id":"a","text":"Rayon"},{"id":"b","text":"Polyester"},{"id":"c","text":"Acrylic"},{"id":"d","text":"Linen"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Cotton, linen, silk, nylon, rayon, and polyester are listed. Acrylic is not on that list.', 'Compare each option with the printed six-name list.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'V-F4–V-F9.', '["V-F4","V-F5","V-F6","V-F7","V-F8","V-F9"]'::jsonb, NULL),
('cb-q20', 'crime-busters', 'hair-fiber', 'Cotton fibrils are almost entirely which carbohydrate?', '[{"id":"a","text":"Sucrose"},{"id":"b","text":"Starch"},{"id":"c","text":"Glycogen"},{"id":"d","text":"Cellulose"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The LibreTexts page states that cotton fibrils and filter paper are almost entirely cellulose (about 95%), and that cellulose is a fibrous carbohydrate found in all plants. This does not assign every official fiber to animal, vegetable, or synthetic.', 'Think about cotton fibrils, not the names of storage sugars.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'libretexts', 'E-CB-024.', '["E-CB-024"]'::jsonb, NULL),
('cb-q21', 'crime-busters', 'soil', 'Which six soil types should you be able to identify from samples in this event?', '[{"id":"a","text":"Peaty, Loamy, Sandy, Clay, Chalky, and Silty"},{"id":"b","text":"Sand, silt, clay, gravel, loam, and bedrock"},{"id":"c","text":"Histosol, Mollisol, Alfisol, Aridisol, Spodosol, and Oxisol"},{"id":"d","text":"Topsoil, subsoil, parent material, peat, chalk, and humus"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The closed list is Peaty, Loamy, Sandy, Clay, Chalky, and Silty. USDA taxonomy names and unofficial garden nicknames are not that list.', 'Use the six adjectives printed under Soil Analysis.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-S1–V-S6.', '["V-S1","V-S2","V-S3","V-S4","V-S5","V-S6"]'::jsonb, NULL),
('cb-q22', 'crime-busters', 'soil', 'How are loams typically described in the inspected soil source?', '[{"id":"a","text":"As mixtures of clay, sand, and silt that avoid the extremes of each"},{"id":"b","text":"As soils made only of peat and leaf mould"},{"id":"c","text":"As soils that are always alkaline because they contain lime"},{"id":"d","text":"As soils with no mineral particles and no moisture"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The RHS source describes loams as mixtures of clay, sand, and silt that avoid the extremes of each type. The official rules use the related event-list name Loamy.', 'Think of a balanced mixture rather than one extreme soil property.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rhs-soil', 'RHS Soil types; E-CB-029. Official event spelling: Loamy (V-S2).', '["E-CB-029","V-S2"]'::jsonb, NULL),
('cb-q23', 'crime-busters', 'soil', 'How are clay soils typically described?', '[{"id":"a","text":"Light, dry, warm, and low in nutrients"},{"id":"b","text":"Very high in organic matter and seldom found in gardens"},{"id":"c","text":"Heavy, high in nutrients, wet and cold in winter and baked dry in summer"},{"id":"d","text":"Always acidic and unable to hold any water"}]'::jsonb, 'c', 'multiple-choice', NULL, 'RHS: clay soils are heavy, high in nutrients, wet and cold in winter and baked dry in summer. Light, dry, and low in nutrients describes sandy soils on that page.', 'RHS contrasts clay with sandy soils on weight, wetness, and summer behavior.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rhs-soil', 'E-CB-026; contrast E-CB-027.', '["E-CB-026"]'::jsonb, NULL),
('cb-q24', 'crime-busters', 'soil', 'How are sandy soils typically described?', '[{"id":"a","text":"Heavy and slow to drain"},{"id":"b","text":"Sticky when wet and easy to roll into a long sausage"},{"id":"c","text":"Very alkaline because they are made of lime"},{"id":"d","text":"Light, dry, warm, low in nutrients, and often acidic"}]'::jsonb, 'd', 'multiple-choice', NULL, 'RHS: sandy soils are light, dry, warm, low in nutrients and often acidic. Heavy, sticky, rollable soil is the clay description on that page.', 'RHS calls sandy soils light soils and notes they often drain and warm quickly.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rhs-soil', 'E-CB-027.', '["E-CB-027"]'::jsonb, NULL),
('cb-q25', 'crime-busters', 'soil', 'How are peat soils typically described?', '[{"id":"a","text":"Very high in organic matter and moisture"},{"id":"b","text":"Made mostly of visible white chalk stones only"},{"id":"c","text":"A perfect equal mix of sand, silt, and clay with no organic matter"},{"id":"d","text":"Always the most alkaline garden soil"}]'::jsonb, 'a', 'multiple-choice', NULL, 'RHS: peat soils are very high in organic matter and moisture. Alkaline, lime-rich language on that page belongs to chalky soils.', 'RHS emphasizes organic matter and water-holding, not lime.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rhs-soil', 'E-CB-030. Official list name is Peaty.', '["E-CB-030","V-S1"]'::jsonb, NULL),
('cb-q26', 'crime-busters', 'soil', 'Chalky soils are very alkaline and also contain what?', '[{"id":"a","text":"Only peat and leaf mould"},{"id":"b","text":"Calcium carbonate or lime"},{"id":"c","text":"No mineral particles at all"},{"id":"d","text":"Table salt as the main solid"}]'::jsonb, 'b', 'multiple-choice', NULL, 'RHS: chalky soils also contain calcium carbonate or lime and are very alkaline. That soil-type name is not the same contest item as the powder Calcium carbonate (Chalk).', 'RHS links chalky soils with lime-rich chemistry, not with table salt.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rhs-soil', 'E-CB-031; HR4.', '["E-CB-031","V-S5"]'::jsonb, NULL),
('cb-q27', 'crime-busters', 'soil', 'Chalky soil and chalk powder (calcium carbonate) both appear in this event. What is true?', '[{"id":"a","text":"They are the same item and always share one answer"},{"id":"b","text":"They are two different listed items: a soil type and a powder"},{"id":"c","text":"They are USDA texture classes with published sand percentages"},{"id":"d","text":"They are liquids identified only with pH strips"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Chalky is a soil type. Calcium carbonate (Chalk) is a powder on the chemical list. The evidence matrix marks merging them as human review (HR4).', 'Check which competition heading each printed name sits under.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'V-S5 vs V-W7; HR4.', '["V-S5","V-W7"]'::jsonb, NULL),
('cb-q28', 'crime-busters', 'chemical', 'What is the chemical formula for table salt (sodium chloride)?', '[{"id":"a","text":"NaHCO3"},{"id":"b","text":"CaCO3"},{"id":"c","text":"C12H22O11"},{"id":"d","text":"NaCl"}]'::jsonb, 'd', 'multiple-choice', NULL, 'PubChem: sodium chloride is an ionic compound with the formula NaCl and is also called table salt. NaHCO3 is sodium bicarbonate; CaCO3 is calcium carbonate; C12H22O11 is sucrose.', 'Use the molecular formula for sodium chloride / table salt.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'pubchem', 'E-CB-034; V-W1.', '["E-CB-034","V-W1"]'::jsonb, NULL),
('cb-q29', 'crime-busters', 'chemical', 'Table sugar is sucrose. What is its chemical formula?', '[{"id":"a","text":"C12H22O11"},{"id":"b","text":"NaCl"},{"id":"c","text":"H2O2"},{"id":"d","text":"NaClO"}]'::jsonb, 'a', 'multiple-choice', NULL, 'PubChem CID 5988: sucrose has formula C12H22O11 and lists Table sugar among synonyms. This item treats contest “Sugar” as sucrose only when named as table sugar/sucrose.', 'Use the molecular formula for sucrose.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'pubchem', 'E-CB-035; HR-SUGAR.', '["E-CB-035","V-W2"]'::jsonb, NULL),
('cb-q30', 'crime-busters', 'chemical', 'What is the chemical formula for sodium bicarbonate (baking soda)?', '[{"id":"a","text":"NaCl"},{"id":"b","text":"NaHCO3"},{"id":"c","text":"CaCO3"},{"id":"d","text":"H2O"}]'::jsonb, 'b', 'multiple-choice', NULL, 'PubChem CID 516892 uses molecular formula NaHCO3 for sodium bicarbonate.', 'Use the molecular formula for sodium bicarbonate.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'pubchem', 'E-CB-036; V-W5.', '["E-CB-036","V-W5"]'::jsonb, NULL),
('cb-q31', 'crime-busters', 'chemical', 'What is the chemical formula for calcium carbonate, also listed as chalk powder?', '[{"id":"a","text":"NaHCO3"},{"id":"b","text":"NaCl"},{"id":"c","text":"CaCO3"},{"id":"d","text":"C12H22O11"}]'::jsonb, 'c', 'multiple-choice', NULL, 'PubChem: calcium carbonate has formula CaCO3 and is discussed as chalk. That powder name is separate from soil type Chalky.', 'Use the molecular formula for calcium carbonate.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'pubchem', 'E-CB-037; V-W7.', '["E-CB-037","V-W7"]'::jsonb, NULL),
('cb-q32', 'crime-busters', 'chemical', 'What is the molecular formula for hydrogen peroxide?', '[{"id":"a","text":"H2O"},{"id":"b","text":"CH3COOH"},{"id":"c","text":"NaClO"},{"id":"d","text":"H2O2"}]'::jsonb, 'd', 'multiple-choice', NULL, 'PubChem CID 784 lists H2O2. The 2027 liquid name includes the qualifier (3%), which is a rules string, not a PubChem bottle assay.', 'The peroxide record is not the same formula as water.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'pubchem', 'E-CB-042; V-L3.', '["E-CB-042","V-L3"]'::jsonb, NULL),
('cb-q33', 'crime-busters', 'chemical', 'What is one common use of sodium bicarbonate (baking soda)?', '[{"id":"a","text":"Ingredient of baking powder and a source of carbon dioxide"},{"id":"b","text":"The only official Crime Busters chromatography solvent"},{"id":"c","text":"A substitute for iodine in starch tests"},{"id":"d","text":"The formula for liquid bleach"}]'::jsonb, 'a', 'multiple-choice', NULL, 'PubChem: sodium bicarbonate is used as a source of carbon dioxide and as an ingredient of baking powder (among other uses). That is not a complete contest “uses of every powder” table.', 'Look for baking-powder and carbon-dioxide language, not contest reagents.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'pubchem', 'E-CB-036.', '["E-CB-036"]'::jsonb, NULL),
('cb-q34', 'crime-busters', 'chemical', 'Name one sourced use of calcium carbonate besides industrial uses.', '[{"id":"a","text":"A bleach active ingredient"},{"id":"b","text":"An antacid"},{"id":"c","text":"Rubbing alcohol"},{"id":"d","text":"A pH-strip dye"}]'::jsonb, 'b', 'multiple-choice', NULL, 'PubChem: calcium carbonate is therapeutically used as a food additive, a dietary supplement, an antacid, and a phosphate binder.', 'Think about therapeutic uses of calcium carbonate, such as settling an upset stomach.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'pubchem', 'E-CB-038.', '["E-CB-038"]'::jsonb, NULL),
('cb-q35', 'crime-busters', 'chemical', 'In an iodine test for starch, a positive result is which color change?', '[{"id":"a","text":"The mixture stays yellow-brown and that means starch is present"},{"id":"b","text":"The mixture turns brick red after boiling with Benedict’s reagent"},{"id":"c","text":"A bluish black color"},{"id":"d","text":"Immediate fizzing of carbon dioxide gas"}]'::jsonb, 'c', 'multiple-choice', NULL, 'LibreTexts: a bluish black color is a positive test for starch; a yellowish-brown color (no color change) is negative. That does not uniquely identify flour versus cornstarch, which can both contain starch.', 'The iodine test is a color change without boiling. Fizzing is a different reaction family.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'libretexts', 'E-CB-041.', '["E-CB-041"]'::jsonb, NULL),
('cb-q36', 'crime-busters', 'chemical', 'When a carbonate reacts with an acid, it forms a salt, water, and which gas?', '[{"id":"a","text":"Oxygen"},{"id":"b","text":"Ammonia"},{"id":"c","text":"Chlorine"},{"id":"d","text":"Carbon dioxide"}]'::jsonb, 'd', 'multiple-choice', NULL, 'LibreTexts OpenStax remix: carbonates react with acids to form salts of the metal, gaseous carbon dioxide, and water. Example: CaCO3 + 2 HCl → CaCl2 + CO2 + H2O. Hydrogen carbonates also form CO2 with acids, so this test alone does not uniquely identify chalk versus baking soda.', 'Carbonates plus acid make a salt, water, and a gas.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'libretexts', 'E-CB-039, E-CB-040.', '["E-CB-039","E-CB-040"]'::jsonb, NULL),
('cb-q37', 'crime-busters', 'chemical', 'Powder tests in this event provide which three materials?', '[{"id":"a","text":"Iodine, HCl, and distilled water"},{"id":"b","text":"Benedict’s reagent, limewater, and vinegar"},{"id":"c","text":"Universal indicator, silver nitrate, and flame tests"},{"id":"d","text":"Chromatography paper, acetone, and bleach"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules state that strictly iodine, HCl, and distilled water will be provided to perform powder tests. Chromatography pen is supplied separately and is not this three-reagent list.', 'Use the Event Parameters / Chemical Analysis reagent sentence, not a general chemistry lab kit.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md chemical tests; RS11.', '["RS11"]'::jsonb, NULL),
('cb-q38', 'crime-busters', 'chemical', 'Isopropanol sold as about a 70% water solution is which household product on the liquid list?', '[{"id":"a","text":"Lemon juice"},{"id":"b","text":"Rubbing alcohol"},{"id":"c","text":"Vinegar"},{"id":"d","text":"Liquid bleach"}]'::jsonb, 'b', 'multiple-choice', NULL, 'PubChem: sold in 70% aqueous solution as rubbing alcohol. The rules print Rubbing alcohol (isopropyl). The bottle is still a mixture (HR6); this item only matches the named product.', 'Think of the household name for about 70% isopropanol in water.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'pubchem', 'E-CB-043; V-L2.', '["E-CB-043","V-L2"]'::jsonb, NULL),
('cb-q39', 'crime-busters', 'chemical', 'Sodium hypochlorite is commonly found in which listed liquid?', '[{"id":"a","text":"Water"},{"id":"b","text":"Hydrogen peroxide (3%)"},{"id":"c","text":"Liquid bleach"},{"id":"d","text":"Lemon juice"}]'::jsonb, 'c', 'multiple-choice', NULL, 'PubChem: sodium hypochlorite is commonly found in household bleach (formula NaClO on that record). Liquid bleach is still a commercial mixture (HR6).', 'Think of the household product that often contains sodium hypochlorite.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'pubchem', 'E-CB-045; V-L4.', '["E-CB-045","V-L4"]'::jsonb, NULL),
('cb-q40', 'crime-busters', 'safety', 'What is the safety rule for the powders and liquids in this event?', '[{"id":"a","text":"Teams must taste each unknown to confirm identity"},{"id":"b","text":"Only liquids may be tasted; powders may not"},{"id":"c","text":"Unknowns may be eaten if pH is near 7"},{"id":"d","text":"Do not taste or eat them"}]'::jsonb, 'd', 'multiple-choice', NULL, 'The rules include a note: please do not consume the powders/liquids used in this event for testing.', 'Read the printed NOTE under Chemical Analysis.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'V-G6.', '["V-G6"]'::jsonb, NULL),
('cb-q41', 'crime-busters', 'fingerprints', 'What fingerprint pattern is shown?', '[{"id":"a","text":"Loop"},{"id":"b","text":"Whorl"},{"id":"c","text":"Arch"},{"id":"d","text":"Tented arch"}]'::jsonb, 'a', 'multiple-choice', NULL, 'Ridges enter from one side, recurve, and leave on the same side. That is the official Loop family.', 'Watch whether ridges come back out on the same side, make a complete circuit, or rise and leave on the other side.', NULL, NULL, NULL, 1, true, '/crime-busters/cb-q41.jpg', 'Inked fingerprint with ridges that curve and return toward the side they entered.', 'Figure: FBI, The Science of Fingerprints. Public domain.', 'FBI fig. 61. Same-side entry and exit with a recurve; one delta opposite the opening.', 'verified', 'recognition', 'fbi-handbook', 'IM4-L1: FBI Science of Fingerprints fig. 61 (Gutenberg 19022). Loop family E-CB-002; names V-P1.', '["IM4-L1","V-P1","E-CB-002"]'::jsonb, NULL),
('cb-q42', 'crime-busters', 'fingerprints', 'Which fingerprint pattern family is shown here?', '[{"id":"a","text":"Arch"},{"id":"b","text":"Tented arch"},{"id":"c","text":"Loop"},{"id":"d","text":"Whorl"}]'::jsonb, 'c', 'multiple-choice', NULL, 'Ridges enter from one side, recurve, and leave on the same side. That is the official Loop family.', 'Watch whether ridges come back out on the same side, make a complete circuit, or rise and leave on the other side.', NULL, NULL, NULL, 1, true, '/crime-busters/cb-q42.jpg', 'Inked fingerprint with a tight inner curve and ridges leaving toward the side they entered.', 'Figure: FBI, The Science of Fingerprints. Public domain.', 'FBI fig. 62. Same-side entry and exit with a hairpin core; one delta on the opposite side.', 'verified', 'recognition', 'fbi-handbook', 'IM4-L2: FBI Science of Fingerprints fig. 62 (Gutenberg 19022). Loop family E-CB-002; names V-P1.', '["IM4-L2","V-P1","E-CB-002"]'::jsonb, NULL),
('cb-q43', 'crime-busters', 'fingerprints', 'This photographed print belongs to which pattern family?', '[{"id":"a","text":"Arch"},{"id":"b","text":"Whorl"},{"id":"c","text":"Loop"},{"id":"d","text":"Tented arch"}]'::jsonb, 'b', 'multiple-choice', NULL, 'Ridges in the center make a complete circuit, and two deltas sit on either side. That is the official Whorl family.', 'Watch whether ridges come back out on the same side, make a complete circuit, or rise and leave on the other side.', NULL, NULL, NULL, 1, true, '/crime-busters/cb-q43.jpg', 'Close-up fingerprint whose center ridges form a complete circular circuit.', 'Photo: Metrónomo. CC BY-SA 4.0. Wikimedia Commons.', 'Plain whorl photo. Concentric circuit in the core; deltas at lower left and lower right.', 'verified', 'recognition', 'commons', 'IM4-W1: Wikimedia Commons Plain whorl in a right thumbprint.JPG (Metrónomo, CC BY-SA 4.0). Whorl family E-CB-007; names V-P2.', '["IM4-W1","V-P2","E-CB-007"]'::jsonb, NULL),
('cb-q44', 'crime-busters', 'fingerprints', 'Which pattern family is this fingerprint?', '[{"id":"a","text":"Loop"},{"id":"b","text":"Whorl"},{"id":"c","text":"Double loop"},{"id":"d","text":"Arch"}]'::jsonb, 'd', 'multiple-choice', NULL, 'Ridges enter on one side, rise in the center, and flow out the other side. That is the official Arch family.', 'Watch whether ridges come back out on the same side, make a complete circuit, or rise and leave on the other side.', NULL, NULL, NULL, 1, true, '/crime-busters/cb-q44.jpg', 'Close-up fingerprint whose ridges rise in the center and continue toward the opposite side.', 'Photo: Metrónomo. CC BY-SA 4.0. Wikimedia Commons.', 'Tented-arch photo used only as Arch-family ID. Enter one side, central rise, exit the other; no complete circuit.', 'verified', 'recognition', 'commons', 'IM4-A1: Wikimedia Commons Tented arch in a left index fingerprint.jpg (Metrónomo, CC BY-SA 4.0). Arch family E-CB-005; names V-P3. Stem keys the family, not tented vs plain.', '["IM4-A1","V-P3","E-CB-005"]'::jsonb, NULL),
('cb-q45', 'crime-busters', 'overall-analysis', 'Name the four elements required in a final Crime Busters analysis paragraph.', '[{"id":"a","text":"The suspect, the motive, all evidence pieces, and why each piece incriminates the suspect"},{"id":"b","text":"Only the suspect''s name and the fastest test result"},{"id":"c","text":"Only the chemical formulas and the time the team finished"},{"id":"d","text":"The soil type, the team score, and the number of participants"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules require the paragraph to name the suspect, give the motive, name all pieces of evidence, and explain why each piece incriminates the suspect. The other choices leave out required parts or add unrelated logistics.', 'Use every element named in the Overall Analysis rule.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md Overall Analysis; RS14.', '["RS14"]'::jsonb, NULL),
('cb-q46', 'crime-busters', 'fingerprints', 'A crime-scene print and several suspect prints are provided. Which conclusion is supported only after comparing the observable ridge details in the images?', '[{"id":"a","text":"Which suspect''s print matches the crime-scene print"},{"id":"b","text":"Which soil type has the most organic matter"},{"id":"c","text":"Which liquid has the lowest pH"},{"id":"d","text":"Which fiber class is synthetic"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules require students to identify and compare crime-scene fingerprints with suspect fingerprints. The comparison cannot be verified or made live here until appropriate print images are sourced and reviewed.', 'This item requires the missing crime-scene and suspect print stimulus.', NULL, NULL, NULL, 3, true, NULL, NULL, NULL, 'Side-by-side crime-scene and suspect prints with comparable ridge details.', 'needs-review', 'multi-step', 'rules-derived', 'RULES_2027.md Fingerprint Analysis §1.1; RS3; image asset IM1 needed.', '["RS3"]'::jsonb, NULL),
('cb-q47', 'crime-busters', 'fingerprints', 'Which marked feature should a student identify when a fingerprint image shows one ridge splitting into two?', '[{"id":"a","text":"A bifurcation"},{"id":"b","text":"A plain arch"},{"id":"c","text":"A soil horizon"},{"id":"d","text":"A hair medulla"}]'::jsonb, 'a', 'multiple-choice', NULL, 'NIST describes a bifurcation as the location where a ridge starts to split into two. A live version still needs a suitable marked-print image so the student can identify the feature visually.', 'The image must show the marked ridge feature; a text definition alone is not the intended task.', NULL, NULL, NULL, 3, true, NULL, NULL, NULL, 'Fingerprint close-up with a single bifurcation clearly marked.', 'needs-review', 'application', 'nist', 'NIST AFIS training — Minutiae; E-CB-014; image asset IM2 needed.', '["E-CB-014"]'::jsonb, NULL),
('cb-q48', 'crime-busters', 'hair-fiber', 'Which conclusion could a student make from a sourced microscopic hair image showing a narrow, irregular medulla?', '[{"id":"a","text":"It is consistent with the general human-hair description in the inspected source"},{"id":"b","text":"It must be squirrel hair"},{"id":"c","text":"It must be a synthetic fiber"},{"id":"d","text":"It must be a soil sample"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The DOJ source describes human hair as typically having a medulla less than one-third of the shaft width with an amorphous irregular appearance. It does not support identifying dog, cat, squirrel, or mouse from that feature alone.', 'The current source distinguishes human hair from animal hair generally, not among the four animal species.', NULL, NULL, NULL, 3, true, NULL, NULL, NULL, 'Microscopic hair cross-section or shaft view with the medulla-width diagnostic visible.', 'needs-review', 'distinction', 'doj-hair', 'DOJ hair examination documentation; E-CB-020; image asset IM5 needed.', '["E-CB-020"]'::jsonb, NULL),
('cb-q49', 'crime-busters', 'hair-fiber', 'Which fiber conclusion should remain held out until the image diagnostic and class terminology are reviewed?', '[{"id":"a","text":"Mapping one of the six named fibers to animal, vegetable, or synthetic from a micrograph"},{"id":"b","text":"Recognizing that cotton is one of the six listed fibers"},{"id":"c","text":"Recognizing that silk is one of the six listed fibers"},{"id":"d","text":"Recognizing that nylon is one of the six listed fibers"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules require microscopic fiber distinctions, while the available sources do not yet verify all six diagnostics or resolve the event''s animal/vegetable/synthetic terminology. The image and classification evidence must be reviewed before this item can go live.', 'The rules require microscopic distinctions, but the evidence matrix records unresolved class terminology.', NULL, NULL, NULL, 3, true, NULL, NULL, NULL, 'Microscopic fiber comparison showing the diagnostic feature used for classification.', 'needs-review', 'distinction', 'rules-derived', 'RULES_2027.md Hair/Fiber Analysis; RS8; IM6 and HR-FIB.', '["RS8"]'::jsonb, NULL),
('cb-q50', 'crime-busters', 'soil', 'Which soil identification question requires a real sample or reviewed sample image before it can be live?', '[{"id":"a","text":"Which of the six listed soil types matches the observed texture and sample properties"},{"id":"b","text":"Which six soil names are printed in the rules"},{"id":"c","text":"Which soil type is called Loamy in the official list"},{"id":"d","text":"Which soil type is described as sandy in a source"}]'::jsonb, 'a', 'multiple-choice', NULL, 'The rules require identification of the six soil types using provided samples. A live Jr. Explorer item needs a real, reviewed sample image or equivalent stimulus; this bank does not create a placeholder.', 'The competition asks students to identify soil types using provided samples.', NULL, NULL, NULL, 3, true, NULL, NULL, NULL, 'Reviewed soil sample image or equivalent stimulus with observable properties.', 'needs-review', 'multi-step', 'rules-derived', 'RULES_2027.md Soil Analysis; RS9; image asset IM7 needed.', '["RS9"]'::jsonb, NULL);

create index if not exists crime_busters_questions_topic_id_idx on public.crime_busters_questions (topic_id);
create index if not exists crime_busters_questions_verification_status_idx on public.crime_busters_questions (verification_status);

-- codebusters_questions: 40 rows

create table if not exists public.codebusters_questions (
  id text primary key,
  event_id text not null,
  topic_id text not null,
  prompt text not null,
  choices jsonb,
  correct_choice_id text,
  answer_mode text not null default 'multiple-choice',
  accepted_answers jsonb,
  explanation text not null,
  hint text not null,
  hint_2 text,
  prompt_terms jsonb,
  wording_help text,
  difficulty integer not null check (difficulty between 1 and 3),
  image_required boolean,
  image_src text,
  image_alt text,
  image_credit text,
  image_brief text,
  verification_status text,
  cognitive_demand text,
  source_type text,
  source_note text,
  evidence_ids jsonb,
  taxonomy_tags jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint codebusters_questions_answer_mode_check check (answer_mode in ('multiple-choice', 'open-ended')),
  constraint codebusters_questions_verification_status_check check (
    verification_status is null or verification_status in ('draft', 'needs-review', 'verified')
  )
);

insert into public.codebusters_questions (id, event_id, topic_id, prompt, choices, correct_choice_id, answer_mode, accepted_answers, explanation, hint, hint_2, prompt_terms, wording_help, difficulty, image_required, image_src, image_alt, image_credit, image_brief, verification_status, cognitive_demand, source_type, source_note, evidence_ids, taxonomy_tags) values
('cbus-q1', 'codebusters', 'baconian', 'What two symbols does the Baconian cipher use?', '[]'::jsonb, 'A and B', 'open-ended', '["A and B","A/B","a and b"]'::jsonb, 'Baconian uses groups made from two symbols: A and B.', 'The cipher names its two symbols directly.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q2', 'codebusters', 'baconian', 'How many A/B symbols represent one Baconian letter?', '[]'::jsonb, '5', 'open-ended', '["5"]'::jsonb, 'Each Baconian letter is represented by a group of five A/B symbols.', 'Count the symbols in AAAAA, the example for the first letter.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q3', 'codebusters', 'baconian', 'Using AAAAA = A, AAAAB = B, and AAABA = C, what letter does AAABB represent?', '[]'::jsonb, 'D', 'open-ended', '["D"]'::jsonb, 'AAABB is the fourth pattern in the sequence, so it represents D.', 'Continue the five-symbol pattern after AAABA.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q4', 'codebusters', 'baconian', 'Decode the Baconian groups ABBBA AAAAA BAABA. What plaintext do they make?', '[]'::jsonb, 'PAT', 'open-ended', '["PAT"]'::jsonb, 'ABBBA is P, AAAAA is A, and BAABA is T. Together they spell PAT.', 'Decode one group of five symbols at a time.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q5', 'codebusters', 'baconian', 'In the original Baconian alphabet, which pairs are treated as the same letter?', '[]'::jsonb, 'I/J and U/V', 'open-ended', '["I/J and U/V","I and J and U and V","I/J, U/V"]'::jsonb, 'The original Baconian alphabet treats I and J as one letter and U and V as one letter.', 'The original alphabet has 24 letters rather than 26.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q6', 'codebusters', 'baconian', 'A Baconian message contains 17 A/B symbols. What should you do before decoding it into letters?', '[]'::jsonb, 'Group the first 15 symbols and check the remaining 2 as an incomplete group.', 'open-ended', '["Group the first 15 symbols and check the remaining 2 as an incomplete group."]'::jsonb, 'Seventeen symbols make three complete groups of five with two symbols left over. The incomplete group signals that the message needs to be checked before all of it can be decoded.', 'Every decoded letter needs a complete group of five symbols.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q7', 'codebusters', 'baconian', 'Decode the Baconian groups BABAA AAAAA BAAAA ABABB. What plaintext do they make?', '[]'::jsonb, 'WARM', 'open-ended', '["WARM"]'::jsonb, 'BABAA is W, AAAAA is A, BAAAA is R, and ABABB is M. The plaintext is WARM.', 'Decode BABAA, AAAAA, BAAAA, and ABABB separately.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-BACONIAN"]'::jsonb, NULL),
('cbus-q8', 'codebusters', 'porta', 'What does the repeating keyword do in a Porta cipher?', '[]'::jsonb, 'It chooses which substitution alphabet is used at each position.', 'open-ended', '["It chooses which substitution alphabet is used at each position."]'::jsonb, 'In Porta, each plaintext position is matched with a repeating keyword letter, which selects the substitution alphabet for that position.', 'The keyword repeats to match the message length.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q9', 'codebusters', 'porta', 'What is special about Porta decryption?', '[]'::jsonb, 'It uses the exact same reciprocal process as encryption.', 'open-ended', '["It uses the exact same reciprocal process as encryption."]'::jsonb, 'Porta is reciprocal, so the same keyword and substitution process can be used for both encoding and decoding.', 'The rules call the cipher reciprocal.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q10', 'codebusters', 'porta', 'A Porta message has eight letters and uses the keyword KEY. Write the keyword letters aligned with message positions 1 through 8.', '[]'::jsonb, 'K E Y K E Y K E', 'open-ended', '["K E Y K E Y K E","KEYKEYKE","KEY KEY KE"]'::jsonb, 'Repeating KEY across eight positions gives KEYKEYKE.', 'Write KEY repeatedly until it reaches eight positions.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q11', 'codebusters', 'porta', 'When two plaintext letters use the same aligned Porta keyword letter, what should you expect?', '[]'::jsonb, 'They use the same substitution alphabet for those positions.', 'open-ended', '["They use the same substitution alphabet for those positions."]'::jsonb, 'The same keyword letter selects the same Porta substitution alphabet, although different plaintext letters can still encrypt to different ciphertext letters.', 'The keyword selects an alphabet; it does not decide the plaintext letter itself.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q12', 'codebusters', 'porta', 'You know the Porta keyword but not the plaintext. What is the best first step?', '[]'::jsonb, 'Repeat the keyword across the ciphertext and use the matching reference-sheet alphabets.', 'open-ended', '["Repeat the keyword across the ciphertext and use the matching reference-sheet alphabets."]'::jsonb, 'A known Porta keyword lets you align the repeating key and select the correct reference-sheet alphabet at each position.', 'Use the information the cipher requires: the keyword and its alphabets.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q13', 'codebusters', 'porta', 'For this question, use the provided reciprocal alphabet A↔N, B↔O, C↔P, D↔Q, and so on through M↔Z. What is the encryption of BAD?', '[]'::jsonb, 'ONQ', 'open-ended', '["ONQ"]'::jsonb, 'B maps to O, A maps to N, and D maps to Q. The result is ONQ.', 'Apply the provided pairs one letter at a time.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q14', 'codebusters', 'porta', 'A Porta solver uses keyword KEY but shifts the keyword one position before starting. What is the main error?', '[]'::jsonb, 'Every message position is matched with the wrong substitution alphabet.', 'open-ended', '["Every message position is matched with the wrong substitution alphabet."]'::jsonb, 'The keyword letter aligned with each message position selects the substitution alphabet. Starting one position late shifts every selection and can make the whole solution incorrect.', 'Compare the intended alignment KEYKEY... with the shifted alignment.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-PORTA"]'::jsonb, NULL),
('cbus-q15', 'codebusters', 'aristocrat', 'What kind of cipher is an aristocrat?', '[]'::jsonb, 'A substitution cipher using a different letter for each alphabet letter', 'open-ended', '["A substitution cipher using a different letter for each alphabet letter"]'::jsonb, 'An aristocrat replaces each letter of the alphabet with a different letter.', 'Focus on what replaces each plaintext letter.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q16', 'codebusters', 'aristocrat', 'What happens to spaces and punctuation when an aristocrat is encrypted?', '[]'::jsonb, 'They stay in the same positions.', 'open-ended', '["They stay in the same positions."]'::jsonb, 'Aristocrat substitution changes letters, while spaces and punctuation remain as they were.', 'The rules distinguish letters from spaces and punctuation.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q17', 'codebusters', 'aristocrat', 'State the rule that applies to an aristocrat''s letter substitution.', '[]'::jsonb, 'A letter cannot decipher to itself.', 'open-ended', '["A letter cannot decipher to itself."]'::jsonb, 'The 2027 rules state that an aristocrat cannot map a letter to itself.', 'Look for the rule that prevents a letter from keeping its own identity.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q18', 'codebusters', 'aristocrat', 'Use this substitution: M→Q, E→L, T→R, A→X, N→B, O→K. Decode QLLR XR BKKB.', '[]'::jsonb, 'MEET AT NOON', 'open-ended', '["MEET AT NOON","MEETATNOON"]'::jsonb, 'Q L L R reverses to M E E T, X R to A T, and B K K B to N O O N. The plaintext is MEET AT NOON.', 'Reverse each listed pair and keep the spaces.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q19', 'codebusters', 'aristocrat', 'Using A→X, B→Y, C→Z, and D→W, encode the text BAD.', '[]'::jsonb, 'YXW', 'open-ended', '["YXW"]'::jsonb, 'B becomes Y, A becomes X, and D becomes W. BAD becomes YXW.', 'Replace B, then A, then D. Do not insert spaces between letters.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q20', 'codebusters', 'aristocrat', 'An aristocrat hint says Q deciphers to E. What does that tell you?', '[]'::jsonb, 'Every Q in the ciphertext represents E in the plaintext.', 'open-ended', '["Every Q in the ciphertext represents E in the plaintext."]'::jsonb, 'The hint supplies the substitution pair Q→E for every occurrence of Q in the ciphertext.', 'A hint gives a letter-to-letter mapping.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q21', 'codebusters', 'cryptanalysis-strategy', 'In an aristocrat, the ciphertext letter X appears twice. What must be true?', '[]'::jsonb, 'Spaces are encrypted as X.', 'open-ended', '["Spaces are encrypted as X."]'::jsonb, 'In an aristocrat, one ciphertext letter consistently represents one plaintext letter. Therefore both X positions represent the same plaintext letter.', 'A substitution mapping stays consistent throughout one message.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ARISTOCRAT"]'::jsonb, NULL),
('cbus-q22', 'codebusters', 'cryptarithm', 'What does a cryptarithm replace with letters?', '[]'::jsonb, 'Five A/B symbols per letter', 'open-ended', '["Five A/B symbols per letter"]'::jsonb, 'A cryptarithm presents a math puzzle in which digits are replaced by letters. The goal is to determine the digit for each letter.', 'It is described as a math cipher.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q23', 'codebusters', 'cryptarithm', 'In a cryptarithm, A=2 and B=5. What digit must C be if A + B = C?', '[]'::jsonb, '7', 'open-ended', '["7","07"]'::jsonb, '2 + 5 = 7, so C must represent digit 7.', 'Substitute the known digits and add them.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q24', 'codebusters', 'cryptarithm', 'In a cryptarithm, A=9 and B=4. What digit must C be if A − B = C?', '[]'::jsonb, '5', 'open-ended', '["5","05"]'::jsonb, '9 − 4 = 5, so C must represent digit 5.', 'Subtract the second known digit from the first.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q25', 'codebusters', 'cryptarithm', 'A solver adds two cryptarithm columns from right to left. Why might the next column need an extra 1?', '[]'::jsonb, 'The previous column produced a carry.', 'open-ended', '["The previous column produced a carry."]'::jsonb, 'When a column total is 10 or more, the extra ten is carried into the next column as 1.', 'Use the same carrying idea as ordinary addition.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q26', 'codebusters', 'cryptarithm', 'In the equation A + B = C, A=6 and C=9. What digit must B represent?', '[]'::jsonb, '3', 'open-ended', '["3","03"]'::jsonb, '9 − 6 = 3, so B must represent digit 3.', 'Find the missing addend by subtracting A from C.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q27', 'codebusters', 'cryptarithm', 'Solve this addition: A7 + B = C2. If A=3 and B=5, which digit must C represent?', '[]'::jsonb, '4', 'open-ended', '["4","04"]'::jsonb, 'A7 + B becomes 37 + 5 = 42, so C represents digit 4.', 'Substitute A and B, then add 37 and 5.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL),
('cbus-q28', 'codebusters', 'caesar-atbash', 'What operation defines a Caesar cipher?', '[]'::jsonb, 'Shift each letter by the same number of alphabet positions.', 'open-ended', '["Shift each letter by the same number of alphabet positions."]'::jsonb, 'Caesar encryption shifts every letter by a specific number of places down the alphabet.', 'The cipher uses a fixed movement through the alphabet.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q29', 'codebusters', 'caesar-atbash', 'Using a Caesar shift of 3 forward, what does CAT become?', '[]'::jsonb, 'FDW', 'open-ended', '["FDW"]'::jsonb, 'C→F, A→D, and T→W. Therefore CAT becomes FDW.', 'Move C, A, and T forward three places, wrapping only if needed.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q30', 'codebusters', 'caesar-atbash', 'Decode FDW using a Caesar shift of 3 backward.', '[]'::jsonb, 'CAT', 'open-ended', '["CAT"]'::jsonb, 'F→C, D→A, and W→T. The plaintext is CAT.', 'Move F, D, and W backward three places.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q31', 'codebusters', 'caesar-atbash', 'With a Caesar shift of 2 forward, what does YZ become?', '[]'::jsonb, 'AB', 'open-ended', '["AB","A B"]'::jsonb, 'Y shifted two places forward is A, and Z shifted two places forward is B. The result is AB.', 'Continue past Z by wrapping back to A.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q32', 'codebusters', 'caesar-atbash', 'A Caesar ciphertext has no stated shift. What is a reasonable first strategy?', '[]'::jsonb, 'Try possible shifts and look for readable words.', 'open-ended', '["Try possible shifts and look for readable words."]'::jsonb, 'When the shift is not provided, testing possible fixed shifts is a practical way to find the one that produces readable plaintext.', 'A Caesar cipher has a small set of possible fixed shifts.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q33', 'codebusters', 'caesar-atbash', 'A solver decodes FDW by shifting forward 3 and gets I G Z. What should the solver notice?', '[]'::jsonb, 'The direction is wrong; decoding should shift backward 3.', 'open-ended', '["The direction is wrong; decoding should shift backward 3."]'::jsonb, 'If FDW was made by shifting forward 3, decoding requires shifting backward 3, producing CAT. Shifting forward again moves farther from the plaintext.', 'The rules describe decoding as reversing the encoding shift.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CAESAR"]'::jsonb, NULL),
('cbus-q34', 'codebusters', 'caesar-atbash', 'What mapping defines Atbash?', '[]'::jsonb, 'Each letter maps to its opposite in the reversed alphabet.', 'open-ended', '["Each letter maps to its opposite in the reversed alphabet."]'::jsonb, 'Atbash maps the standard alphabet to its exact reverse: A↔Z, B↔Y, and so on.', 'Think of writing the alphabet in one row and its reverse below it.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ATBASH"]'::jsonb, NULL),
('cbus-q35', 'codebusters', 'caesar-atbash', 'Using Atbash, what does CODE become?', '[]'::jsonb, 'XLWV', 'open-ended', '["XLWV"]'::jsonb, 'C→X, O→L, D→W, and E→V. CODE becomes XLWV.', 'Match each letter with its opposite in the alphabet.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ATBASH"]'::jsonb, NULL),
('cbus-q36', 'codebusters', 'caesar-atbash', 'Using Atbash, decode XLWV.', '[]'::jsonb, 'CODE', 'open-ended', '["CODE"]'::jsonb, 'X→C, L→O, W→D, and V→E. The plaintext is CODE.', 'Atbash is reciprocal, so use the same opposite-letter pairs.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'application', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ATBASH"]'::jsonb, NULL),
('cbus-q37', 'codebusters', 'caesar-atbash', 'Give one correct Atbash letter pair.', '[]'::jsonb, 'A↔Z', 'open-ended', '["A↔Z"]'::jsonb, 'Atbash pairs the alphabet from opposite ends, so A pairs with Z.', 'Pair the first letter with the last, then continue inward.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recognition', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ATBASH"]'::jsonb, NULL),
('cbus-q38', 'codebusters', 'cryptanalysis-strategy', 'What clue best separates Atbash from a Caesar cipher when the method is unknown?', '[]'::jsonb, 'Atbash always uses fixed opposite-letter pairs, while Caesar uses one fixed shift.', 'open-ended', '["Atbash always uses fixed opposite-letter pairs, while Caesar uses one fixed shift."]'::jsonb, 'Atbash uses the reversed alphabet, while Caesar uses a constant shift amount. Those are different substitution patterns.', 'Compare the rule used to choose the replacement letter.', NULL, NULL, NULL, 2, false, NULL, NULL, NULL, NULL, 'verified', 'distinction', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-ATBASH"]'::jsonb, NULL),
('cbus-q39', 'codebusters', 'cryptanalysis-strategy', 'For how long can a team earn bonus points on the timed aristocrat?', '[]'::jsonb, 'Until ten minutes have elapsed', 'open-ended', '["Until ten minutes have elapsed"]'::jsonb, 'The timed aristocrat can earn bonus points only before ten minutes have elapsed. After that, it still counts as a standard question.', 'The rules give a specific time limit for bonus eligibility.', NULL, NULL, NULL, 1, false, NULL, NULL, NULL, NULL, 'verified', 'recall', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-COMPETITION"]'::jsonb, NULL),
('cbus-q40', 'codebusters', 'cryptarithm', 'Solve this final-column cryptarithm step: A + B + 1 carry = 10. If A=4, which digit must B represent?', '[]'::jsonb, '5', 'open-ended', '["5","05"]'::jsonb, 'Subtract 4 and the carry 1 from 10: B = 10 − 4 − 1 = 5.', 'Write the equation as 4 + B + 1 = 10.', NULL, NULL, NULL, 3, false, NULL, NULL, NULL, NULL, 'verified', 'multi-step', 'rules-derived', 'RULES_2027.md CIPHERS section.', '["CB-RULES-CRYPTARITHM"]'::jsonb, NULL);

create index if not exists codebusters_questions_topic_id_idx on public.codebusters_questions (topic_id);
create index if not exists codebusters_questions_verification_status_idx on public.codebusters_questions (verification_status);
